INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(1,1,'Briefing vidéo : le métier d''analyste','video','<p>Ce briefing visuel présente en quelques minutes les notions clés de la formation : la différence entre information et renseignement, le cycle de production et les exigences éthiques du métier. Il ne comporte pas de narration : prenez le temps de lire chaque écran.</p>',NULL,1,4,1,1),
(2,1,'Qu''est-ce que le renseignement ?','text','<p>Le renseignement est <strong>une information élaborée pour éclairer une décision</strong>. Il se définit moins par la nature de ses sources que par sa finalité : réduire l''incertitude d''un décideur (chef d''État, dirigeant d''entreprise, responsable de la sécurité d''une organisation) face à une situation qui le concerne.</p>\n<h3>Trois niveaux à ne pas confondre</h3>\n<table><thead><tr><th>Niveau</th><th>Définition</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Donnée / information</td><td>Fait brut, non évalué</td><td>« Un convoi de camions a été vu près de la frontière. »</td></tr>\n<tr><td>Renseignement</td><td>Information évaluée, recoupée, interprétée pour un besoin précis</td><td>« Le convoi correspond probablement à une rotation logistique saisonnière ; aucun indice de menace (confiance modérée). »</td></tr>\n<tr><td>Connaissance</td><td>Savoir accumulé et structuré dans la durée</td><td>Base documentaire sur les flux commerciaux transfrontaliers de la région.</td></tr>\n</tbody></table>\n<h3>Les trois niveaux de décision</h3>\n<ul>\n<li><strong>Stratégique</strong> : grandes orientations, horizon de plusieurs années (stabilité régionale, dépendances économiques).</li>\n<li><strong>Opérationnel</strong> : conduite d''un ensemble d''actions sur une zone ou un secteur.</li>\n<li><strong>Tactique</strong> : décision immédiate, sur le terrain ou en situation de crise.</li>\n</ul>\n<h3>Le cycle du renseignement</h3>\n<p>La production suit un cycle classique en cinq phases, qui structure tout le reste du parcours :</p>\n<ol>\n<li><strong>Orientation</strong> : le décideur exprime un besoin ; l''analyste le traduit en questions précises (<em>besoins en renseignement</em>).</li>\n<li><strong>Collecte</strong> : recherche d''informations par des moyens légaux et adaptés.</li>\n<li><strong>Exploitation</strong> : tri, traduction, mise en forme, évaluation des sources.</li>\n<li><strong>Analyse</strong> : interprétation, recoupement, formulation de jugements avec un niveau de confiance.</li>\n<li><strong>Diffusion</strong> : livraison d''un produit clair au bon destinataire, au bon moment, puis retour d''expérience.</li>\n</ol>\n<div class="callout"><strong>À retenir.</strong> Un renseignement exact mais livré trop tard ou au mauvais destinataire n''a aucune valeur. La pertinence et le délai font partie de la qualité.</div>\n<h3>Ce que le renseignement n''est pas</h3>\n<p>Le renseignement n''est ni de la surveillance indiscriminée, ni de la propagande, ni une activité au-dessus des lois. Dans un État de droit, il s''exerce dans un cadre légal, sous contrôle, avec des finalités définies. C''est ce cadre qui garantit sa légitimité et, à terme, son efficacité.</p>',NULL,NULL,20,1,2),
(3,1,'Approfondissement : besoins en renseignement et produits','text','<p>Le cycle ne démarre vraiment qu''avec un <strong>besoin en renseignement</strong> bien formulé. Les services distinguent généralement trois niveaux de besoins, du plus large au plus précis.</p>\n<table><thead><tr><th>Niveau</th><th>Formulation</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Priorité</td><td>Grand thème fixé par le décideur</td><td>Stabilité des corridors logistiques régionaux</td></tr>\n<tr><td>Besoin en renseignement</td><td>Question analytique</td><td>Quels facteurs pourraient perturber le corridor Abidjan-Ouagadougou dans les six mois ?</td></tr>\n<tr><td>Élément d''information</td><td>Fait observable à collecter</td><td>Évolution des délais de passage aux postes frontières</td></tr>\n</tbody></table>\n<h3>Les principaux types de produits</h3>\n<ul>\n<li><strong>Note de situation</strong> : ce qui se passe maintenant, diffusée rapidement.</li>\n<li><strong>Note d''analyse</strong> : pourquoi cela se passe, quelles conséquences.</li>\n<li><strong>Évaluation prospective</strong> : scénarios à moyen terme, indicateurs à surveiller.</li>\n<li><strong>Alerte</strong> : signal d''un changement imminent nécessitant une décision.</li>\n</ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un besoin flou produit une collecte inutile.</li><li>Chaque produit répond à un horizon temporel et à un lecteur précis.</li><li>Le retour du décideur (feedback) améliore le cycle suivant.</li></ul></div>\n<div class="note"><strong>Mini-cas.</strong> Une banque demande « tout sur le pays X ». L''analyste propose trois besoins : risque de change, calendrier électoral, sécurité des agences en zone frontalière. La collecte devient ciblée et le livrable utile.</div>',NULL,NULL,20,1,3),
(4,2,'Grandes étapes historiques','text','<p>L''histoire du renseignement est aussi ancienne que celle du pouvoir politique. Elle éclaire les pratiques actuelles et rappelle que les dérives passées ont conduit à l''instauration de contrôles démocratiques.</p>\n<h3>Antiquité et royaumes africains</h3>\n<p>Les traités militaires anciens, dont <em>L''Art de la guerre</em> attribué à Sun Tzu, consacrent déjà un chapitre à l''emploi des informateurs. En Afrique, les grands ensembles politiques (empires du Ghana, du Mali et Songhaï, royaume du Dahomey, empire éthiopien, royaumes swahilis) s''appuyaient sur des réseaux de messagers, de commerçants caravaniers et de conseillers chargés de rapporter la situation des provinces et des voisins. Les routes transsahariennes étaient autant des voies d''échange que des canaux d''information.</p>\n<h3>L''âge des cabinets et des chiffres</h3>\n<p>Du XVI<sup>e</sup> au XIX<sup>e</sup> siècle, les monarchies européennes structurent des « cabinets noirs » chargés d''ouvrir le courrier diplomatique et de déchiffrer les messages. La cryptologie devient une discipline à part entière. La période coloniale voit ensuite les administrations imposer en Afrique des services de police politique tournés vers le contrôle des populations, un héritage que les États indépendants ont dû réformer.</p>\n<h3>Le XX<sup>e</sup> siècle : institutionnalisation</h3>\n<ul>\n<li><strong>Les deux guerres mondiales</strong> industrialisent la collecte (écoutes radio, reconnaissance aérienne) et le décryptement.</li>\n<li><strong>La guerre froide</strong> crée de grandes agences permanentes et fait de l''Afrique un terrain de rivalités extérieures.</li>\n<li><strong>Les indépendances</strong> conduisent les États africains à bâtir leurs propres services, souvent dans l''urgence et parfois au service exclusif du pouvoir en place.</li>\n</ul>\n<h3>Depuis les années 1990 : contrôle et coopération</h3>\n<p>La fin de la guerre froide, puis la montée du terrorisme transnational, de la criminalité organisée et des menaces numériques, ont transformé les priorités. Deux tendances marquent la période : l''encadrement législatif des services (lois, commissions de contrôle, juges) et le développement de coopérations régionales, notamment sous l''égide de l''Union africaine et des communautés économiques régionales.</p>\n<blockquote>Leçon de l''histoire : les services les plus efficaces dans la durée sont ceux qui bénéficient de la confiance des citoyens, donc ceux qui respectent la loi.</blockquote>',NULL,NULL,25,1,1),
(5,2,'Approfondissement : contrôle démocratique des services','text','<p>L''histoire montre que la question centrale n''est pas seulement l''efficacité des services, mais leur <strong>redevabilité</strong>. Un service sans contrôle tend à servir un pouvoir plutôt que l''État et les citoyens.</p>\n<h3>Les quatre formes de contrôle</h3>\n<ol>\n<li><strong>Exécutif</strong> : directives ministérielles, inspections internes.</li>\n<li><strong>Parlementaire</strong> : commissions spécialisées, contrôle budgétaire.</li>\n<li><strong>Juridictionnel</strong> : autorisation et recours devant un juge.</li>\n<li><strong>Indépendant</strong> : autorités administratives, médiateurs, autorités de protection des données.</li>\n</ol>\n<h3>Repères internationaux</h3>\n<p>Les Nations unies ont publié en 2010 une compilation de <em>bonnes pratiques</em> sur le cadre juridique et institutionnel des services de renseignement (rapport du Rapporteur spécial sur les droits de l''homme et la lutte antiterroriste). Elle recommande notamment un mandat légal public, un contrôle indépendant et des voies de recours pour les personnes concernées.</p>\n<h3>En Afrique</h3>\n<p>Plusieurs constitutions africaines adoptées ou révisées depuis les années 1990 encadrent explicitement les services de sécurité (par exemple l''Afrique du Sud, avec un inspecteur général du renseignement et une commission parlementaire conjointe). La tendance générale est à l''inscription des services dans la loi et à la création d''organes de contrôle.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Légitimité et efficacité vont de pair.</li><li>Le contrôle combine plusieurs niveaux complémentaires.</li><li>La loi publique fixe le mandat ; le secret porte sur les opérations, pas sur les règles.</li></ul></div>',NULL,NULL,20,1,2),
(6,3,'Panorama des disciplines de collecte','text','<p>Les professionnels classent les sources par grandes familles, désignées par des acronymes anglais. Chacune a ses forces, ses faiblesses et son cadre juridique propre.</p>\n<table><thead><tr><th>Discipline</th><th>Source</th><th>Atout</th><th>Limite</th></tr></thead><tbody>\n<tr><td><strong>HUMINT</strong></td><td>Personnes</td><td>Intentions, contexte, nuances</td><td>Fiabilité variable, risques humains</td></tr>\n<tr><td><strong>OSINT</strong></td><td>Sources ouvertes et publiques</td><td>Volume, coût, légalité d''accès</td><td>Bruit, désinformation</td></tr>\n<tr><td><strong>SIGINT</strong></td><td>Signaux électromagnétiques</td><td>Couverture, rapidité</td><td>Strictement réservé aux autorités habilitées par la loi</td></tr>\n<tr><td><strong>GEOINT</strong></td><td>Imagerie et données géospatiales</td><td>Vision objective du terrain</td><td>Ne révèle pas les intentions</td></tr>\n<tr><td><strong>FININT</strong></td><td>Flux financiers</td><td>Traçabilité des réseaux</td><td>Accès encadré (cellules de renseignement financier)</td></tr>\n<tr><td><strong>TECHINT</strong></td><td>Matériels et technologies</td><td>Connaissance des capacités</td><td>Expertise rare</td></tr>\n</tbody></table>\n<h3>La fusion des sources (all-source)</h3>\n<p>Aucune discipline ne suffit seule. L''analyste « toutes sources » croise des éléments hétérogènes : une image satellite montre un chantier, un article de presse locale évoque un projet d''infrastructure, un registre public identifie l''entreprise adjudicataire. C''est la convergence d''indices indépendants qui fonde un jugement solide.</p>\n<div class="note"><strong>Principe d''indépendance.</strong> Deux articles qui reprennent la même dépêche ne constituent pas deux sources : ils n''en font qu''une. Remonter à l''origine de l''information est un réflexe fondamental.</div>',NULL,NULL,20,1,1),
(7,3,'Approfondissement : planifier une collecte multi-sources','text','<p>Le <strong>plan de collecte</strong> associe chaque élément d''information recherché à des sources possibles, en privilégiant les moins coûteuses et les moins intrusives.</p>\n<table><thead><tr><th>Élément recherché</th><th>Sources ouvertes</th><th>Sources humaines (consenties)</th><th>Imagerie</th></tr></thead><tbody>\n<tr><td>Activité d''un port</td><td>Statistiques portuaires, presse économique</td><td>Échanges avec des transitaires</td><td>Images satellitaires libres (navires à quai)</td></tr>\n<tr><td>Prix des denrées</td><td>Systèmes d''information sur les marchés</td><td>Commerçants interrogés</td><td>-</td></tr>\n<tr><td>Inondations</td><td>Communiqués officiels, ONG</td><td>Témoignages publics</td><td>Imagerie radar (traverse les nuages)</td></tr>\n</tbody></table>\n<h3>Principe de parcimonie</h3>\n<p>On commence par les sources ouvertes ; on ne recourt aux moyens plus coûteux que si une lacune importante subsiste. Cette règle économise des ressources et limite l''intrusion dans la vie des personnes.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Une source par élément ne suffit pas : prévoir des sources de recoupement.</li><li>Documenter pourquoi une source est choisie.</li><li>Réviser le plan à chaque cycle.</li></ul></div>',NULL,NULL,20,1,2),
(8,4,'Méthodes d''analyse structurée','text','<p>L''analyse consiste à transformer un ensemble d''éléments évalués en <strong>jugements</strong> utiles. Le principal ennemi de l''analyste n''est pas le manque d''information mais <strong>les biais cognitifs</strong>.</p>\n<h3>Biais fréquents</h3>\n<ul>\n<li><strong>Biais de confirmation</strong> : retenir ce qui confirme l''idée initiale.</li>\n<li><strong>Ancrage</strong> : rester prisonnier de la première estimation.</li>\n<li><strong>Effet miroir</strong> : supposer que l''autre raisonne comme nous.</li>\n<li><strong>Pensée de groupe</strong> : consensus artificiel au sein d''une équipe.</li>\n</ul>\n<h3>L''analyse des hypothèses concurrentes (ACH)</h3>\n<p>Méthode formalisée par Richards J. Heuer : on liste <em>toutes</em> les hypothèses plausibles, puis on évalue chaque indice au regard de chacune. On cherche moins les indices qui confirment que ceux qui <strong>infirment</strong>. L''hypothèse retenue est celle qui subit le moins d''incohérences.</p>\n<table><thead><tr><th>Indice</th><th>H1 : exercice logistique</th><th>H2 : préparation d''incident</th><th>H3 : activité commerciale</th></tr></thead><tbody>\n<tr><td>Convoi observé à date habituelle</td><td>Cohérent</td><td>Neutre</td><td>Cohérent</td></tr>\n<tr><td>Aucun discours public hostile</td><td>Cohérent</td><td>Incohérent</td><td>Cohérent</td></tr>\n<tr><td>Marchandises déclarées en douane</td><td>Neutre</td><td>Incohérent</td><td>Cohérent</td></tr>\n</tbody></table>\n<h3>Exprimer l''incertitude</h3>\n<p>Un jugement analytique s''accompagne toujours d''un niveau de confiance et d''un vocabulaire de probabilité stable : <em>presque certain, probable, possible, peu probable</em>. Cette échelle doit être définie à l''avance et partagée avec les lecteurs pour éviter toute ambiguïté.</p>\n<div class="callout"><strong>Bonne pratique :</strong> séparer clairement les <em>faits</em> (ce qui est établi), les <em>jugements</em> (ce que l''on en conclut) et les <em>lacunes</em> (ce que l''on ignore encore).</div>',NULL,NULL,30,1,1),
(9,4,'Approfondissement : indicateurs et alerte précoce','text','<p>L''analyse prospective s''appuie sur des <strong>indicateurs</strong> : des faits observables dont l''apparition rend un scénario plus ou moins probable. Cette méthode est au cœur des systèmes d''alerte précoce.</p>\n<h3>Construire une liste d''indicateurs</h3>\n<ol><li>Décrire chaque scénario en une phrase.</li><li>Lister ce qui serait <em>visible</em> si ce scénario se réalisait.</li><li>Retenir les indicateurs observables légalement et régulièrement.</li><li>Fixer des seuils (« plus de trois incidents par semaine »).</li></ol>\n<h3>Exemple (fictif)</h3>\n<table><thead><tr><th>Scénario</th><th>Indicateurs</th></tr></thead><tbody>\n<tr><td>Hausse des tensions foncières</td><td>Plaintes déposées, conflits signalés par la presse locale, déplacements de troupeaux anormaux</td></tr>\n<tr><td>Apaisement</td><td>Accords communautaires publiés, médiations annoncées, baisse des incidents</td></tr>\n</tbody></table>\n<div class="warning">Un indicateur n''est pas une preuve : il modifie une probabilité. Évitez de conclure sur un indicateur isolé.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les indicateurs rendent l''analyse vérifiable et révisable.</li><li>Prévoir aussi des indicateurs du scénario favorable.</li><li>Revoir régulièrement la liste.</li></ul></div>',NULL,NULL,20,1,2),
(10,5,'Simulation guidée : de la commande à la note','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Commande.</strong> La directrice d''une compagnie aérienne régionale fictive, « Air Sahelia », vous demande : <em>« Devons-nous maintenir nos vols vers Port-Saba, capitale de la République de Kanaga, pendant les élections dans six semaines ? »</em></p>\n<h3>Étape 1 : Orientation (15 min)</h3>\n<p>Formulez trois besoins en renseignement et, pour chacun, deux éléments d''information observables.</p>\n<h3>Étape 2 : Plan de collecte (10 min)</h3>\n<p>Associez à chaque élément au moins une source ouverte légale et une source de recoupement.</p>\n<h3>Étape 3 : Analyse (20 min)</h3>\n<p>À partir des éléments fictifs suivants, construisez une matrice ACH à trois hypothèses (vols normaux / perturbations ponctuelles / suspension nécessaire) :</p>\n<ul><li>L''autorité de l''aviation civile de Kanaga a publié un avis de fonctionnement normal de l''aéroport.</li><li>Deux manifestations ont eu lieu près du centre-ville, sans incident à l''aéroport.</li><li>Un syndicat de contrôleurs aériens évoque une grève « possible ».</li><li>Les ambassades n''ont pas modifié leurs conseils aux voyageurs.</li></ul>\n<h3>Étape 4 : Livrable (15 min)</h3>\n<p>Rédigez une note BLUF d''une demi-page avec niveau de confiance, trois indicateurs à surveiller et une recommandation.</p><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Besoins précis et vérifiables</td><td>4</td></tr><tr><td>Plan de collecte légal et recoupé</td><td>3</td></tr><tr><td>Matrice ACH cohérente</td><td>5</td></tr><tr><td>Note BLUF claire, sourcée, avec confiance</td><td>5</td></tr><tr><td>Indicateurs pertinents</td><td>3</td></tr></tbody></table>',NULL,NULL,60,1,1),
(11,5,'Étude de cas : le rapport qui arrivait trop tard','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Une ONG humanitaire fictive dispose d''une analyste remarquable, dont les notes sont longues, exhaustives et parfaitement sourcées. Lors d''une crise d''approvisionnement en eau dans une région du nord de Kanaga, sa note de 22 pages arrive quatre jours après la décision de redéployer les équipes, prise sans elle.</p>\n<h3>Questions</h3>\n<ol><li>Quelle(s) phase(s) du cycle ont échoué ?</li><li>Comment concilier rigueur et délai ? Proposez un format en deux temps (alerte courte puis analyse).</li><li>Quel rôle aurait dû jouer le décideur dans l''orientation ?</li><li>Rédigez l''alerte de cinq lignes qui aurait dû être envoyée le premier jour.</li></ol>\n<blockquote>Leçon : la qualité d''un produit inclut sa pertinence temporelle.</blockquote>',NULL,NULL,30,1,2),
(12,5,'Fiche méthode : modèle de note d''analyse','text','<p>Modèle réutilisable, à copier dans votre traitement de texte.</p>\n<pre><code>CLASSIFICATION : [Public / Interne / Confidentiel]       DATE : [JJ/MM/AAAA]\nRÉFÉRENCE : [N°]     DESTINATAIRE : [Fonction]     AUTEUR : [Fonction]\n\nTITRE-JUGEMENT : [Une phrase qui dit l''essentiel]\n\nRÉSUMÉ (5 lignes max.)\n- Constat principal\n- Cause probable\n- Conséquence pour le destinataire\n- Niveau de confiance : [élevé / modéré / faible], avec justification\n- Recommandation ou indicateur à suivre\n\nFAITS ÉTABLIS          (sources cotées, ex. B2)\nANALYSE                (hypothèses concurrentes, raisonnement)\nLACUNES                (ce que l''on ignore)\nINDICATEURS À SURVEILLER\nSOURCES                (références, dates de consultation)</code></pre>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Faits, jugements et lacunes toujours séparés.</li><li>Le titre est un jugement, pas un thème.</li><li>Une note = un destinataire et une question.</li></ul></div>',NULL,NULL,10,1,3),
(13,6,'Fiche de synthèse (PDF)','document','<p>Téléchargez la fiche de synthèse de la formation : définitions, cycle du renseignement, tableau des disciplines, liste des biais et échelle de probabilité. Elle constitue votre aide-mémoire pour l''examen final.</p>',NULL,2,10,1,1),
(14,6,'Exercice : de l''information au renseignement','exercise','<p><strong>Contexte fictif.</strong> Le directeur sécurité d''une entreprise de logistique opérant entre deux pays voisins vous demande si la réouverture annoncée d''un poste frontière présente des risques pour ses convois.</p>\n<h3>Consignes</h3>\n<ol>\n<li>Reformulez la demande en <strong>trois besoins en renseignement</strong> précis et vérifiables.</li>\n<li>Pour chacun, identifiez <strong>deux sources ouvertes légales</strong> que vous consulteriez (journaux officiels, presse régionale, communiqués des douanes, rapports d''organisations régionales...).</li>\n<li>Proposez une <strong>grille d''évaluation</strong> des sources (fiabilité de la source / crédibilité de l''information).</li>\n<li>Rédigez un <strong>jugement analytique de cinq lignes</strong> en séparant faits, jugements et lacunes, avec un niveau de confiance.</li>\n</ol>\n<div class="note"><strong>Corrigé indicatif.</strong> Un bon besoin est daté et mesurable : « Quels sont les horaires et procédures effectifs du poste X depuis sa réouverture ? » plutôt que « Est-ce dangereux ? ». Le jugement doit mentionner explicitement ce qui reste inconnu.</div>',NULL,NULL,40,1,2),
(15,6,'Étude de cas : l''erreur d''analyse','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une cellule d''analyse d''une organisation régionale reçoit, sur trois semaines, une série de signalements de rassemblements dans une ville moyenne. L''analyste principal, convaincu dès le premier jour d''une préparation de troubles, rédige des notes de plus en plus alarmistes. Il s''avère finalement qu''il s''agissait de la préparation d''un festival culturel annuel, annoncée dans la presse locale en langue nationale.</p>\n<h3>Questions d''analyse</h3>\n<ol>\n<li>Quels biais cognitifs identifiez-vous ? À quel moment se sont-ils installés ?</li>\n<li>Quelle source simple aurait permis de lever le doute ? Pourquoi n''a-t-elle pas été consultée ?</li>\n<li>Construisez la matrice ACH qui aurait dû être réalisée dès la première semaine.</li>\n<li>Quelles mesures organisationnelles (relecture contradictoire, « avocat du diable », diversité linguistique de l''équipe) proposeriez-vous ?</li>\n</ol>\n<blockquote>Enseignement : la maîtrise des langues et des contextes locaux est une compétence analytique de premier plan sur le continent africain.</blockquote>',NULL,NULL,35,1,3),
(16,6,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>ACH</dt><dd>Analyse des hypothèses concurrentes : méthode privilégiant la réfutation.</dd><dt>Besoin en renseignement</dt><dd>Question précise et vérifiable dérivée d&#039;une préoccupation du décideur.</dd><dt>Biais de confirmation</dt><dd>Tendance à retenir ce qui confirme une idée préexistante.</dd><dt>Cycle du renseignement</dt><dd>Orientation, collecte, exploitation, analyse, diffusion, puis retour d&#039;expérience.</dd><dt>Effet miroir</dt><dd>Projection de sa propre logique sur un autre acteur.</dd><dt>Indicateur</dt><dd>Fait observable qui rend un scénario plus ou moins probable.</dd><dt>Niveau de confiance</dt><dd>Appréciation de la solidité d&#039;un jugement analytique.</dd><dt>Renseignement</dt><dd>Information évaluée, recoupée et interprétée pour éclairer une décision.</dd><dt>Toutes sources (all-source)</dt><dd>Analyse croisant plusieurs disciplines de collecte.</dd></dl>',NULL,NULL,10,1,4),
(17,6,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Heuer, Richards J., <em>Psychology of Intelligence Analysis</em>, CIA Center for the Study of Intelligence, 1999 (accès libre en ligne).<small>Classique sur les biais cognitifs et l&#039;ACH.</small></li><li>Lowenthal, Mark M., <em>Intelligence: From Secrets to Policy</em>, CQ Press (éditions successives).<small>Manuel de référence sur le cycle et les disciplines.</small></li><li>Kent, Sherman, <em>Strategic Intelligence for American World Policy</em>, Princeton University Press, 1949.<small>Texte fondateur de l&#039;analyse du renseignement.</small></li><li>Kahneman, Daniel, <em>Système 1 / Système 2 : les deux vitesses de la pensée</em>, Flammarion, 2012.<small>Comprendre les mécanismes des biais de jugement.</small></li><li>Nations unies, Conseil des droits de l''homme, <em>Compilation de bonnes pratiques relatives aux cadres juridiques et institutionnels des services de renseignement</em>, A/HRC/14/46, 2010.<small>Référence internationale sur le contrôle démocratique des services.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(18,7,'Briefing vidéo : quatre familles de sources','video','<p>Présentation visuelle des quatre disciplines étudiées et de leurs garde-fous juridiques.</p>',NULL,3,4,1,1),
(19,7,'Le renseignement d''origine humaine','text','<p>Le HUMINT regroupe toutes les informations obtenues <strong>auprès de personnes</strong>. Dans sa forme la plus courante et la plus légitime, il ressemble au travail d''un journaliste d''investigation ou d''un chercheur de terrain : entretiens, échanges avec des experts, participation à des conférences, débriefing de voyageurs ou de collaborateurs.</p>\n<h3>Ce qu''apporte le HUMINT</h3>\n<ul><li>Les <strong>intentions</strong> et les motivations, invisibles pour les capteurs techniques ;</li><li>Le <strong>contexte</strong> culturel, linguistique et social ;</li><li>L''accès à des milieux fermés, dans les limites de la loi.</li></ul>\n<h3>Ses fragilités</h3>\n<ul><li>La source peut se tromper, exagérer ou manipuler ;</li><li>Elle peut s''exposer à des risques personnels ;</li><li>La relation peut créer des dépendances ou des conflits d''intérêts.</li></ul>\n<h3>Cadre</h3>\n<p>Le recrutement de sources clandestines relève exclusivement des services de l''État agissant dans un cadre légal. Pour un acteur privé (entreprise, ONG, cabinet de conseil), le HUMINT se limite à des <strong>échanges transparents et consentis</strong> : jamais de corruption, de chantage, de fausse identité ou d''incitation à violer une obligation de confidentialité.</p>\n<div class="warning"><strong>Ligne rouge.</strong> Obtenir d''un salarié des informations couvertes par le secret de son employeur expose à des poursuites (violation du secret des affaires, corruption, complicité). L''éthique est ici aussi une protection juridique.</div>',NULL,NULL,25,1,2),
(20,7,'Approfondissement : le débriefing de voyage','text','<p>Le <strong>débriefing de retour de mission</strong> est la forme de HUMINT la plus simple et la plus légitime pour une organisation : on recueille, auprès de ses propres collaborateurs volontaires, ce qu''ils ont observé lors d''un déplacement professionnel.</p>\n<h3>Trame de débriefing (20 minutes)</h3>\n<ol><li>Contexte : lieux, dates, interlocuteurs officiels rencontrés.</li><li>Faits marquants : changements depuis la dernière mission (prix, sécurité, logistique).</li><li>Perceptions : climat des affaires, préoccupations exprimées publiquement.</li><li>Incidents : sollicitations inhabituelles, pertes de matériel, contrôles.</li><li>Recommandations pour la prochaine mission.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le débriefing est volontaire et transparent.</li><li>On ne demande jamais à un collaborateur de collecter clandestinement.</li><li>Les incidents de sécurité alimentent aussi la protection de l''organisation.</li></ul></div>',NULL,NULL,15,1,3),
(21,8,'Méthodologie OSINT','text','<p>L''OSINT exploite les informations <strong>publiquement et légalement accessibles</strong> : presse, publications officielles, registres publics, données ouvertes, travaux académiques, réseaux sociaux publics, imagerie commerciale. On estime souvent qu''une large majorité du renseignement utile à la décision peut être obtenue de cette manière.</p>\n<h3>Une méthode en six temps</h3>\n<ol>\n<li><strong>Cadrer</strong> la question et les limites (ce que l''on ne cherchera pas).</li>\n<li><strong>Planifier</strong> les sources et les mots-clés, y compris dans les langues locales (wolof, haoussa, swahili, amharique, arabe...).</li>\n<li><strong>Collecter</strong> en archivant systématiquement : URL, date, capture, empreinte du fichier.</li>\n<li><strong>Vérifier</strong> : origine, date réelle, géolocalisation, cohérence.</li>\n<li><strong>Analyser</strong> et recouper.</li>\n<li><strong>Restituer</strong> avec les références permettant à un tiers de refaire le chemin.</li>\n</ol>\n<h3>Les limites légales et éthiques</h3>\n<ul>\n<li>« Accessible » ne veut pas dire « librement exploitable » : les lois sur la protection des données personnelles s''appliquent (par exemple la Convention de Malabo de l''Union africaine et les lois nationales).</li>\n<li>Pas de contournement d''authentification, pas de faux profils pour infiltrer des groupes privés, pas de collecte massive de données personnelles sans base légale.</li>\n<li>Principe de <strong>minimisation</strong> : ne collecter que ce qui est nécessaire à la question posée.</li>\n</ul>\n<div class="callout">Un bon livrable OSINT est <strong>reproductible</strong> : un relecteur doit pouvoir retrouver chaque élément grâce aux références et aux captures horodatées.</div>',NULL,NULL,30,1,1),
(22,8,'Approfondissement : vérifier une information publique','text','<p>La vérification est l''étape qui distingue l''OSINT professionnel de la simple recherche. On applique une grille systématique inspirée du journalisme de vérification.</p>\n<h3>La grille en cinq questions</h3>\n<table><thead><tr><th>Question</th><th>Technique</th></tr></thead><tbody>\n<tr><td>Qui l''a publié en premier ?</td><td>Recherche d''antériorité, tri chronologique</td></tr>\n<tr><td>Quand ?</td><td>Métadonnées, archives web, éléments datés visibles</td></tr>\n<tr><td>Où ?</td><td>Géolocalisation sur imagerie</td></tr>\n<tr><td>Pourquoi maintenant ?</td><td>Contexte, intérêt de la diffusion</td></tr>\n<tr><td>Est-ce cohérent ?</td><td>Recoupement avec d''autres sources indépendantes</td></tr>\n</tbody></table>\n<p>Les archives web publiques (comme la Wayback Machine d''Internet Archive) permettent de retrouver une version antérieure d''une page modifiée ou supprimée.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>La première publication est souvent la plus informative.</li><li>Un contenu viral n''est pas un contenu vérifié.</li><li>Conserver la trace de chaque vérification.</li></ul></div>',NULL,NULL,20,1,2),
(23,9,'Le SIGINT : principes et contrôle démocratique','text','<p>Le SIGINT désigne le renseignement issu des <strong>signaux électromagnétiques</strong>. Il se divise traditionnellement en COMINT (communications) et ELINT (signaux électroniques non communicants, comme les radars). Cette formation l''aborde <strong>sous un angle conceptuel, historique et juridique</strong> : l''interception de communications est un acte réservé aux autorités habilitées et strictement encadré par la loi.</p>\n<h3>Pourquoi l''étudier ?</h3>\n<ul><li>Pour comprendre la place de cette discipline dans les politiques de sécurité ;</li><li>Pour mesurer les enjeux de souveraineté numérique et de protection des communications ;</li><li>Pour maîtriser le débat public sur l''équilibre entre sécurité et libertés.</li></ul>\n<h3>Repères historiques</h3>\n<p>Le décryptement des communications a pesé sur l''issue de plusieurs conflits du XX<sup>e</sup> siècle. Les révélations publiques des années 2010 sur la surveillance de masse ont, à l''inverse, montré les risques d''une collecte sans contrôle suffisant et relancé partout la réflexion législative.</p>\n<h3>Les garde-fous d''un État de droit</h3>\n<table><thead><tr><th>Principe</th><th>Traduction concrète</th></tr></thead><tbody>\n<tr><td>Légalité</td><td>Finalités et techniques définies par une loi publique</td></tr>\n<tr><td>Nécessité et proportionnalité</td><td>Mesure ciblée, limitée dans le temps, justifiée par une menace</td></tr>\n<tr><td>Autorisation préalable</td><td>Décision d''une autorité indépendante ou d''un juge</td></tr>\n<tr><td>Contrôle a posteriori</td><td>Commission parlementaire ou administrative indépendante</td></tr>\n<tr><td>Recours</td><td>Possibilité pour un citoyen de saisir une juridiction</td></tr>\n</tbody></table>\n<div class="warning">Toute interception de communications par un particulier ou une entreprise constitue une infraction pénale dans la quasi-totalité des législations. Aucune technique d''interception n''est enseignée à l''Académie.</div>',NULL,NULL,20,1,1),
(24,9,'Approfondissement : souveraineté numérique et câbles sous-marins','text','<p>Comprendre le SIGINT, c''est aussi comprendre l''<strong>infrastructure</strong> par laquelle circulent les communications. Pour l''Afrique, les câbles sous-marins et les points d''échange Internet sont des enjeux de souveraineté.</p>\n<h3>Quelques repères</h3>\n<ul><li>L''essentiel du trafic Internet intercontinental passe par des câbles sous-marins ; plusieurs grands câbles (par exemple 2Africa, Equiano, WACS, SAT-3) desservent le continent.</li><li>Les <strong>points d''échange Internet (IXP)</strong> nationaux permettent que le trafic entre deux utilisateurs d''un même pays reste dans le pays, ce qui réduit coûts et délais.</li><li>Les coupures de câbles (comme celles survenues en Afrique de l''Ouest en 2024) montrent la dépendance des économies à ces infrastructures.</li></ul>\n<h3>Enjeux pour l''analyste</h3>\n<p>Ces sujets relèvent de l''analyse stratégique ouverte : résilience des réseaux, dépendances technologiques, protection juridique des données. Ils ne requièrent aucune technique d''interception.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>L''infrastructure numérique est un actif stratégique.</li><li>Les IXP nationaux renforcent la résilience et la souveraineté.</li><li>L''analyse de ces enjeux se fait en sources ouvertes.</li></ul></div>',NULL,NULL,15,1,2),
(25,10,'Imagerie et analyse géospatiale','text','<p>Le GEOINT combine imagerie (satellitaire, aérienne), cartographie et données géoréférencées pour décrire et comprendre une situation sur le terrain. L''essor de l''imagerie commerciale et des programmes ouverts (comme Sentinel du programme européen Copernicus ou Landsat) a démocratisé cette discipline.</p>\n<h3>Notions de base</h3>\n<ul>\n<li><strong>Résolution spatiale</strong> : taille au sol d''un pixel (de 10 m pour Sentinel-2 à moins d''un mètre pour l''imagerie commerciale très haute résolution).</li>\n<li><strong>Résolution temporelle</strong> : fréquence de revisite d''une zone.</li>\n<li><strong>Bandes spectrales</strong> : l''infrarouge permet par exemple d''évaluer l''état de la végétation.</li>\n</ul>\n<h3>Applications légitimes en Afrique</h3>\n<ul><li>Suivi de la déforestation et de l''orpaillage illégal ;</li><li>Évaluation des dégâts après inondations ou sécheresses ;</li><li>Suivi des déplacements de populations à des fins humanitaires ;</li><li>Vérification d''informations diffusées en ligne (géolocalisation d''une vidéo).</li></ul>\n<h3>Méthode de photo-interprétation</h3>\n<p>On observe successivement : la <em>forme</em>, la <em>taille</em>, l''<em>ombre</em> (qui renseigne sur la hauteur et l''heure), la <em>texture</em>, le <em>motif</em> et l''<em>association</em> (ce qui se trouve autour). Comparer deux dates d''une même zone (analyse diachronique) est souvent plus parlant qu''une image isolée.</p>\n<div class="note">Le GEOINT montre <strong>ce qui est</strong>, rarement <strong>pourquoi</strong>. Il doit être croisé avec d''autres sources pour interpréter les intentions.</div>',NULL,NULL,25,1,1),
(26,10,'Approfondissement : indices de végétation et suivi environnemental','text','<p>Les capteurs multispectraux enregistrent la lumière réfléchie dans plusieurs longueurs d''onde. En combinant le rouge et le proche infrarouge, on calcule le <strong>NDVI</strong> (indice de végétation par différence normalisée), qui mesure la vigueur de la végétation.</p>\n<p><code>NDVI = (PIR - Rouge) / (PIR + Rouge)</code> : valeur comprise entre -1 et 1 ; plus elle est élevée, plus la végétation est dense et active.</p>\n<h3>Usages légitimes</h3>\n<ul><li>Anticiper les crises alimentaires (sécheresse, baisse des récoltes) ;</li><li>Suivre la déforestation et les feux de brousse ;</li><li>Repérer l''extension d''exploitations minières artisanales à proximité de cours d''eau.</li></ul>\n<p>Les données Sentinel-2 (Copernicus) et Landsat sont librement accessibles et suffisent pour la plupart de ces analyses.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le NDVI combine rouge et proche infrarouge.</li><li>La comparaison entre années révèle les tendances.</li><li>Ces analyses servent la sécurité alimentaire et environnementale.</li></ul></div>',NULL,NULL,20,1,2),
(27,11,'Simulation guidée : établir la chronologie d''un événement','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Situation.</strong> Un grand marché de Port-Saba (Kanaga) a été ravagé par un incendie. Sur les réseaux sociaux, trois versions circulent : accident électrique, acte criminel, incendie lié à un conflit entre commerçants. Une assurance vous mandate pour établir les faits publics, sans enquêter sur des personnes.</p>\n<h3>Matériel fictif fourni</h3>\n<ul><li>4 vidéos publiques publiées entre 02 h 10 et 03 h 40 ;</li><li>2 communiqués (pompiers, mairie) ;</li><li>une image satellitaire « avant » et une « après » ;</li><li>des articles de deux journaux locaux.</li></ul>\n<h3>Consignes</h3>\n<ol><li>Vérifiez chaque vidéo (antériorité, lieu, heure par les ombres et l''éclairage).</li><li>Établissez une chronologie horodatée en indiquant la source de chaque élément.</li><li>Mesurez sur l''imagerie l''étendue de la zone touchée.</li><li>Pour chacune des trois versions, indiquez les éléments qui la soutiennent ou la contredisent.</li><li>Concluez en séparant faits établis, hypothèses et lacunes.</li></ol>\n<div class="warning">Ne cherchez ni à identifier ni à nommer des personnes filmées : ce n''est ni le mandat ni une pratique éthique.</div><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Vérification méthodique des vidéos</td><td>5</td></tr><tr><td>Chronologie sourcée</td><td>5</td></tr><tr><td>Exploitation de l''imagerie</td><td>3</td></tr><tr><td>Évaluation équilibrée des versions</td><td>4</td></tr><tr><td>Respect du périmètre éthique</td><td>3</td></tr></tbody></table>',NULL,NULL,60,1,1),
(28,11,'Étude de cas : l''image satellite mal interprétée','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Un analyste junior signale « une concentration de véhicules militaires » sur une image satellitaire d''une zone frontalière. Après vérification, il s''agissait de camions de collecte de coton stationnés devant une usine d''égrenage, comme chaque année à la même période.</p>\n<ol><li>Quels critères de photo-interprétation auraient évité l''erreur (association, motif, saisonnalité) ?</li><li>Pourquoi une comparaison avec la même date l''année précédente est-elle décisive ?</li><li>Quelles sources ouvertes (calendrier agricole, presse économique) auraient confirmé l''activité ?</li></ol>',NULL,NULL,25,1,2),
(29,11,'Fiche méthode : journal de vérification','text','<table><thead><tr><th>N°</th><th>Contenu (URL, archive)</th><th>Première publication</th><th>Lieu vérifié</th><th>Heure estimée</th><th>Méthode</th><th>Confiance</th></tr></thead><tbody>\n<tr><td>1</td><td>...</td><td>...</td><td>...</td><td>...</td><td>...</td><td>...</td></tr></tbody></table>\n<h3>Réflexes</h3>\n<ul><li>Archiver avant d''analyser (le contenu peut disparaître) ;</li><li>Noter la date UTC de chaque consultation ;</li><li>Indiquer la méthode utilisée, pas seulement le résultat.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un journal permet à un tiers de refaire la vérification.</li><li>La confiance s''exprime pour chaque élément.</li></ul></div>',NULL,NULL,10,1,3),
(30,12,'Fiche de synthèse (PDF)','document','<p>Aide-mémoire des quatre disciplines : définitions, apports, limites et cadre légal.</p>',NULL,4,10,1,1),
(31,12,'Exercice : géolocaliser une image publique','exercise','<p><strong>Objectif.</strong> Apprendre à vérifier la localisation d''une photographie <em>publiée par une institution</em> (communiqué officiel, rapport d''ONG) en n''utilisant que des sources ouvertes, sans jamais chercher à localiser une personne privée.</p>\n<h3>Étapes</h3>\n<ol>\n<li>Relevez les indices visibles : relief, végétation, panneaux, architecture, langue des inscriptions, sens de circulation.</li>\n<li>Formulez une hypothèse de région, puis comparez avec une imagerie satellitaire libre.</li>\n<li>Vérifiez l''heure approximative grâce aux ombres.</li>\n<li>Documentez chaque étape par une capture annotée.</li>\n<li>Concluez avec un niveau de confiance et les éléments manquants.</li>\n</ol>\n<div class="warning">Règle déontologique : l''exercice porte uniquement sur des lieux et non sur des personnes. Ne jamais diffuser l''emplacement d''un domicile privé.</div>',NULL,NULL,45,1,2),
(32,12,'Étude de cas : vérifier une vidéo virale','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une vidéo présentée comme montrant des affrontements récents dans une capitale régionale circule massivement. Plusieurs médias s''apprêtent à la reprendre.</p>\n<h3>Démarche attendue</h3>\n<ol>\n<li><strong>Recherche d''antériorité</strong> par recherche inversée d''images clés : la vidéo a-t-elle déjà circulé ?</li>\n<li><strong>Géolocalisation</strong> via les bâtiments visibles et l''imagerie libre.</li>\n<li><strong>Chronolocalisation</strong> : météo, ombres, événements datés visibles.</li>\n<li><strong>Croisement</strong> avec la presse locale et les communiqués officiels.</li>\n</ol>\n<p><strong>Dénouement :</strong> la vidéo datait de six ans et avait été tournée dans un autre pays. Discutez l''impact qu''aurait eu sa diffusion et le rôle d''un analyste dans la lutte contre la désinformation.</p>',NULL,NULL,35,1,3),
(33,12,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Chronolocalisation</dt><dd>Détermination du moment d&#039;une prise de vue.</dd><dt>GEOINT</dt><dd>Renseignement géospatial : imagerie et données géoréférencées.</dd><dt>Géolocalisation</dt><dd>Détermination du lieu d&#039;une image ou d&#039;une vidéo.</dd><dt>HUMINT</dt><dd>Renseignement d&#039;origine humaine.</dd><dt>IXP</dt><dd>Point d&#039;échange Internet où les réseaux s&#039;interconnectent localement.</dd><dt>NDVI</dt><dd>Indice de végétation calculé à partir du rouge et du proche infrarouge.</dd><dt>OSINT</dt><dd>Renseignement d&#039;origine sources ouvertes.</dd><dt>Résolution spatiale</dt><dd>Taille au sol représentée par un pixel.</dd><dt>SIGINT</dt><dd>Renseignement d&#039;origine électromagnétique (COMINT, ELINT).</dd></dl>',NULL,NULL,10,1,4),
(34,12,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Silverman, Craig (dir.), <em>Verification Handbook</em>, European Journalism Centre, 2014 (accès libre).<small>Méthodes de vérification de contenus en ligne.</small></li><li>Higgins, Eliot, <em>We Are Bellingcat</em>, Bloomsbury, 2021.<small>Récit et méthodes de l&#039;enquête en sources ouvertes.</small></li><li>Programme européen Copernicus : données Sentinel (accès libre).<small>Imagerie satellitaire gratuite pour l&#039;entraînement.</small></li><li>Lowenthal, Mark M., <em>Intelligence: From Secrets to Policy</em>, CQ Press.<small>Chapitres consacrés aux disciplines de collecte.</small></li><li>Nations unies, Conseil des droits de l''homme, <em>Compilation de bonnes pratiques relatives aux cadres juridiques et institutionnels des services de renseignement</em>, A/HRC/14/46, 2010.<small>Référence internationale sur le contrôle démocratique des services.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(35,13,'Briefing vidéo : la dimension humaine','video','<p>Les quatre principes qui guident toute collecte humaine légitime.</p>',NULL,5,4,1,1),
(36,13,'Les principes du HUMINT','text','<p>Toute collecte humaine repose sur une <strong>relation</strong> entre un professionnel et une personne qui accepte de partager ce qu''elle sait. Quatre principes structurent cette relation.</p>\n<h3>1. Le besoin d''en connaître</h3>\n<p>On ne recueille que ce qui répond à une question précise. Interroger « au cas où » expose inutilement les personnes et noie l''analyse.</p>\n<h3>2. Le consentement éclairé</h3>\n<p>Dans un cadre privé ou académique, la personne sait à qui elle parle, pourquoi, et ce que deviendront ses propos. Elle peut refuser de répondre ou retirer son accord.</p>\n<h3>3. La protection</h3>\n<p>Le professionnel est responsable de la sécurité et de la confidentialité de ses interlocuteurs. Une source exposée par négligence est une faute professionnelle grave.</p>\n<h3>4. Le scepticisme méthodique</h3>\n<p>La sympathie pour un interlocuteur ne doit jamais remplacer l''évaluation. Chaque information est recoupée.</p>\n<table><thead><tr><th>Profil d''interlocuteur</th><th>Apport typique</th><th>Vigilance</th></tr></thead><tbody>\n<tr><td>Expert académique</td><td>Analyse de fond, contexte historique</td><td>Biais d''école de pensée</td></tr>\n<tr><td>Acteur économique local</td><td>Réalités du terrain, prix, flux</td><td>Intérêts commerciaux</td></tr>\n<tr><td>Responsable associatif</td><td>Perception des populations</td><td>Engagement militant</td></tr>\n<tr><td>Fonctionnaire (propos publics)</td><td>Position officielle</td><td>Communication institutionnelle</td></tr>\n</tbody></table>',NULL,NULL,25,1,2),
(37,13,'Approfondissement : le cycle de la relation avec un interlocuteur','text','<p>Une relation d''information professionnelle suit un cycle qui doit rester transparent à chaque étape.</p>\n<ol><li><strong>Identification</strong> : qui détient une expertise utile (publications, fonctions publiques) ?</li><li><strong>Prise de contact</strong> : présentation honnête, finalité annoncée.</li><li><strong>Échange</strong> : entretien consenti, dans les limites fixées par l''interlocuteur.</li><li><strong>Entretien de la relation</strong> : restitution, remerciements, respect des engagements.</li><li><strong>Clôture</strong> : fin explicite si le besoin disparaît.</li></ol>\n<div class="note"><strong>Réciprocité légitime.</strong> Partager une synthèse publique, inviter à une conférence ou citer une contribution (avec accord) sont des contreparties acceptables ; offrir de l''argent ou des avantages pour obtenir des informations confidentielles ne l''est pas.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Chaque étape repose sur l''honnêteté.</li><li>La relation se gère dans la durée et se clôt proprement.</li><li>La réciprocité doit rester transparente et proportionnée.</li></ul></div>',NULL,NULL,15,1,3),
(38,14,'Cadre juridique de la collecte','text','<p>La légalité de la collecte dépend à la fois <strong>du statut de celui qui collecte</strong> (service de l''État, entreprise, chercheur, journaliste) et <strong>des moyens employés</strong>.</p>\n<h3>Textes de référence (à adapter au pays d''exercice)</h3>\n<ul>\n<li>Constitutions nationales : droit à la vie privée, secret des correspondances.</li>\n<li>Lois nationales sur la protection des données personnelles et autorités de contrôle associées.</li>\n<li>Convention de l''Union africaine sur la cybersécurité et la protection des données à caractère personnel (Convention de Malabo, 2014).</li>\n<li>Code pénal : corruption, atteinte au secret professionnel, usurpation d''identité, intrusion.</li>\n<li>Droit du travail et secret des affaires.</li>\n</ul>\n<h3>Les lignes rouges absolues</h3>\n<div class="warning"><ul class="mb-0"><li>Offrir un avantage pour obtenir une information confidentielle (corruption) ;</li><li>Menacer, faire pression, exploiter une vulnérabilité (chantage, abus de faiblesse) ;</li><li>Usurper une identité ou une qualité (se dire policier, journaliste, auditeur...) ;</li><li>Enregistrer une conversation privée à l''insu de l''interlocuteur lorsque la loi l''interdit ;</li><li>Inciter quelqu''un à violer son obligation de confidentialité.</li></ul></div>\n<h3>Le test des quatre questions</h3>\n<ol><li>Est-ce légal dans le pays concerné ?</li><li>Serais-je à l''aise si la méthode était rendue publique ?</li><li>L''interlocuteur aurait-il accepté s''il avait su ?</li><li>Le bénéfice attendu justifie-t-il le risque pour les personnes ?</li></ol>\n<p>Une seule réponse négative suffit à abandonner la démarche.</p>',NULL,NULL,25,1,1),
(39,14,'Approfondissement : consentement et protection des données dans les entretiens','text','<p>Les notes d''entretien contiennent souvent des <strong>données personnelles</strong>. Les lois de protection des données s''appliquent donc à leur traitement.</p>\n<h3>Bonnes pratiques</h3>\n<ul><li>Informer l''interlocuteur de la finalité et de la durée de conservation ;</li><li>Recueillir son accord pour tout enregistrement audio ;</li><li>Pseudonymiser les comptes rendus ;</li><li>Limiter l''accès aux personnes qui en ont besoin ;</li><li>Supprimer les données brutes à l''échéance prévue.</li></ul>\n<h3>Le cas des personnes vulnérables</h3>\n<p>Victimes, mineurs, personnes déplacées : l''entretien exige un cadre renforcé (consentement éclairé, présence d''un tiers de confiance si nécessaire, absence de toute pression). En cas de doute, on s''abstient.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les notes d''entretien sont des données personnelles.</li><li>L''enregistrement suppose un accord explicite.</li><li>La vulnérabilité impose une prudence accrue.</li></ul></div>',NULL,NULL,15,1,2),
(40,15,'L''entretien d''information','text','<p>L''entretien d''information est une conversation <strong>préparée, transparente et structurée</strong>. Il s''inspire des méthodes du journalisme et des sciences sociales.</p>\n<h3>Préparation</h3>\n<ul><li>Objectif écrit en une phrase ;</li><li>Recherche préalable sur le sujet (pour poser des questions intelligentes) ;</li><li>Guide d''entretien : 5 à 8 questions ouvertes, du général au particulier ;</li><li>Logistique : lieu neutre et confortable, durée annoncée.</li></ul>\n<h3>Conduite : la méthode de l''entonnoir</h3>\n<ol><li><strong>Accueil</strong> : présentation, finalité, règles de confidentialité, accord sur la prise de notes.</li><li><strong>Questions ouvertes</strong> : « Comment décririez-vous... ? », « Que s''est-il passé ensuite ? »</li><li><strong>Approfondissement</strong> : reformulation, relances neutres, demandes d''exemples.</li><li><strong>Questions fermées</strong> de vérification : dates, chiffres, noms publics.</li><li><strong>Clôture</strong> : « Y a-t-il un point que je n''ai pas abordé ? », remerciements.</li></ol>\n<h3>Écoute active</h3>\n<p>Silence accueillant, reformulation, attention au non-verbal, absence de jugement. On évite les questions suggestives (« Vous êtes d''accord que... ? ») qui contaminent la réponse.</p>\n<h3>Observation non intrusive</h3>\n<p>Observer un <strong>espace public</strong> (marché, gare, salon professionnel) permet de comprendre des flux, des usages, une ambiance, sans jamais suivre, photographier ou ficher des individus. On note des tendances (affluence, horaires, types d''activités), pas des identités.</p>\n<div class="note">Après l''entretien, rédigez votre compte rendu dans l''heure : la mémoire se dégrade très vite. Distinguez verbatim, paraphrase et impressions personnelles.</div>',NULL,NULL,30,1,1),
(41,15,'Approfondissement : l''entretien cognitif','text','<p>L''<strong>entretien cognitif</strong>, développé par les psychologues Ronald Fisher et Edward Geiselman dans les années 1980, vise à obtenir des témoignages plus complets et plus exacts. Il est aujourd''hui utilisé par de nombreux services d''enquête et chercheurs.</p>\n<h3>Ses quatre consignes de base</h3>\n<ol><li><strong>Restituer le contexte</strong> : se replacer mentalement dans la situation (lieu, moment, ambiance).</li><li><strong>Tout rapporter</strong>, même les détails qui semblent sans importance.</li><li><strong>Changer l''ordre</strong> du récit (par exemple à rebours).</li><li><strong>Changer de perspective</strong> : décrire comme l''aurait vu une autre personne présente.</li></ol>\n<p>L''interviewer parle peu, laisse des silences et évite toute question suggestive. Les études montrent une augmentation sensible des informations correctes sans hausse importante des erreurs.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Méthode validée scientifiquement, non coercitive.</li><li>L''interlocuteur garde la maîtrise de son récit.</li><li>Elle s''applique aux témoignages consentis.</li></ul></div>',NULL,NULL,20,1,2),
(42,16,'Coter une source et une information','text','<p>Le système de cotation le plus répandu, souvent appelé <strong>code de l''Amirauté</strong> ou système OTAN, évalue séparément <strong>la source</strong> (lettre) et <strong>l''information</strong> (chiffre).</p>\n<table><thead><tr><th>Fiabilité de la source</th><th>Crédibilité de l''information</th></tr></thead><tbody>\n<tr><td>A : Totalement fiable</td><td>1 : Confirmée par d''autres sources</td></tr>\n<tr><td>B : Habituellement fiable</td><td>2 : Probablement vraie</td></tr>\n<tr><td>C : Assez fiable</td><td>3 : Possiblement vraie</td></tr>\n<tr><td>D : Pas toujours fiable</td><td>4 : Douteuse</td></tr>\n<tr><td>E : Non fiable</td><td>5 : Improbable</td></tr>\n<tr><td>F : Fiabilité impossible à évaluer</td><td>6 : Véracité impossible à évaluer</td></tr>\n</tbody></table>\n<p>Une source habituellement fiable peut transmettre une information douteuse (B4), et une source inconnue une information confirmée (F1). C''est tout l''intérêt de la double cotation.</p>\n<h3>Critères d''évaluation de la source</h3>\n<ul><li><strong>Accès</strong> : était-elle en position de savoir ?</li><li><strong>Historique</strong> : ses informations passées se sont-elles vérifiées ?</li><li><strong>Motivation</strong> : quel intérêt a-t-elle à parler ?</li><li><strong>Cohérence</strong> interne du récit.</li></ul>\n<h3>Signaux d''alerte</h3>\n<ul><li>Information trop parfaite, qui répond exactement à ce que l''on espérait ;</li><li>Détails invérifiables abondants, précision factice ;</li><li>Pression pour une décision rapide ;</li><li>Sources multiples qui partagent en réalité une même origine (<em>rapport circulaire</em>).</li></ul>',NULL,NULL,25,1,1),
(43,16,'Approfondissement : désinformation et manipulation des sources','text','<p>Une source peut être instrumentalisée pour diffuser une information fausse : c''est la <strong>désinformation</strong> (fausse et intentionnelle), à distinguer de la <strong>mésinformation</strong> (fausse mais diffusée de bonne foi).</p>\n<h3>Techniques fréquentes</h3>\n<ul><li>Mélange de faits vrais et d''un élément faux (le vrai crédibilise le faux) ;</li><li>Fuites « exclusives » sollicitant une réaction rapide ;</li><li>Faux documents imitant des en-têtes officiels ;</li><li>Réseaux de comptes coordonnés simulant un consensus.</li></ul>\n<h3>Défenses</h3>\n<ul><li>Coter séparément chaque élément d''un même récit ;</li><li>Vérifier l''authenticité matérielle des documents (format, signatures, cohérence) ;</li><li>Demander : à qui profite la diffusion ?</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Désinformation = intention de tromper.</li><li>Le vrai sert souvent d''emballage au faux.</li><li>L''urgence imposée est un signal d''alerte.</li></ul></div>',NULL,NULL,15,1,2),
(44,17,'Simulation guidée : plan d''entretiens pour une étude de marché','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Mandat.</strong> Une coopérative fictive de transformation de poisson souhaite comprendre pourquoi ses ventes baissent dans trois villes côtières de Kanaga. Vous disposez de deux jours sur place.</p>\n<h3>Consignes</h3>\n<ol><li>Identifiez cinq profils d''interlocuteurs pertinents (vendeuses, transporteurs, restaurateurs, association de consommateurs, service public des pêches) et justifiez chaque choix.</li><li>Rédigez le texte de présentation (identité, finalité, confidentialité, droit de refus).</li><li>Préparez un guide de six questions ouvertes adapté à deux de ces profils.</li><li>Prévoyez une grille de cotation des informations recueillies.</li><li>Indiquez trois situations où vous interromprez un entretien (détresse, demande de contrepartie, sujet hors mandat).</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Pertinence des profils</td><td>4</td></tr><tr><td>Transparence de la présentation</td><td>4</td></tr><tr><td>Qualité des questions ouvertes</td><td>5</td></tr><tr><td>Grille de cotation</td><td>4</td></tr><tr><td>Limites éthiques anticipées</td><td>3</td></tr></tbody></table>',NULL,NULL,50,1,1),
(45,17,'Étude de cas : l''informateur qui voulait être payé','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Lors d''une étude pour un client industriel, un employé d''un fournisseur concurrent propose de « fournir les prix d''achat internes » contre rémunération. Le chargé d''études hésite : l''information serait très utile au client.</p>\n<ol><li>Identifiez les infractions potentielles (corruption, violation du secret des affaires, complicité).</li><li>Quels risques pour le chargé d''études, son cabinet et le client ?</li><li>Rédigez la réponse à apporter à l''employé.</li><li>Quelles sources légales permettraient d''estimer ces prix (statistiques douanières, cours publics des matières premières, entretiens avec des experts) ?</li></ol>\n<blockquote>Règle : une information obtenue illégalement contamine toute l''analyse qui en dépend.</blockquote>',NULL,NULL,25,1,2),
(46,17,'Fiche méthode : compte rendu d''entretien','text','<pre><code>CR N° : [..]      Date / durée : [..]      Lieu : [type de lieu, non nominatif]\nInterlocuteur : [code pseudonyme, ex. S-021]   Accès : [nature de sa connaissance]\nConsentement : [oui, finalité annoncée, prise de notes acceptée]\n\n1. Verbatim marquants        (entre guillemets)\n2. Faits rapportés           (cotation de chaque fait, ex. C2)\n3. Opinions de l''interlocuteur\n4. Impressions de l''enquêteur (séparées et signalées comme telles)\n5. Points à vérifier          (avec sources de recoupement prévues)\n6. Engagements pris           (restitution, confidentialité)</code></pre>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Rédiger dans l''heure qui suit.</li><li>Ne jamais mêler faits, opinions et impressions.</li><li>Conserver la table de correspondance des pseudonymes à part.</li></ul></div>',NULL,NULL,10,1,3),
(47,18,'Fiche de synthèse (PDF)','document','<p>Guide d''entretien type, grille de cotation et test des quatre questions.</p>',NULL,6,10,1,1),
(48,18,'Exercice : préparer un guide d''entretien','exercise','<p><strong>Situation fictive.</strong> Une ONG de développement souhaite comprendre pourquoi un marché agricole régional a perdu la moitié de sa fréquentation en un an. Vous allez rencontrer, avec leur accord, un responsable de coopérative.</p>\n<h3>À produire</h3>\n<ol><li>L''objectif de l''entretien en une phrase.</li><li>Un texte d''introduction (présentation, finalité, confidentialité).</li><li>Six questions ouvertes ordonnées en entonnoir.</li><li>Trois relances neutres.</li><li>Un modèle de compte rendu distinguant verbatim, paraphrase et impressions.</li></ol>\n<div class="note">Critères d''évaluation : absence de questions suggestives, transparence sur la finalité, pertinence des relances, respect de la confidentialité.</div>',NULL,NULL,40,1,2),
(49,18,'Étude de cas : la source trop parfaite','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un cabinet d''analyse reçoit d''un contact rencontré récemment des informations très détaillées annonçant la faillite imminente d''un concurrent de son client. Le contact insiste pour que l''information soit utilisée « dans les 48 heures ».</p>\n<h3>Questions</h3>\n<ol><li>Quelle cotation provisoire attribuez-vous à la source et à l''information ? Justifiez.</li><li>Listez les signaux d''alerte présents.</li><li>Quelles vérifications ouvertes et légales mèneriez-vous (registres de commerce, publications légales, résultats financiers publiés) ?</li><li>Quels risques juridiques le client encourt-il s''il agit sur cette base (diffusion de fausses informations, manipulation de marché) ?</li></ol>\n<p><strong>Dénouement :</strong> l''information était une tentative de manipulation destinée à pousser le client à une communication publique préjudiciable. La prudence méthodique a protégé le client.</p>',NULL,NULL,30,1,3),
(50,18,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Besoin d&#039;en connaître</dt><dd>Principe limitant la collecte et le partage au strict nécessaire.</dd><dt>Code de l&#039;Amirauté</dt><dd>Cotation séparée de la source (A à F) et de l&#039;information (1 à 6).</dd><dt>Consentement éclairé</dt><dd>Accord donné en connaissant l&#039;identité de l&#039;interlocuteur et la finalité de l&#039;échange.</dd><dt>Désinformation</dt><dd>Information fausse diffusée intentionnellement.</dd><dt>Écoute active</dt><dd>Attention, reformulation et relances neutres.</dd><dt>Entretien cognitif</dt><dd>Méthode d&#039;entretien améliorant la qualité des témoignages.</dd><dt>Mésinformation</dt><dd>Information fausse diffusée de bonne foi.</dd><dt>Question suggestive</dt><dd>Question qui oriente la réponse ; à proscrire.</dd><dt>Rapport circulaire</dt><dd>Plusieurs sources apparentes issues d&#039;une même origine.</dd></dl>',NULL,NULL,10,1,4);
INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(51,18,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Fisher, Ronald P. et Geiselman, R. Edward, <em>Memory-Enhancing Techniques for Investigative Interviewing: The Cognitive Interview</em>, Charles C. Thomas, 1992.<small>Ouvrage de référence sur l&#039;entretien cognitif.</small></li><li>Vrij, Aldert, <em>Detecting Lies and Deceit</em>, Wiley, 2e éd. 2008.<small>Synthèse de la recherche sur la détection du mensonge.</small></li><li>Silverman, Craig (dir.), <em>Verification Handbook for Disinformation and Media Manipulation</em>, European Journalism Centre, 2020.<small>Désinformation et manipulation des sources.</small></li><li>Nations unies, Conseil des droits de l''homme, <em>Compilation de bonnes pratiques relatives aux cadres juridiques et institutionnels des services de renseignement</em>, A/HRC/14/46, 2010.<small>Référence internationale sur le contrôle démocratique des services.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(52,19,'Briefing vidéo : protéger, interpréter, écrire','video','<p>Les trois piliers de la formation en un coup d''œil.</p>',NULL,7,4,1,1),
(53,19,'Protéger ses sources','text','<p>La protection des sources est un principe partagé par le renseignement, le journalisme (consacré par de nombreuses législations africaines sur la presse) et la recherche en sciences sociales. Elle repose sur trois mécanismes.</p>\n<h3>1. La pseudonymisation</h3>\n<p>Dans les documents de travail, la source est désignée par un code (ex. <code>S-014</code>). La table de correspondance est conservée séparément, avec un accès restreint.</p>\n<h3>2. Le cloisonnement</h3>\n<p>Seules les personnes qui en ont besoin connaissent l''identité d''une source. Les rapports diffusés décrivent l''<em>accès</em> de la source (« une personne ayant une connaissance directe du secteur ») sans permettre de l''identifier.</p>\n<h3>3. L''hygiène numérique</h3>\n<ul><li>Messageries chiffrées de bout en bout pour les échanges ;</li><li>Chiffrement des supports (ordinateurs, clés USB) ;</li><li>Attention aux métadonnées des fichiers et des photos ;</li><li>Politique de conservation : supprimer ce qui n''est plus nécessaire.</li></ul>\n<div class="warning"><strong>Risque de recoupement.</strong> Même sans nom, un détail (fonction rare, lieu, date d''une réunion à trois participants) peut suffire à identifier quelqu''un. Relisez chaque rapport avec ce regard.</div>',NULL,NULL,25,1,2),
(54,19,'Approfondissement : la protection juridique des sources journalistiques en Afrique','text','<p>La protection des sources est reconnue comme un élément de la liberté d''expression. La <strong>Déclaration de principes sur la liberté d''expression et l''accès à l''information en Afrique</strong>, adoptée par la Commission africaine des droits de l''homme et des peuples (révisée en 2019), prévoit que les journalistes ne doivent pas être contraints de révéler leurs sources, sauf exceptions strictement encadrées par la loi.</p>\n<h3>Ce que cela implique pour un analyste</h3>\n<ul><li>Respecter les engagements de confidentialité pris ;</li><li>Ne jamais exercer de pression pour identifier la source d''un journaliste ;</li><li>Connaître les exceptions prévues par la loi nationale applicable.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>La protection des sources a un fondement juridique régional.</li><li>Les exceptions doivent être prévues par la loi et proportionnées.</li><li>La confiance des sources repose sur le respect des engagements.</li></ul></div>',NULL,NULL,15,1,3),
(55,20,'Mythes et réalités du comportement','text','<p>Films et séries ont popularisé l''idée qu''un regard fuyant ou un geste de la main trahirait le mensonge. <strong>La recherche scientifique contredit largement ces croyances.</strong></p>\n<h3>Ce que montrent les études</h3>\n<ul><li>Les méta-analyses de la recherche en psychologie montrent que la capacité moyenne à détecter le mensonge à partir du comportement dépasse à peine le hasard (de l''ordre de 54 %).</li><li>Il n''existe <strong>aucun indice non verbal universel</strong> du mensonge, à la manière du « nez de Pinocchio ».</li><li>Le stress d''une personne honnête soupçonnée peut produire les mêmes signes que ceux attribués aux menteurs.</li><li>Les variations culturelles du contact visuel, de la gestuelle ou des silences sont considérables, un point crucial sur un continent aussi divers que l''Afrique.</li></ul>\n<h3>Ce qui fonctionne mieux</h3>\n<ul><li>Les approches centrées sur le <strong>contenu verbal</strong> : richesse en détails vérifiables, cohérence, plausibilité ;</li><li>La <strong>vérification factuelle</strong> des éléments avancés ;</li><li>Les entretiens non accusatoires, qui favorisent un récit libre et détaillé.</li></ul>\n<div class="warning">Ne jamais fonder un jugement sur une personne (recrutement, soupçon, sanction) à partir d''une « lecture » du comportement. C''est scientifiquement infondé et potentiellement discriminatoire.</div>',NULL,NULL,30,1,1),
(56,20,'Approfondissement : les biais de l''observateur','text','<p>Au-delà du comportement de l''interlocuteur, c''est souvent l''<strong>observateur</strong> qui se trompe. Plusieurs biais affectent la perception :</p>\n<ul><li><strong>Effet de halo</strong> : une qualité perçue (aisance, élégance) colore tout le jugement ;</li><li><strong>Biais culturel</strong> : interpréter un comportement selon ses propres normes (le contact visuel direct est valorisé dans certaines cultures et jugé irrespectueux dans d''autres) ;</li><li><strong>Biais de confirmation</strong> : remarquer surtout ce qui confirme un soupçon ;</li><li><strong>Excès de confiance</strong> : les personnes qui se disent expertes en détection du mensonge ne font en moyenne pas mieux que les autres.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le non-verbal renseigne sur l''état émotionnel, pas sur la véracité.</li><li>Les normes culturelles changent l''interprétation des gestes.</li><li>La vérification factuelle reste la référence.</li></ul></div>',NULL,NULL,15,1,2),
(57,21,'Écrire pour un décideur','text','<p>Un décideur dispose de peu de temps. Le rapport doit lui permettre de comprendre <strong>l''essentiel en trente secondes</strong>, puis d''approfondir s''il le souhaite.</p>\n<h3>La structure BLUF</h3>\n<p><em>Bottom Line Up Front</em> : la conclusion d''abord.</p>\n<ol><li><strong>Titre-jugement</strong> : une phrase qui dit l''essentiel (« La hausse des prix du transport devrait se poursuivre jusqu''en mars »).</li><li><strong>Résumé</strong> en trois à cinq lignes, avec niveau de confiance.</li><li><strong>Développement</strong> : faits, analyse, hypothèses alternatives.</li><li><strong>Lacunes et indicateurs</strong> à surveiller.</li><li><strong>Sources</strong> et cotations.</li></ol>\n<h3>Règles d''écriture</h3>\n<ul><li>Phrases courtes, voix active, un paragraphe = une idée ;</li><li>Vocabulaire de probabilité normalisé (presque certain, probable, possible...) ;</li><li>Distinction visible entre faits et jugements ;</li><li>Pas d''adjectifs dramatiques ni de jargon inutile.</li></ul>\n<table><thead><tr><th>À éviter</th><th>À privilégier</th></tr></thead><tbody>\n<tr><td>« La situation est explosive. »</td><td>« Trois incidents ont été signalés en une semaine contre un par mois en moyenne ; une escalade est possible (confiance faible). »</td></tr>\n<tr><td>« Il semblerait que peut-être... »</td><td>« Il est probable que... »</td></tr>\n</tbody></table>',NULL,NULL,30,1,1),
(58,21,'Approfondissement : visualiser et synthétiser','text','<p>Un bon rapport utilise des <strong>supports visuels</strong> sobres qui servent l''argument.</p>\n<table><thead><tr><th>Besoin</th><th>Support adapté</th></tr></thead><tbody>\n<tr><td>Montrer une évolution</td><td>Courbe chronologique</td></tr>\n<tr><td>Comparer des options</td><td>Tableau avantages / risques / coûts</td></tr>\n<tr><td>Situer des faits</td><td>Carte annotée</td></tr>\n<tr><td>Montrer des relations</td><td>Schéma d''acteurs (sans données personnelles inutiles)</td></tr>\n</tbody></table>\n<h3>Le résumé exécutif en 5 lignes</h3>\n<ol><li>Le constat principal ;</li><li>la cause probable ;</li><li>la conséquence pour le lecteur ;</li><li>le niveau de confiance ;</li><li>l''action recommandée ou l''indicateur à suivre.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un visuel = un message.</li><li>Toujours sourcer les données d''un graphique.</li><li>Le résumé exécutif doit pouvoir être lu seul.</li></ul></div>',NULL,NULL,15,1,2),
(59,22,'Simulation guidée : rapport protégé en 45 minutes','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Situation.</strong> Un cadre d''une entreprise publique fictive de Kanaga vous a confié, de manière volontaire et consentie, que des retards de paiement aux fournisseurs risquent de provoquer l''arrêt d''un chantier routier stratégique. Il craint pour sa carrière. Votre client (un bailleur de fonds) attend une note avant ce soir.</p>\n<h3>Consignes</h3>\n<ol><li>Listez les détails du récit qui pourraient permettre d''identifier la source et décidez comment les neutraliser.</li><li>Recherchez au moins deux éléments publics corroborant ou nuançant l''information (presse, rapports d''exécution budgétaire).</li><li>Rédigez une note BLUF d''une page avec description protectrice de la source.</li><li>Définissez la liste de diffusion et le marquage.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Neutralisation des détails identifiants</td><td>6</td></tr><tr><td>Corroboration publique</td><td>4</td></tr><tr><td>Qualité de la note BLUF</td><td>6</td></tr><tr><td>Diffusion maîtrisée</td><td>4</td></tr></tbody></table>',NULL,NULL,45,1,1),
(60,22,'Étude de cas : le recruteur « intuitif »','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Le responsable sécurité d''une société de transport fictive écarte systématiquement les candidats qui « évitent le regard » lors des entretiens, persuadé de repérer ainsi les personnes malhonnêtes. Plusieurs candidats issus de régions où baisser les yeux devant un aîné est une marque de respect sont éliminés.</p>\n<ol><li>Quelles erreurs scientifiques et quels biais sont en cause ?</li><li>Quels risques juridiques (discrimination) l''entreprise court-elle ?</li><li>Proposez une procédure de recrutement fondée sur des critères vérifiables.</li></ol>',NULL,NULL,25,1,2),
(61,22,'Fiche méthode : check-list de protection d''une source','text','<ul class="checklist">\n<li>Pseudonyme attribué et table séparée</li>\n<li>Accès décrit sans détail identifiant</li>\n<li>Dates et lieux de rencontre généralisés</li>\n<li>Liste de diffusion restreinte et nominative</li>\n<li>Marquage du document</li>\n<li>Échanges sur messagerie chiffrée</li>\n<li>Métadonnées du fichier nettoyées</li>\n<li>Durée de conservation définie</li>\n</ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Relire chaque rapport « comme un adversaire » cherchant la source.</li><li>Moins de détails, plus de sécurité.</li></ul></div>',NULL,NULL,10,1,3),
(62,23,'Fiche de synthèse (PDF)','document','<p>Modèle de rapport BLUF, check-list de protection des sources et rappels scientifiques.</p>',NULL,8,10,1,1),
(63,23,'Exercice : rédiger un rapport BLUF','exercise','<p>À partir des éléments fictifs ci-dessous, rédigez un rapport d''une page.</p>\n<ul><li>Fait 1 : le prix du carburant a augmenté de 18 % en deux mois dans la région (statistiques officielles).</li><li>Fait 2 : deux syndicats de transporteurs ont annoncé publiquement des consultations de leurs membres.</li><li>Fait 3 : un responsable de coopérative (source cotée B, information cotée 3) évoque un possible mouvement de grève.</li><li>Lacune : aucune date n''est connue.</li></ul>\n<h3>Consignes</h3>\n<ol><li>Un titre-jugement.</li><li>Un résumé de quatre lignes avec niveau de confiance.</li><li>Deux hypothèses alternatives.</li><li>Trois indicateurs à surveiller.</li><li>La source humaine décrite sans pouvoir être identifiée.</li></ol>',NULL,NULL,50,1,2),
(64,23,'Étude de cas : la fuite par recoupement','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un rapport interne mentionne qu''« une source participant à la réunion restreinte du comité de direction du mardi » a signalé un projet de cession. Le rapport circule plus largement que prévu. En quelques heures, l''entreprise concernée identifie la source : seules quatre personnes assistaient à la réunion.</p>\n<h3>Questions</h3>\n<ol><li>Quelles erreurs de rédaction ont rendu l''identification possible ?</li><li>Réécrivez la mention de la source de manière protectrice.</li><li>Quelles mesures de diffusion auraient limité le risque ?</li><li>Quelles sont les responsabilités morales et juridiques de l''analyste ?</li></ol>',NULL,NULL,30,1,3),
(65,23,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>BLUF</dt><dd>Bottom Line Up Front : la conclusion en tête.</dd><dt>Cloisonnement</dt><dd>Limitation de la connaissance d&#039;une information aux seules personnes concernées.</dd><dt>Effet de halo</dt><dd>Une impression globale qui colore tout le jugement.</dd><dt>Pseudonymisation</dt><dd>Remplacement de l&#039;identité par un code, avec table de correspondance séparée.</dd><dt>Recoupement d&#039;identification</dt><dd>Identification indirecte d&#039;une personne par des détails contextuels.</dd><dt>Résumé exécutif</dt><dd>Synthèse lisible seule, destinée au décideur.</dd><dt>Vocabulaire de probabilité</dt><dd>Échelle normalisée (presque certain, probable, possible...).</dd></dl>',NULL,NULL,10,1,4),
(66,23,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Bond, Charles F. et DePaulo, Bella M., « Accuracy of Deception Judgments », <em>Personality and Social Psychology Review</em>, 10(3), 2006.<small>Méta-analyse montrant une précision proche du hasard.</small></li><li>Commission africaine des droits de l''homme et des peuples, <em>Déclaration de principes sur la liberté d''expression et l''accès à l''information en Afrique</em>, 2019.<small>Protection des sources journalistiques.</small></li><li>Heuer, Richards J. et Pherson, Randolph H., <em>Structured Analytic Techniques for Intelligence Analysis</em>, CQ Press, 2010.<small>Techniques de rédaction et d&#039;analyse structurée.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(67,24,'Briefing vidéo : penser comme un défenseur','video','<p>Les principes de la posture défensive en contre-espionnage.</p>',NULL,9,4,1,1),
(68,24,'Comprendre l''ingérence','text','<p>Le contre-espionnage regroupe l''ensemble des mesures visant à <strong>détecter, prévenir et neutraliser</strong> les activités de renseignement hostiles dirigées contre une organisation ou un État. Pour une organisation privée, il s''agit essentiellement de <strong>protection</strong> et de <strong>vigilance</strong> ; les enquêtes et sanctions relèvent des autorités judiciaires.</p>\n<h3>Qui cherche à obtenir vos informations ?</h3>\n<ul><li>Des <strong>concurrents</strong> peu scrupuleux (intelligence économique offensive illégale) ;</li><li>Des <strong>acteurs étatiques</strong> étrangers intéressés par des secteurs stratégiques (mines, énergie, télécoms, agriculture) ;</li><li>Des <strong>groupes criminels</strong> (fraude, rançongiciels, extorsion) ;</li><li>Des <strong>individus</strong> motivés par la vengeance, l''idéologie ou l''argent.</li></ul>\n<h3>Les modes opératoires classiques</h3>\n<table><thead><tr><th>Vecteur</th><th>Exemple</th></tr></thead><tbody>\n<tr><td>Approche humaine</td><td>Faux recruteur, consultant trop curieux, stagiaire sans encadrement</td></tr>\n<tr><td>Numérique</td><td>Hameçonnage ciblé, compromission de messagerie</td></tr>\n<tr><td>Physique</td><td>Vol d''ordinateur en déplacement, documents laissés en salle de réunion</td></tr>\n<tr><td>Légal mais déloyal</td><td>Questions insistantes lors d''audits, de salons, de visites de site</td></tr>\n</tbody></table>\n<p>La plupart des pertes d''informations ne résultent pas d''opérations sophistiquées mais d''<strong>imprudences ordinaires</strong> : conversations dans un avion, publications sur les réseaux sociaux, mots de passe partagés.</p>',NULL,NULL,25,1,2),
(69,24,'Approfondissement : les ingérences économiques étrangères','text','<p>L''<strong>ingérence économique</strong> désigne les actions d''acteurs étrangers visant à obtenir un avantage indu sur des entreprises ou des secteurs nationaux, par des moyens déloyaux ou illégaux.</p>\n<h3>Formes observées dans le monde</h3>\n<ul><li>Prises de participation visant à capter une technologie ;</li><li>Recrutement ciblé de chercheurs ou d''ingénieurs clés ;</li><li>Audits ou « due diligences » détournés de leur finalité ;</li><li>Procédures juridiques extraterritoriales utilisées comme levier ;</li><li>Campagnes de dénigrement pour faire échouer un appel d''offres.</li></ul>\n<h3>Secteurs sensibles en Afrique</h3>\n<p>Mines et minerais critiques, énergie, télécommunications, paiement mobile, agro-industrie (semences, transformation), infrastructures portuaires.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Toute relation économique n''est pas une ingérence : c''est le caractère déloyal qui compte.</li><li>Les moments de transaction (levée de fonds, partenariat) sont les plus exposés.</li><li>La réponse passe par la vigilance, le droit et le signalement aux autorités.</li></ul></div>',NULL,NULL,15,1,3),
(70,25,'La menace interne','text','<p>La menace interne désigne le risque qu''une personne disposant d''un <strong>accès légitime</strong> (salarié, prestataire, partenaire) cause un préjudice, volontairement ou non.</p>\n<h3>Trois profils</h3>\n<ul><li><strong>Négligent</strong> : le plus fréquent : erreur, méconnaissance des règles ;</li><li><strong>Compromis</strong> : ses identifiants ou son poste sont utilisés par un tiers ;</li><li><strong>Malveillant</strong> : agit intentionnellement, souvent après une frustration non traitée.</li></ul>\n<h3>Facteurs de risque organisationnels</h3>\n<ul><li>Droits d''accès excessifs et jamais révisés ;</li><li>Départs mal gérés (comptes actifs après la fin du contrat) ;</li><li>Climat social dégradé, absence de canal d''écoute ;</li><li>Absence de séparation des tâches sensibles.</li></ul>\n<h3>Mesures proportionnées</h3>\n<ol><li><strong>Moindre privilège</strong> : chacun n''accède qu''à ce dont il a besoin ;</li><li><strong>Revue périodique</strong> des accès ;</li><li><strong>Procédures d''arrivée et de départ</strong> formalisées ;</li><li><strong>Culture de confiance</strong> : un canal de signalement protégé et un management attentif réduisent davantage le risque que la surveillance.</li></ol>\n<div class="warning">La surveillance des salariés est strictement encadrée par le droit du travail et la protection des données : information préalable, proportionnalité, finalité légitime. Une surveillance généralisée détruit la confiance et peut être illégale.</div>',NULL,NULL,25,1,1),
(71,25,'Approfondissement : les signaux de vigilance sans surveillance abusive','text','<p>La recherche sur la menace interne montre que les incidents sont souvent précédés de <strong>signaux observables</strong> dans le cadre normal du travail. Les repérer ne nécessite pas de surveiller la vie privée des employés.</p>\n<h3>Signaux liés au travail (à traiter avec discernement)</h3>\n<ul><li>Demandes d''accès sans lien avec la mission ;</li><li>Téléchargements massifs avant un départ ;</li><li>Contournement répété des procédures de sécurité ;</li><li>Conflit professionnel grave non résolu.</li></ul>\n<h3>La bonne réponse</h3>\n<p>Un signal appelle d''abord un <strong>échange managérial</strong> et, si nécessaire, une vérification encadrée par les procédures internes et le droit du travail, jamais une enquête clandestine ni une stigmatisation.</p>\n<div class="warning">Les critères liés à l''origine, à la religion, à l''opinion ou à la vie privée ne sont pas des indicateurs de risque : les utiliser serait discriminatoire et illégal.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les signaux pertinents sont professionnels et objectifs.</li><li>La première réponse est managériale.</li><li>Toute vérification suit une procédure écrite et proportionnée.</li></ul></div>',NULL,NULL,15,1,2),
(72,26,'Classifier et protéger','text','<p>On ne peut pas tout protéger avec la même intensité. La démarche commence par l''identification du <strong>patrimoine informationnel critique</strong> : ce dont la perte, l''altération ou la divulgation causerait un préjudice grave.</p>\n<h3>Étape 1 : inventaire</h3>\n<p>Pour chaque information sensible : qui la détient, où est-elle stockée, qui y accède, quelle serait la conséquence d''une fuite ?</p>\n<h3>Étape 2 : une classification simple</h3>\n<table><thead><tr><th>Niveau</th><th>Exemples</th><th>Règles</th></tr></thead><tbody>\n<tr><td>Public</td><td>Plaquette, site web</td><td>Diffusion libre</td></tr>\n<tr><td>Interne</td><td>Notes de service, organigramme</td><td>Personnels uniquement</td></tr>\n<tr><td>Confidentiel</td><td>Offres commerciales, données RH</td><td>Liste nominative, chiffrement</td></tr>\n<tr><td>Secret organisationnel</td><td>Stratégie, négociations en cours</td><td>Accès très restreint, traçabilité</td></tr>\n</tbody></table>\n<h3>Étape 3 : mesures</h3>\n<ul><li>Marquage visible des documents ;</li><li>Chiffrement des fichiers et des supports ;</li><li>Bureau et écran propres ; destruction sécurisée des papiers ;</li><li>Règles de discussion en lieux publics et en déplacement ;</li><li>Clauses de confidentialité avec les partenaires.</li></ul>\n<div class="callout">Une classification trop complexe n''est pas appliquée. Quatre niveaux suffisent dans la plupart des organisations.</div>',NULL,NULL,25,1,1),
(73,26,'Approfondissement : le marquage TLP pour partager l''information','text','<p>Le <strong>Traffic Light Protocol (TLP)</strong>, normalisé par le FIRST (Forum of Incident Response and Security Teams, version 2.0 en 2022), est un code simple indiquant jusqu''où une information peut être partagée.</p>\n<table><thead><tr><th>Marquage</th><th>Diffusion autorisée</th></tr></thead><tbody>\n<tr><td>TLP:RED</td><td>Uniquement les participants nommés de la réunion ou de l''échange</td></tr>\n<tr><td>TLP:AMBER+STRICT</td><td>Uniquement l''organisation du destinataire</td></tr>\n<tr><td>TLP:AMBER</td><td>L''organisation du destinataire et ses clients, sur la base du besoin d''en connaître</td></tr>\n<tr><td>TLP:GREEN</td><td>La communauté (secteur, réseau de confiance), pas publiquement</td></tr>\n<tr><td>TLP:CLEAR</td><td>Diffusion publique sans restriction</td></tr>\n</tbody></table>\n<p>Le TLP complète la classification interne : il régit le <em>partage</em> entre organisations, notamment entre équipes de réponse aux incidents.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le marquage s''indique en tête du document.</li><li>En cas de doute, demander à l''émetteur.</li><li>TLP:CLEAR remplace l''ancien TLP:WHITE.</li></ul></div>',NULL,NULL,15,1,2),
(74,27,'Reconnaître la manipulation','text','<p>L''ingénierie sociale exploite des réflexes humains normaux (serviabilité, respect de l''autorité, peur) pour obtenir une information ou une action. Elle précède la majorité des cyberattaques réussies.</p>\n<h3>Les leviers utilisés</h3>\n<table><thead><tr><th>Levier</th><th>Formulation typique</th></tr></thead><tbody>\n<tr><td>Autorité</td><td>« Le directeur général exige ce virement aujourd''hui. »</td></tr>\n<tr><td>Urgence</td><td>« Votre compte sera bloqué dans une heure. »</td></tr>\n<tr><td>Sympathie</td><td>« On s''est croisés au séminaire de Dakar, tu te souviens ? »</td></tr>\n<tr><td>Réciprocité</td><td>Petit cadeau ou service rendu, puis demande</td></tr>\n<tr><td>Preuve sociale</td><td>« Tous vos collègues ont déjà validé. »</td></tr>\n</tbody></table>\n<h3>Scénarios fréquents en Afrique</h3>\n<ul><li>Fraude au président par messagerie instantanée ou appel vocal ;</li><li>Faux changement de coordonnées bancaires d''un fournisseur ;</li><li>Fausses offres d''emploi ou de bourses visant les jeunes diplômés ;</li><li>Faux techniciens d''opérateurs télécoms ou de services de paiement mobile.</li></ul>\n<h3>Parades</h3>\n<ol><li><strong>Vérifier par un autre canal</strong> (rappeler un numéro connu, jamais celui fourni) ;</li><li>Ne jamais céder à l''urgence artificielle : <em>« ralentir, c''est se protéger »</em> ;</li><li>Procédures de double validation pour les paiements ;</li><li>Signaler sans crainte : celui qui signale une tentative ne doit jamais être blâmé.</li></ol>',NULL,NULL,25,1,1),
(75,27,'Approfondissement : concevoir une campagne de sensibilisation','text','<p>Une sensibilisation efficace change des comportements, pas seulement des connaissances.</p>\n<h3>Les ingrédients</h3>\n<ul><li><strong>Exemples locaux</strong> : fraudes réellement observées dans le pays ou le secteur (anonymisées) ;</li><li><strong>Formats courts</strong> et répétés plutôt qu''une longue session annuelle ;</li><li><strong>Exercices de simulation</strong> d''hameçonnage annoncés dans leur principe, suivis d''une explication bienveillante ;</li><li><strong>Un canal de signalement simple</strong> (adresse ou bouton unique) ;</li><li><strong>Des indicateurs</strong> : taux de signalement, délai de signalement, plutôt que le seul taux de clic.</li></ul>\n<div class="note">Le meilleur indicateur d''une culture de sécurité est l''augmentation des signalements : elle montre que les équipes reconnaissent les tentatives et ont confiance dans le dispositif.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Court, fréquent, concret.</li><li>Valoriser les signalements, ne jamais humilier.</li><li>Mesurer les progrès dans le temps.</li></ul></div>',NULL,NULL,15,1,2),
(76,28,'Simulation guidée : diagnostic en une journée','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Organisation fictive :</strong> « Karité d''Or », 35 salariés, exporte des cosmétiques naturels et négocie un contrat de distribution avec un groupe étranger.</p>\n<h3>Constats de visite (fictifs)</h3>\n<ul><li>La formule des produits est stockée sur un ordinateur partagé sans mot de passe ;</li><li>Les visiteurs circulent librement dans l''atelier de production ;</li><li>Le commercial publie ses déplacements sur ses réseaux sociaux ;</li><li>La comptable a reçu un courriel d''un « nouveau transitaire » demandant les factures du client principal ;</li><li>Aucun accord de confidentialité n''a été signé avec le futur distributeur.</li></ul>\n<h3>Consignes</h3>\n<ol><li>Classez les constats par gravité (matrice probabilité × impact).</li><li>Proposez une mesure par constat, avec coût estimé (faible / moyen / élevé).</li><li>Rédigez un plan d''action sur 90 jours en trois priorités.</li><li>Préparez un message de sensibilisation de dix lignes pour les salariés.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Hiérarchisation justifiée</td><td>5</td></tr><tr><td>Mesures proportionnées</td><td>5</td></tr><tr><td>Plan 90 jours réaliste</td><td>5</td></tr><tr><td>Message de sensibilisation clair et bienveillant</td><td>5</td></tr></tbody></table>',NULL,NULL,60,1,1),
(77,28,'Étude de cas : la délégation trop curieuse','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Une délégation d''« investisseurs » visite une usine de semences améliorées. Pendant la visite, deux membres photographient les installations, posent des questions détaillées sur les procédés de sélection et demandent à échanger seuls avec les techniciens. Aucune lettre d''intention n''a été signée.</p>\n<ol><li>Quels signaux auraient dû alerter ?</li><li>Quelles règles de visite mettre en place (parcours défini, photos interdites, accompagnement, accord de confidentialité préalable) ?</li><li>Comment poursuivre une relation commerciale légitime tout en protégeant le savoir-faire ?</li></ol>',NULL,NULL,25,1,2),
(78,28,'Fiche méthode : protocole d''accueil des visiteurs','text','<ol><li><strong>Avant</strong> : liste nominative des visiteurs, objet de la visite, accord de confidentialité si des informations non publiques seront présentées.</li><li><strong>À l''arrivée</strong> : badge visiteur, rappel des règles (photos, zones interdites).</li><li><strong>Pendant</strong> : accompagnement permanent, parcours défini, documents sensibles rangés.</li><li><strong>Après</strong> : compte rendu, signalement de tout comportement inhabituel.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Accueillir n''est pas tout montrer.</li><li>Les règles s''annoncent avant la visite.</li></ul></div>',NULL,NULL,10,1,3),
(79,29,'Fiche de synthèse (PDF)','document','<p>Grille de classification, check-list anti-ingénierie sociale et procédure de signalement type.</p>',NULL,10,10,1,1),
(80,29,'Exercice : cartographier les actifs sensibles','exercise','<p><strong>Organisation fictive :</strong> « AgroSahel Coop », coopérative de 40 salariés qui exporte des produits transformés et prépare une levée de fonds.</p>\n<h3>Consignes</h3>\n<ol><li>Identifiez huit actifs informationnels (recettes, fichier clients, négociation financière, données RH...).</li><li>Classez-les selon la grille à quatre niveaux.</li><li>Pour les trois plus critiques, indiquez qui y accède aujourd''hui et qui <em>devrait</em> y accéder.</li><li>Proposez cinq mesures prioritaires, réalistes pour une PME.</li></ol>',NULL,NULL,45,1,2),
(81,29,'Étude de cas : la fraude au fournisseur','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une société de BTP reçoit un courriel apparemment envoyé par son principal fournisseur annonçant un changement de banque. Le comptable met à jour les coordonnées. Deux virements importants partent vers le compte frauduleux avant que le vrai fournisseur ne réclame son paiement.</p>\n<h3>Questions</h3>\n<ol><li>Quels indices auraient dû alerter (domaine de l''adresse, ton, timing) ?</li><li>Quelle procédure de contrôle aurait empêché la fraude ?</li><li>Qui prévenir immédiatement après la découverte (banque, autorités, plateforme de signalement nationale) ?</li><li>Comment communiquer en interne sans désigner de coupable ?</li></ol>',NULL,NULL,30,1,3),
(82,29,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Contre-espionnage</dt><dd>Mesures visant à détecter et neutraliser les activités de renseignement hostiles.</dd><dt>Fraude au président</dt><dd>Usurpation d&#039;un dirigeant pour obtenir un virement.</dd><dt>Ingénierie sociale</dt><dd>Manipulation psychologique pour obtenir une information ou une action.</dd><dt>Ingérence économique</dt><dd>Recherche d&#039;un avantage indu par des moyens déloyaux.</dd><dt>Menace interne</dt><dd>Risque causé par une personne disposant d&#039;un accès légitime.</dd><dt>Moindre privilège</dt><dd>Chacun n&#039;accède qu&#039;à ce dont il a besoin.</dd><dt>Patrimoine informationnel</dt><dd>Ensemble des informations ayant de la valeur pour l&#039;organisation.</dd><dt>TLP</dt><dd>Traffic Light Protocol : code de partage de l&#039;information.</dd></dl>',NULL,NULL,10,1,4),
(83,29,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Mitnick, Kevin, <em>The Art of Deception</em>, Wiley, 2002.<small>Exemples classiques d&#039;ingénierie sociale.</small></li><li>Hadnagy, Christopher, <em>Social Engineering: The Science of Human Hacking</em>, Wiley, 2018.<small>Leviers psychologiques et défenses.</small></li><li>FIRST, <em>Traffic Light Protocol (TLP) version 2.0</em>, 2022 (en ligne).<small>Norme de marquage du partage.</small></li><li>ISO/IEC 27001, Systèmes de management de la sécurité de l''information.<small>Cadre de référence de la protection de l&#039;information.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(84,30,'Briefing vidéo : la sécurité comme système','video','<p>Vue d''ensemble des couches de sécurité d''une organisation.</p>',NULL,11,4,1,1),
(85,30,'Protéger les personnes','text','<p>Les personnes sont à la fois la première ressource et la première cible. La sécurité du personnel couvre le cycle de vie professionnel et les situations de déplacement.</p>\n<h3>Le cycle de vie</h3>\n<ul><li><strong>Recrutement</strong> : vérifications proportionnées et légales (diplômes, références), sans enquête intrusive sur la vie privée ;</li><li><strong>Intégration</strong> : sensibilisation, charte, signature des engagements de confidentialité ;</li><li><strong>En poste</strong> : formation continue, entretiens réguliers ;</li><li><strong>Départ</strong> : restitution des équipements, clôture des accès, rappel des obligations.</li></ul>\n<h3>Sécurité en déplacement</h3>\n<table><thead><tr><th>Avant</th><th>Pendant</th><th>Après</th></tr></thead><tbody>\n<tr><td>Analyse du pays (avis officiels), itinéraire, contacts d''urgence, équipement informatique dédié</td><td>Discrétion, points de contact réguliers, vigilance sur les réseaux Wi-Fi publics</td><td>Débriefing, signalement d''incidents, contrôle des appareils</td></tr>\n</tbody></table>\n<div class="callout">Le devoir de protection de l''employeur (<em>duty of care</em>) impose d''évaluer les risques avant d''envoyer un collaborateur en mission et de prévoir les moyens d''assistance.</div>',NULL,NULL,25,1,2),
(86,30,'Approfondissement : la sécurité des voyageurs d''affaires','text','<p>Les déplacements concentrent des risques informationnels : appareils perdus ou inspectés, réseaux non fiables, conversations entendues.</p>\n<h3>Check-list numérique</h3>\n<ul><li>Emporter un ordinateur et un téléphone dédiés, ne contenant que le nécessaire ;</li><li>Chiffrement intégral activé et mises à jour faites avant le départ ;</li><li>Accès aux ressources de l''organisation via un VPN d''entreprise ;</li><li>Ne pas brancher de clés USB reçues ; recharger sur prise électrique plutôt que sur des ports USB publics ;</li><li>Au retour, faire vérifier les appareils par le service informatique.</li></ul>\n<h3>Check-list comportementale</h3>\n<ul><li>Discrétion dans les lieux publics (taxi, restaurant, salon d''aéroport) ;</li><li>Documents sensibles toujours sous contrôle ;</li><li>Signalement de toute sollicitation inhabituelle.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Moins on emporte de données, moins on en expose.</li><li>Le retour de mission compte autant que le départ.</li><li>Respecter les lois du pays visité, y compris lors des contrôles aux frontières.</li></ul></div>',NULL,NULL,15,1,3),
(87,31,'Conduire une analyse de menaces','text','<p>Le risque résulte de la combinaison d''une <strong>menace</strong> (un acteur avec une intention et une capacité), d''une <strong>vulnérabilité</strong> (une faiblesse exploitable) et d''un <strong>impact</strong> (la gravité des conséquences).</p>\n<h3>Évaluer une menace</h3>\n<ul><li><strong>Intention</strong> : l''acteur veut-il nous nuire ? Pourquoi ?</li><li><strong>Capacité</strong> : en a-t-il les moyens ?</li><li><strong>Opportunité</strong> : nos vulnérabilités lui offrent-elles une ouverture ?</li></ul>\n<h3>La matrice probabilité × impact</h3>\n<table><thead><tr><th></th><th>Impact faible</th><th>Impact modéré</th><th>Impact grave</th></tr></thead><tbody>\n<tr><th>Probable</th><td>Moyen</td><td>Élevé</td><td><strong>Critique</strong></td></tr>\n<tr><th>Possible</th><td>Faible</td><td>Moyen</td><td>Élevé</td></tr>\n<tr><th>Peu probable</th><td>Faible</td><td>Faible</td><td>Moyen</td></tr>\n</tbody></table>\n<h3>Sources d''information sur les menaces</h3>\n<p>Rapports publics d''autorités nationales de cybersécurité, bulletins des équipes CERT/CSIRT africaines, alertes sectorielles, retours d''expérience des pairs, incidents internes. L''analyse doit être <strong>actualisée régulièrement</strong> : une matrice figée devient trompeuse.</p>',NULL,NULL,30,1,1),
(88,31,'Approfondissement : la méthode du nœud papillon','text','<p>Le <strong>nœud papillon</strong> (bow-tie) représente un événement redouté au centre, ses <em>causes</em> à gauche et ses <em>conséquences</em> à droite. Les mesures de prévention s''insèrent entre causes et événement ; les mesures de protection entre événement et conséquences.</p>\n<pre><code>Causes -> [Prévention] -> ÉVÉNEMENT -> [Protection] -> Conséquences\nHameçonnage   MFA, formation    Compromission    Sauvegardes,      Arrêt d''activité\nMot de passe                    de messagerie    cellule de crise  Fuite de données</code></pre>\n<p>Cette visualisation, utilisée dans l''industrie et la sûreté, aide les décideurs à voir où investir et à vérifier qu''aucune cause majeure n''est sans barrière.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Prévention à gauche, protection à droite.</li><li>Chaque barrière a un responsable et un test.</li><li>Outil de communication efficace avec la direction.</li></ul></div>',NULL,NULL,15,1,2),
(89,32,'Choisir des contre-mesures','text','<p>Une contre-mesure réduit la probabilité ou l''impact d''un risque. La défense efficace est <strong>en profondeur</strong> : plusieurs couches complémentaires, de sorte qu''une défaillance isolée ne suffise pas.</p>\n<h3>Les quatre fonctions</h3>\n<ol><li><strong>Prévenir</strong> : contrôle d''accès, chiffrement, formation, procédures ;</li><li><strong>Détecter</strong> : journalisation, alertes, signalements des personnels ;</li><li><strong>Réagir</strong> : plan de réponse, cellule de crise, contacts juridiques et autorités ;</li><li><strong>Se rétablir</strong> : sauvegardes testées, plan de continuité, retour d''expérience.</li></ol>\n<h3>Prioriser</h3>\n<p>Chaque mesure est évaluée selon son coût, sa facilité de mise en œuvre et sa réduction du risque. Les mesures « à fort effet et faible coût » viennent en premier : double authentification, sauvegardes hors ligne, procédure de contre-appel pour les paiements, sensibilisation.</p>\n<div class="note"><strong>Contre-mesures et droit :</strong> les mesures défensives restent dans le périmètre de l''organisation. « Riposter » contre un attaquant (intrusion en retour, représailles) est illégal et dangereux : on signale aux autorités compétentes.</div>',NULL,NULL,25,1,1),
(90,32,'Approfondissement : continuité d''activité et gestion de crise','text','<p>La <strong>continuité d''activité</strong> organise le maintien des fonctions essentielles lorsqu''un incident survient. La norme ISO 22301 en fournit le cadre de référence.</p>\n<h3>Deux notions clés</h3>\n<ul><li><strong>RTO</strong> (Recovery Time Objective) : durée maximale d''interruption acceptable ;</li><li><strong>RPO</strong> (Recovery Point Objective) : perte de données maximale acceptable, exprimée en temps (par exemple 24 h de données).</li></ul>\n<h3>La cellule de crise</h3>\n<p>Elle réunit direction, technique, juridique et communication, avec un journal de bord horodaté. Ses premiers réflexes : qualifier l''incident, protéger les personnes et les preuves, informer les autorités et partenaires concernés, communiquer de façon factuelle.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>RTO = temps ; RPO = données perdues.</li><li>Un plan non testé n''est pas un plan.</li><li>La communication de crise doit être factuelle et coordonnée.</li></ul></div>',NULL,NULL,15,1,2),
(91,33,'Concevoir un exercice sur table','text','<p>L''exercice sur table (<em>tabletop exercise</em>) réunit les décideurs autour d''un scénario fictif qui se déroule par étapes (« injects »). Il teste les procédures, la coordination et la communication sans aucun risque réel.</p>\n<h3>Conception en cinq étapes</h3>\n<ol><li>Définir 2 ou 3 objectifs (ex. tester la chaîne d''alerte) ;</li><li>Écrire un scénario plausible et <strong>entièrement fictif</strong> ;</li><li>Préparer 5 à 8 injects successifs ;</li><li>Désigner un animateur et un observateur ;</li><li>Prévoir un débriefing structuré : ce qui a fonctionné, ce qui doit changer, qui fait quoi et quand.</li></ol>\n<div class="callout">Un exercice réussi n''est pas un exercice sans erreurs : c''est un exercice qui révèle les failles avant qu''une vraie crise ne le fasse.</div>',NULL,NULL,25,1,1),
(92,33,'Approfondissement : le retour d''expérience (RETEX)','text','<p>Le <strong>retour d''expérience</strong> transforme un exercice ou un incident en améliorations concrètes.</p>\n<h3>Trame en quatre questions</h3>\n<ol><li>Qu''était-il prévu ?</li><li>Que s''est-il réellement passé ?</li><li>Pourquoi des écarts ?</li><li>Que changeons-nous, qui en est responsable, pour quelle date ?</li></ol>\n<p>Le RETEX est <strong>sans recherche de coupable</strong> (« blameless ») : il analyse les systèmes et les procédures, pas les personnes. Cette approche, issue de l''aéronautique et de la santé, favorise la transparence.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Chaque action corrective a un responsable et une échéance.</li><li>On suit la mise en œuvre lors de l''exercice suivant.</li><li>L''absence de recherche de coupable libère la parole.</li></ul></div>',NULL,NULL,15,1,2),
(93,34,'Simulation guidée : préparer la mission « Sentinelle »','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p><strong>Mission fictive.</strong> Quatre consultants d''un cabinet d''audit doivent passer dix jours dans trois villes de Kanaga pour évaluer des centres de santé. L''une des villes connaît des tensions intercommunautaires épisodiques.</p>\n<h3>Consignes</h3>\n<ol><li>Réalisez l''analyse de risques (personnes, informations, matériel, réputation).</li><li>Rédigez le plan de déplacement : itinéraires, horaires, points de contact, protocole de « check-in » quotidien.</li><li>Définissez l''équipement numérique et les règles d''usage.</li><li>Écrivez la procédure en cas de perte de contact pendant plus de quatre heures.</li><li>Prévoyez le débriefing de retour.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Analyse de risques complète</td><td>5</td></tr><tr><td>Plan de déplacement opérationnel</td><td>5</td></tr><tr><td>Règles numériques</td><td>3</td></tr><tr><td>Procédure de perte de contact</td><td>4</td></tr><tr><td>Débriefing prévu</td><td>3</td></tr></tbody></table>',NULL,NULL,60,1,1),
(94,34,'Étude de cas : la clé USB du séminaire','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>À l''issue d''un séminaire, chaque participant reçoit une clé USB « contenant les présentations ». Un responsable financier la branche sur son ordinateur professionnel. Deux semaines plus tard, des courriels frauduleux très crédibles sont envoyés à ses fournisseurs depuis sa messagerie.</p>\n<ol><li>Reconstituez la chaîne d''attaque probable.</li><li>Placez sur un nœud papillon les barrières qui ont manqué.</li><li>Quelle politique adopter vis-à-vis des supports amovibles reçus ?</li><li>Quelles actions immédiates après la découverte ?</li></ol>',NULL,NULL,25,1,2),
(95,34,'Fiche méthode : fiche de mission sécurité','text','<pre><code>MISSION : [nom]        DATES : [..]        CHEF DE MISSION : [..]\nPARTICIPANTS / CONTACTS D''URGENCE : [..]\nANALYSE PAYS : [sources officielles consultées, date]\nITINÉRAIRE ET HÉBERGEMENTS : [..]\nCHECK-IN : [heure quotidienne, canal, destinataire]\nÉQUIPEMENT : [poste dédié, chiffrement, VPN, téléphone de mission]\nPROCÉDURE INCIDENT : [qui appeler, dans quel ordre]\nPERTE DE CONTACT > 4 h : [actions graduées]\nRETOUR : [débriefing, contrôle des appareils]</code></pre>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Une fiche par mission, validée avant le départ.</li><li>Le check-in quotidien est non négociable.</li></ul></div>',NULL,NULL,10,1,3),
(96,35,'Fiche de synthèse (PDF)','document','<p>Modèles de matrice de risques, de plan de déplacement et de fiche d''exercice.</p>',NULL,12,10,1,1),
(97,35,'Exercice : matrice de risques','exercise','<p><strong>Organisation fictive :</strong> une université régionale qui héberge un laboratoire de recherche sur les semences résistantes à la sécheresse.</p>\n<ol><li>Identifiez six risques (fuite de résultats, rançongiciel, vol de matériel, ingérence via partenariats...).</li><li>Évaluez chacun : intention, capacité, vulnérabilité, impact.</li><li>Placez-les dans la matrice.</li><li>Proposez deux contre-mesures par risque critique, classées par coût.</li></ol>',NULL,NULL,45,1,2),
(98,35,'Étude de cas : exercice « Harmattan »','case_study','<p><strong>Simulation pédagogique (fictive).</strong> Un groupe logistique découvre un lundi matin que ses serveurs sont chiffrés par un rançongiciel, en pleine période de dédouanement.</p>\n<ul><li><strong>Inject 1 (08 h 10)</strong> : les agents ne peuvent plus imprimer les déclarations.</li><li><strong>Inject 2 (09 h 00)</strong> : une demande de rançon apparaît ; les attaquants menacent de publier des données clients.</li><li><strong>Inject 3 (10 h 30)</strong> : un journaliste appelle le service communication.</li><li><strong>Inject 4 (12 h 00)</strong> : on découvre que la dernière sauvegarde hors ligne date de trois semaines.</li></ul>\n<h3>Questions de débriefing</h3>\n<ol><li>Qui aurait dû être alerté, dans quel ordre ?</li><li>Quelles obligations de notification (autorité de protection des données, clients) s''appliquent ?</li><li>Pourquoi est-il déconseillé de payer la rançon ?</li><li>Quelles trois mesures auraient le plus réduit l''impact ?</li></ol>',NULL,NULL,40,1,3),
(99,35,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Défense en profondeur</dt><dd>Superposition de couches de protection.</dd><dt>Duty of care</dt><dd>Devoir de protection de l&#039;employeur envers ses collaborateurs.</dd><dt>Exercice sur table</dt><dd>Simulation de crise par étapes (injects).</dd><dt>Matrice de risques</dt><dd>Croisement probabilité × impact pour prioriser.</dd><dt>Nœud papillon</dt><dd>Représentation causes, événement, conséquences avec barrières.</dd><dt>RETEX</dt><dd>Retour d&#039;expérience transformé en actions correctives.</dd><dt>RPO</dt><dd>Perte de données maximale acceptable.</dd><dt>RTO</dt><dd>Durée maximale d&#039;interruption acceptable.</dd></dl>',NULL,NULL,10,1,4),
(100,35,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>ISO 22301, Sécurité et résilience : Systèmes de management de la continuité d''activité.<small>Référence de la continuité d&#039;activité.</small></li><li>ISO 31000, Management du risque : Lignes directrices.<small>Principes généraux de l&#039;analyse de risques.</small></li><li>ANSSI (France), <em>Guide d''hygiène informatique</em> (accès libre).<small>Mesures défensives prioritaires et concrètes.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5);
INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(101,36,'Briefing vidéo : le terrain numérique','video','<p>Panorama visuel des menaces numériques et de la posture de l''analyste.</p>',NULL,13,4,1,1),
(102,36,'Comprendre le cyberespionnage','text','<p>Le cyberespionnage désigne l''accès non autorisé à des systèmes d''information pour y dérober des données, de façon discrète et souvent prolongée. Il se distingue du cybercrime (motivation financière directe) et du sabotage (destruction), même si les frontières sont poreuses.</p>\n<h3>Les acteurs</h3>\n<ul><li>Groupes liés à des États, souvent désignés par les éditeurs de sécurité sous le terme <strong>APT</strong> (<em>Advanced Persistent Threat</em>) ;</li><li>Mercenaires numériques et sociétés de surveillance commerciale ;</li><li>Groupes criminels revendant des accès.</li></ul>\n<h3>La chaîne d''attaque (modèle conceptuel)</h3>\n<ol><li>Reconnaissance (souvent en sources ouvertes) ;</li><li>Accès initial (hameçonnage ciblé, identifiants volés) ;</li><li>Installation et persistance ;</li><li>Mouvement latéral ;</li><li>Exfiltration.</li></ol>\n<p>Connaître cette chaîne sert à <strong>placer des défenses à chaque étape</strong> : moins d''informations exposées publiquement, authentification forte, détection des comportements anormaux, segmentation des réseaux, surveillance des flux sortants.</p>\n<div class="note">Le cadre de référence MITRE ATT&amp;CK, librement consultable, décrit de façon structurée les tactiques et techniques observées. Il est utilisé ici comme langage commun de défense.</div>',NULL,NULL,25,1,2),
(103,36,'Approfondissement : le paysage cyber africain','text','<p>La transformation numérique rapide du continent s''accompagne d''une croissance des menaces. Les rapports publics d''organisations comme INTERPOL (évaluations des cybermenaces en Afrique) soulignent notamment :</p>\n<ul><li>les escroqueries en ligne et la compromission de messageries professionnelles ;</li><li>les rançongiciels visant entreprises et administrations ;</li><li>les fraudes liées au paiement mobile ;</li><li>les campagnes d''hameçonnage ciblant les clients bancaires.</li></ul>\n<h3>Les réponses institutionnelles</h3>\n<ul><li>Création d''équipes nationales de réponse aux incidents (CERT/CSIRT) dans de nombreux pays ;</li><li>Adoption de lois sur la cybercriminalité et la protection des données ;</li><li>La Convention de Malabo (Union africaine, 2014) est entrée en vigueur en 2023 après avoir atteint le nombre requis de ratifications.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>La fraude financière domine les menaces signalées.</li><li>Les CERT nationaux sont des interlocuteurs clés.</li><li>Le cadre juridique continental se consolide.</li></ul></div>',NULL,NULL,15,1,3),
(104,37,'Techniques de recherche avancées','text','<p>L''OSINT avancé se caractérise par la précision des requêtes, la capacité à <strong>pivoter</strong> d''un indice à l''autre et une rigoureuse hygiène opérationnelle.</p>\n<h3>Opérateurs de recherche</h3>\n<table><thead><tr><th>Opérateur</th><th>Usage</th><th>Exemple</th></tr></thead><tbody>\n<tr><td><code>site:</code></td><td>Limiter à un domaine</td><td><code>site:gouv.sn rapport annuel</code></td></tr>\n<tr><td><code>filetype:</code></td><td>Type de document</td><td><code>filetype:pdf budget santé 2025</code></td></tr>\n<tr><td><code>"..."</code></td><td>Expression exacte</td><td><code>"appel d''offres" "fibre optique"</code></td></tr>\n<tr><td><code>-</code></td><td>Exclure un terme</td><td><code>jaguar -voiture</code></td></tr>\n</tbody></table>\n<h3>Le pivot</h3>\n<p>Un indicateur en révèle d''autres : un nom de domaine mène à son historique d''enregistrement public, à ses certificats TLS (journaux de transparence), aux autres sites hébergés sur la même infrastructure. Chaque pivot est noté dans un journal d''enquête.</p>\n<h3>Hygiène de l''enquêteur</h3>\n<ul><li>Environnement de travail dédié et séparé de ses comptes personnels ;</li><li>Aucune interaction avec les cibles (pas de « like », pas de message, pas de demande d''ami) ;</li><li>Respect des conditions d''utilisation des plateformes ;</li><li>Collecte minimale de données personnelles.</li></ul>',NULL,NULL,30,1,1),
(105,37,'Approfondissement : documenter une enquête ouverte','text','<p>Le <strong>Protocole de Berkeley</strong> sur les enquêtes numériques en sources ouvertes (publié en 2020 par le Human Rights Center de l''Université de Californie à Berkeley et le Haut-Commissariat des Nations unies aux droits de l''homme) fixe des standards professionnels pour la collecte, la préservation et la vérification d''informations en ligne.</p>\n<h3>Principes retenus</h3>\n<ul><li><strong>Exactitude</strong> et <strong>impartialité</strong> ;</li><li><strong>Préservation</strong> des contenus avec métadonnées et empreintes ;</li><li><strong>Sécurité</strong> de l''enquêteur et des personnes concernées ;</li><li><strong>Légalité</strong> et respect de la vie privée ;</li><li><strong>Documentation</strong> complète de la méthodologie.</li></ul>\n<h3>Journal d''enquête type</h3>\n<pre><code>Date/heure UTC | Requête / URL | Résultat | Capture (fichier, SHA-256) | Commentaire</code></pre>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un standard international existe : s''y référer.</li><li>Tout ce qui n''est pas documenté n''existe pas.</li><li>La sécurité de l''enquêteur fait partie de la méthode.</li></ul></div>',NULL,NULL,15,1,2),
(106,38,'Empreinte numérique organisationnelle','text','<p>L''empreinte numérique d''une organisation est l''ensemble des traces publiquement observables : sites, sous-domaines, adresses e-mail, profils des employés, documents publiés, dépôts de code, offres d''emploi détaillant les technologies utilisées...</p>\n<h3>Pourquoi l''analyser ?</h3>\n<p>Un attaquant commence par là. L''analyser <strong>pour sa propre organisation</strong> (ou pour un client qui l''a mandaté par écrit) permet de réduire la surface d''attaque.</p>\n<h3>Grille d''audit d''exposition</h3>\n<ul><li><strong>Domaines et sous-domaines</strong> : services oubliés, environnements de test exposés ;</li><li><strong>Documents publics</strong> : métadonnées révélant noms d''utilisateurs, versions logicielles ;</li><li><strong>Personnes</strong> : organigramme reconstituable, formats d''adresses e-mail ;</li><li><strong>Fuites</strong> : identifiants apparus dans des fuites publiques connues (à vérifier via des services de notification légitimes).</li></ul>\n<div class="warning">Un audit d''exposition sur une organisation tierce nécessite un <strong>mandat écrit</strong>. Sans autorisation, même une collecte « passive » peut poser problème juridiquement et déontologiquement.</div>',NULL,NULL,25,1,1),
(107,38,'Approfondissement : réduire l''empreinte de son organisation','text','<p>Après l''audit vient la <strong>remédiation</strong>. Les mesures les plus efficaces sont souvent simples.</p>\n<table><thead><tr><th>Exposition constatée</th><th>Mesure</th></tr></thead><tbody>\n<tr><td>Sous-domaine de test accessible</td><td>Désactiver ou protéger par authentification</td></tr>\n<tr><td>Métadonnées dans les PDF publiés</td><td>Nettoyage systématique avant publication</td></tr>\n<tr><td>Organigramme détaillé en ligne</td><td>Publier des fonctions génériques et des adresses de service</td></tr>\n<tr><td>Identifiants dans des fuites</td><td>Réinitialisation, authentification multifacteur</td></tr>\n<tr><td>Technologies détaillées dans les offres d''emploi</td><td>Formulations plus générales</td></tr>\n</tbody></table>\n<p>Ajoutez un fichier <code>security.txt</code> (norme RFC 9116) sur votre site pour indiquer comment signaler une vulnérabilité.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Prioriser les expositions les plus exploitables.</li><li>Automatiser le nettoyage des documents.</li><li>Répéter l''audit périodiquement.</li></ul></div>',NULL,NULL,15,1,2),
(108,39,'Exploiter les métadonnées','text','<p>Les métadonnées sont des « données sur les données » : auteur d''un document, logiciel utilisé, dates de création et de modification, modèle d''appareil photo, parfois coordonnées GPS.</p>\n<h3>Types courants</h3>\n<table><thead><tr><th>Format</th><th>Métadonnées typiques</th></tr></thead><tbody>\n<tr><td>Photo (EXIF)</td><td>Appareil, date, réglages, éventuellement GPS</td></tr>\n<tr><td>PDF</td><td>Auteur, créateur, producteur, dates</td></tr>\n<tr><td>Bureautique</td><td>Auteur, dernier modificateur, révisions, commentaires</td></tr>\n</tbody></table>\n<h3>Précautions d''interprétation</h3>\n<ul><li>Les métadonnées peuvent être <strong>absentes</strong> (supprimées par les réseaux sociaux) ou <strong>falsifiées</strong> ;</li><li>L''horloge d''un appareil peut être mal réglée ;</li><li>Une métadonnée est un indice, jamais une preuve isolée.</li></ul>\n<h3>Préservation de la preuve</h3>\n<p>Dans un cadre d''enquête autorisée, on travaille sur une <strong>copie</strong>, on calcule l''<strong>empreinte cryptographique</strong> (SHA-256) de l''original et on consigne chaque manipulation (chaîne de traçabilité).</p>\n<div class="callout"><strong>Réflexe défensif :</strong> nettoyez les métadonnées des documents que votre organisation publie.</div>',NULL,NULL,25,1,1),
(109,39,'Approfondissement : nettoyer les métadonnées avant publication','text','<p>Le réflexe défensif le plus rentable : <strong>supprimer les métadonnées</strong> des fichiers que l''on diffuse.</p>\n<h3>Procédure recommandée</h3>\n<ol><li>Exporter le document final en PDF depuis le logiciel de traitement de texte, en désactivant l''inclusion des propriétés personnelles ;</li><li>Vérifier les propriétés du PDF (auteur, créateur, logiciel) ;</li><li>Pour les photos, supprimer les données EXIF (notamment la géolocalisation) ou désactiver la géolocalisation de l''appareil ;</li><li>Contrôler un échantillon avant chaque campagne de publication.</li></ol>\n<p>Des outils libres comme ExifTool permettent d''afficher et de supprimer les métadonnées de nombreux formats.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les photos de smartphones contiennent souvent des coordonnées GPS.</li><li>Les documents bureautiques peuvent conserver des commentaires et révisions.</li><li>Intégrer le nettoyage à la procédure de publication.</li></ul></div>',NULL,NULL,15,1,2),
(110,40,'Simulation guidée : audit « Kilimanjaro Logistics » complet','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Vous disposez d''un <strong>mandat écrit</strong> (fictif) de la société « Kilimanjaro Logistics » pour évaluer son exposition publique. Les données suivantes sont synthétiques :</p>\n<pre><code>Sous-domaines : www, mail, vpn, test-erp, old-portal, dev\nCertificats récents : erp-preprod.kilimanjaro-logistics.example\nDocument public : Rapport_annuel.pdf  (Auteur: j.mwangi ; Producteur: Office 2013)\nOffre d''emploi : « administrateur système Windows Server 2012, VPN FortiGate »\nProfils publics : 14 employés, format d''adresse prenom.nom@...</code></pre>\n<h3>Consignes</h3>\n<ol><li>Classez les expositions en critique / importante / mineure en justifiant.</li><li>Expliquez, pour les trois plus graves, comment un attaquant pourrait les exploiter (sans détail technique offensif).</li><li>Proposez une remédiation par exposition, avec responsable et délai.</li><li>Rédigez un résumé exécutif d''une demi-page pour la direction, sans jargon.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Classement argumenté</td><td>5</td></tr><tr><td>Compréhension des risques</td><td>4</td></tr><tr><td>Remédiations concrètes</td><td>6</td></tr><tr><td>Résumé exécutif accessible</td><td>5</td></tr></tbody></table>',NULL,NULL,75,1,1),
(111,40,'Étude de cas : la photo du bureau','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Pour célébrer un contrat, le service communication d''une agence publique publie une photo de l''équipe dans son bureau. En arrière-plan, un tableau blanc affiche des noms de serveurs et un post-it porte un mot de passe Wi-Fi.</p>\n<ol><li>Quelles informations un tiers peut-il tirer de la photo ?</li><li>Quelles actions immédiates après la publication ?</li><li>Quelle règle intégrer à la procédure de publication des contenus visuels ?</li></ol>',NULL,NULL,20,1,2),
(112,40,'Fiche méthode : structure d''un rapport d''exposition','text','<ol><li><strong>Mandat et périmètre</strong> (référence du mandat écrit, exclusions)</li><li><strong>Résumé exécutif</strong> (risques principaux, actions prioritaires)</li><li><strong>Méthodologie</strong> (sources ouvertes consultées, dates)</li><li><strong>Constats</strong> (tableau : exposition, gravité, preuve archivée)</li><li><strong>Recommandations</strong> (responsable, délai, coût)</li><li><strong>Annexes</strong> (journal d''enquête, empreintes des fichiers)</li><li><strong>Destruction des données</strong> collectées à la clôture</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le rapport lui-même est confidentiel : marquage et diffusion restreinte.</li><li>Aucune donnée personnelle superflue.</li></ul></div>',NULL,NULL,10,1,3),
(113,41,'Fiche de synthèse (PDF)','document','<p>Opérateurs de recherche, grille d''audit d''exposition et procédure de préservation des fichiers.</p>',NULL,14,10,1,1),
(114,41,'Exercice : audit d''exposition d''une organisation fictive','exercise','<p><strong>Environnement :</strong> dossier de données synthétiques « Kilimanjaro Logistics » (organisation fictive) : liste de sous-domaines, trois documents PDF, cinq profils professionnels fictifs, une offre d''emploi.</p>\n<ol><li>Recensez toutes les informations exploitables par un attaquant.</li><li>Déduisez le format probable des adresses e-mail.</li><li>Identifiez les métadonnées sensibles des documents.</li><li>Classez les expositions par gravité.</li><li>Rédigez cinq recommandations de réduction de l''exposition.</li></ol>\n<div class="note">Toutes les données sont fictives. Ne transposez jamais l''exercice sur une organisation réelle sans mandat écrit.</div>',NULL,NULL,50,1,2),
(115,41,'Étude de cas : le document trop bavard','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un ministère publie en ligne un rapport PDF. Ses métadonnées révèlent le nom d''utilisateur réseau de l''auteur, la version d''un logiciel obsolète et le chemin d''un serveur interne. Quelques semaines plus tard, une campagne d''hameçonnage très ciblée vise précisément ce service.</p>\n<ol><li>Quelles informations ont pu servir à la reconnaissance ?</li><li>Quelle procédure de publication aurait évité la fuite ?</li><li>Comment sensibiliser les équipes de communication ?</li></ol>',NULL,NULL,30,1,3),
(116,41,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>APT</dt><dd>Menace persistante avancée : groupe sophistiqué et durable.</dd><dt>Chaîne d&#039;attaque</dt><dd>Étapes successives d&#039;une intrusion, de la reconnaissance à l&#039;exfiltration.</dd><dt>Chaîne de traçabilité</dt><dd>Documentation de toutes les manipulations d&#039;une preuve.</dd><dt>EXIF</dt><dd>Format de métadonnées des photographies.</dd><dt>Empreinte cryptographique</dt><dd>Valeur (ex. SHA-256) garantissant l&#039;intégrité d&#039;un fichier.</dd><dt>Empreinte numérique</dt><dd>Ensemble des traces publiquement observables.</dd><dt>Métadonnées</dt><dd>Données décrivant un fichier (auteur, date, appareil, GPS...).</dd><dt>Pivot</dt><dd>Passage d&#039;un indicateur à d&#039;autres indicateurs liés.</dd><dt>security.txt</dt><dd>Fichier normalisé (RFC 9116) indiquant comment signaler une vulnérabilité.</dd></dl>',NULL,NULL,10,1,4),
(117,41,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Haut-Commissariat des Nations unies aux droits de l''homme et Human Rights Center (UC Berkeley), <em>Protocole de Berkeley sur les enquêtes numériques en sources ouvertes</em>, 2022 (accès libre).<small>Standards professionnels de l&#039;OSINT.</small></li><li>MITRE ATT&amp;CK : base de connaissances des tactiques et techniques (attack.mitre.org).<small>Langage commun de la défense.</small></li><li>Hutchins, Eric M., Cloppert, Michael J. et Amin, Rohan M., « Intelligence-Driven Computer Network Defense Informed by Analysis of Adversary Campaigns and Intrusion Kill Chains », Lockheed Martin, 2011.<small>Article fondateur de la chaîne d&#039;attaque.</small></li><li>IETF, RFC 9116, <em>A File Format to Aid in Security Vulnerability Disclosure</em>, 2022.<small>Norme security.txt.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(118,42,'Briefing vidéo : de la donnée à la décision','video','<p>Les niveaux de la CTI et leurs destinataires.</p>',NULL,15,4,1,1),
(119,42,'Les fondamentaux de la CTI','text','<p>La CTI applique le cycle du renseignement au domaine cyber. Elle répond à des questions comme : <em>qui pourrait nous viser, comment, et que devons-nous surveiller ?</em></p>\n<h3>Trois niveaux</h3>\n<table><thead><tr><th>Niveau</th><th>Destinataire</th><th>Contenu</th></tr></thead><tbody>\n<tr><td>Stratégique</td><td>Direction</td><td>Tendances, acteurs, impacts métier</td></tr>\n<tr><td>Opérationnel</td><td>Responsables sécurité</td><td>Campagnes, modes opératoires (TTP)</td></tr>\n<tr><td>Tactique</td><td>SOC / équipes techniques</td><td>Indicateurs de compromission (IoC)</td></tr>\n</tbody></table>\n<h3>Le modèle en diamant</h3>\n<p>Chaque événement d''intrusion est décrit par quatre sommets reliés : <strong>adversaire</strong>, <strong>capacité</strong>, <strong>infrastructure</strong>, <strong>victime</strong>. Connaître un sommet permet de rechercher les autres.</p>\n<h3>La pyramide de la douleur</h3>\n<p>Bloquer une adresse IP gêne peu un attaquant (il en change facilement) ; détecter ses <strong>TTP</strong> (comportements) l''oblige à modifier ses méthodes, ce qui est beaucoup plus coûteux pour lui. La CTI vise donc le haut de la pyramide.</p>',NULL,NULL,30,1,2),
(120,42,'Approfondissement : formats et partage de la CTI','text','<p>Pour être exploitable par des machines, la CTI s''échange dans des formats normalisés :</p>\n<ul><li><strong>STIX 2.1</strong> (Structured Threat Information eXpression), standard OASIS décrivant objets et relations : acteurs, campagnes, indicateurs, techniques ;</li><li><strong>TAXII</strong>, protocole de transport des données STIX ;</li><li>Des plateformes libres comme <strong>MISP</strong> permettent de partager des indicateurs au sein de communautés de confiance.</li></ul>\n<h3>Qualité d''un indicateur</h3>\n<p>Un bon IoC est <strong>contextualisé</strong> (campagne, date d''observation, confiance), <strong>daté</strong> (les infrastructures changent vite) et accompagné d''un marquage TLP.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>STIX décrit, TAXII transporte.</li><li>Un indicateur sans contexte génère des faux positifs.</li><li>Le partage se fait dans des communautés de confiance.</li></ul></div>',NULL,NULL,15,1,3),
(121,43,'Comprendre une infrastructure','text','<p>Toute activité en ligne repose sur une infrastructure : noms de domaine, serveurs, adresses IP, certificats, hébergeurs. Ces éléments laissent des traces publiques exploitables légalement.</p>\n<h3>Sources ouvertes d''infrastructure</h3>\n<ul><li><strong>WHOIS / RDAP</strong> : informations d''enregistrement (souvent masquées) ;</li><li><strong>DNS historique</strong> : évolution des résolutions d''un domaine ;</li><li><strong>Journaux de transparence des certificats</strong> : certificats émis pour un domaine ;</li><li><strong>Moteurs d''exposition</strong> recensant les services visibles sur Internet ;</li><li><strong>Registres régionaux</strong> (AFRINIC pour l''Afrique) : attribution des blocs d''adresses.</li></ul>\n<h3>Exemple de raisonnement (données fictives)</h3>\n<p>Un domaine d''hameçonnage imitant une banque est hébergé sur une IP qui sert aussi trois autres domaines récemment enregistrés, imitant d''autres institutions financières. Hypothèse : une même campagne. Action : signalement aux CSIRT et aux registrars, alerte aux clients.</p>\n<div class="note">L''analyse d''infrastructure reste passive : on consulte des registres publics, on n''interagit pas avec les systèmes d''un tiers au-delà d''un usage normal.</div>',NULL,NULL,25,1,1),
(122,43,'Approfondissement : typosquattage et domaines trompeurs','text','<p>Le <strong>typosquattage</strong> consiste à enregistrer des noms de domaine proches d''une marque (lettre inversée, tiret ajouté, extension différente, caractères visuellement similaires) pour tromper les utilisateurs.</p>\n<h3>Exemples de variantes (fictives)</h3>\n<pre><code>banque-exemple.com   ->  banque-exernple.com  (rn au lieu de m)\n                     ->  banqueexemple-ci.com\n                     ->  banque-exemple.co</code></pre>\n<h3>Défense</h3>\n<ul><li>Surveiller les nouveaux enregistrements de domaines proches de sa marque (services de veille, journaux de transparence des certificats) ;</li><li>Enregistrer préventivement les variantes les plus évidentes ;</li><li>Signaler les domaines frauduleux au registrar et au CERT national ;</li><li>Mettre en place SPF, DKIM et DMARC pour limiter l''usurpation de ses adresses e-mail.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les domaines proches sont un vecteur majeur d''hameçonnage.</li><li>La surveillance est passive et légale.</li><li>DMARC protège la réputation de sa messagerie.</li></ul></div>',NULL,NULL,15,1,2),
(123,44,'Communiquer en sécurité','text','<p>Protéger ses communications est un droit et une nécessité professionnelle : journalistes, avocats, ONG, entreprises et administrations y sont confrontés.</p>\n<h3>Notions clés</h3>\n<ul><li><strong>Chiffrement en transit</strong> (TLS) : protège le trajet entre vous et le serveur ;</li><li><strong>Chiffrement de bout en bout</strong> : seuls l''émetteur et le destinataire peuvent lire ;</li><li><strong>Vérification des clés</strong> : comparer les codes de sécurité pour éviter l''interposition ;</li><li><strong>Métadonnées</strong> : même chiffrées, les communications révèlent qui parle à qui et quand.</li></ul>\n<h3>Bonnes pratiques</h3>\n<ol><li>Authentification multifacteur sur toutes les messageries professionnelles ;</li><li>Applications à jour, verrouillage des appareils ;</li><li>Messages éphémères pour les échanges sensibles ;</li><li>Séparation des usages personnels et professionnels ;</li><li>Prudence avec les réseaux Wi-Fi publics.</li></ol>\n<div class="callout">La sécurité d''une communication dépend du maillon le plus faible : un téléphone non verrouillé annule le meilleur chiffrement.</div>',NULL,NULL,25,1,1),
(124,44,'Approfondissement : l''authentification multifacteur','text','<p>L''<strong>authentification multifacteur (MFA)</strong> combine au moins deux éléments : ce que l''on sait (mot de passe), ce que l''on possède (téléphone, clé), ce que l''on est (biométrie).</p>\n<table><thead><tr><th>Méthode</th><th>Robustesse</th><th>Commentaire</th></tr></thead><tbody>\n<tr><td>Code par SMS</td><td>Moyenne</td><td>Exposée aux détournements de carte SIM</td></tr>\n<tr><td>Application d''authentification (codes temporaires)</td><td>Bonne</td><td>Fonctionne hors connexion</td></tr>\n<tr><td>Notification « approuver »</td><td>Bonne si correspondance de nombre</td><td>Attention à la fatigue des notifications</td></tr>\n<tr><td>Clé de sécurité FIDO2 / passkeys</td><td>Très élevée</td><td>Résistante à l''hameçonnage</td></tr>\n</tbody></table>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Même un SMS vaut mieux que rien.</li><li>Privilégier FIDO2 pour les comptes à privilèges.</li><li>Ne jamais approuver une notification non sollicitée.</li></ul></div>',NULL,NULL,15,1,2),
(125,45,'Détecter l''anomalie','text','<p>La détection consiste à repérer, dans le flux d''événements d''un système <strong>que l''on est autorisé à surveiller</strong>, ce qui s''écarte du comportement normal.</p>\n<h3>Signaux typiques dans les journaux d''authentification</h3>\n<ul><li>Nombreux échecs de connexion suivis d''un succès ;</li><li>Connexion depuis un pays inhabituel ou à une heure atypique ;</li><li>« Voyage impossible » : deux connexions éloignées géographiquement en peu de temps ;</li><li>Création de règles de transfert automatique dans une messagerie ;</li><li>Volume inhabituel de téléchargements.</li></ul>\n<h3>Extrait de journal synthétique</h3>\n<pre><code>2026-03-04 02:11:07 user=a.diallo  src=196.0.2.14  result=FAIL\n2026-03-04 02:11:09 user=a.diallo  src=196.0.2.14  result=FAIL\n2026-03-04 02:11:12 user=a.diallo  src=196.0.2.14  result=SUCCESS\n2026-03-04 02:14:40 user=a.diallo  action=create_forward_rule dest=external</code></pre>\n<p>Lecture : connexion nocturne après échecs, puis création d''une règle de transfert vers l''extérieur : scénario classique de compromission de messagerie. Réponse : suspendre la session, réinitialiser le mot de passe, supprimer la règle, enquêter sur l''étendue.</p>\n<div class="note">Une alerte n''est pas une preuve : il faut qualifier (vrai ou faux positif) avant d''agir, et documenter.</div>',NULL,NULL,30,1,1),
(126,45,'Approfondissement : écrire une règle de détection','text','<p>Les équipes de détection formalisent leurs hypothèses en <strong>règles</strong>. Le format ouvert <strong>Sigma</strong> permet de décrire une détection indépendamment de l''outil (SIEM) utilisé.</p>\n<h3>Exemple pédagogique simplifié</h3>\n<pre><code>title: Création de règle de transfert de messagerie vers l''extérieur\nlogsource: { product: messagerie, service: audit }\ndetection:\n  selection:\n    action: create_forward_rule\n    destination|endswith: externe\n  condition: selection\nlevel: high</code></pre>\n<h3>Cycle de vie d''une règle</h3>\n<ol><li>Hypothèse (tirée de la CTI) ;</li><li>Écriture et test sur données historiques ;</li><li>Mesure des faux positifs ;</li><li>Déploiement, puis revue périodique.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Une règle part d''une hypothèse documentée.</li><li>Tester avant de déployer.</li><li>Sigma facilite le partage entre organisations.</li></ul></div>',NULL,NULL,15,1,2),
(127,46,'Simulation guidée : bulletin CTI hebdomadaire du secteur bancaire','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Vous animez la cellule CTI (fictive) d''une association de banques de la zone « UMOK ». Cette semaine, vous recevez :</p>\n<ul><li>de la banque A : 3 domaines d''hameçonnage imitant son application mobile ;</li><li>de la banque B : une hausse de tentatives de connexion depuis des adresses déjà signalées ;</li><li>du CERT national : un avis sur une campagne de faux SMS de livraison ;</li><li>d''un éditeur de sécurité : un rapport public sur un groupe ciblant les banques africaines.</li></ul>\n<h3>Consignes</h3>\n<ol><li>Rédigez un bulletin en trois niveaux : stratégique (5 lignes pour les directions générales), opérationnel (campagnes et TTP), tactique (indicateurs).</li><li>Attribuez un marquage TLP à chaque partie et justifiez.</li><li>Formulez trois recommandations mesurables.</li><li>Proposez un indicateur de performance du dispositif de partage.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Trois niveaux bien distingués</td><td>6</td></tr><tr><td>Marquages TLP justifiés</td><td>4</td></tr><tr><td>Recommandations mesurables</td><td>5</td></tr><tr><td>Indicateur de performance pertinent</td><td>5</td></tr></tbody></table>',NULL,NULL,60,1,1),
(128,46,'Étude de cas : le faux positif qui coûtait cher','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Une banque bloque automatiquement une liste d''adresses IP reçue d''un partenaire. Parmi elles figure l''adresse d''un fournisseur de services de paiement partagée par de nombreux clients : les paiements en ligne sont interrompus pendant six heures.</p>\n<ol><li>Quelles informations manquaient à l''indicateur (contexte, date, confiance) ?</li><li>Quelle procédure de qualification aurait évité l''incident ?</li><li>Comment la pyramide de la douleur éclaire-t-elle le choix de détecter des comportements plutôt que des adresses ?</li></ol>',NULL,NULL,25,1,2),
(129,46,'Fiche méthode : modèle de bulletin CTI','text','<pre><code>BULLETIN CTI N° [..]   PÉRIODE : [..]   MARQUAGE GLOBAL : TLP:[..]\n1. SYNTHÈSE STRATÉGIQUE (direction)         : 5 lignes, impact métier\n2. CAMPAGNES OBSERVÉES (sécurité)           : description, TTP (ATT&CK), cibles\n3. INDICATEURS (SOC)                        : type | valeur | 1re/dernière observation | confiance\n4. RECOMMANDATIONS                          : action | responsable | échéance\n5. SOURCES                                  : émetteur | date | fiabilité</code></pre>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Chaque indicateur porte une date et un niveau de confiance.</li><li>La synthèse stratégique ne contient pas de jargon.</li></ul></div>',NULL,NULL,10,1,3),
(130,47,'Fiche de synthèse (PDF)','document','<p>Modèle de rapport CTI, modèle en diamant et liste des signaux de détection.</p>',NULL,16,10,1,1),
(131,47,'Exercice : analyser un journal synthétique','exercise','<p>Le jeu de données fourni (fictif) contient 200 lignes d''authentification d''une organisation imaginaire sur une semaine.</p>\n<ol><li>Établissez le profil normal (horaires, origines, volumes).</li><li>Identifiez au moins trois anomalies et qualifiez-les.</li><li>Placez l''incident principal dans le modèle en diamant.</li><li>Associez les comportements observés à des techniques MITRE ATT&amp;CK.</li><li>Rédigez un rapport CTI tactique d''une page avec recommandations.</li></ol>\n<pre><code>2026-03-01 08:02:44 user=k.mensah src=41.0.0.21 result=SUCCESS\n2026-03-02 23:47:10 user=k.mensah src=203.0.113.9 result=SUCCESS\n2026-03-02 23:47:58 user=k.mensah action=mass_download files=412</code></pre>',NULL,NULL,50,1,2),
(132,47,'Étude de cas : campagne contre le secteur bancaire','case_study','<p><strong>Scénario pédagogique (fictif).</strong> En trois semaines, quatre banques d''une même zone monétaire signalent des courriels imitant leur autorité de régulation et contenant une pièce jointe piégée. Le CSIRT régional coordonne l''analyse.</p>\n<ol><li>Quelles informations partager entre banques, et sous quel format (niveau TLP) ?</li><li>Quels indicateurs tactiques et quels TTP retenir ?</li><li>Quel message stratégique adresser aux directions générales ?</li><li>Quelles mesures de sensibilisation des clients ?</li></ol>',NULL,NULL,35,1,3),
(133,47,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>CTI</dt><dd>Cyber Threat Intelligence : renseignement sur les menaces cyber.</dd><dt>DMARC</dt><dd>Politique d&#039;authentification des e-mails d&#039;un domaine.</dd><dt>IoC</dt><dd>Indicateur de compromission (adresse, domaine, empreinte...).</dd><dt>MFA</dt><dd>Authentification multifacteur.</dd><dt>Modèle en diamant</dt><dd>Adversaire, capacité, infrastructure, victime.</dd><dt>STIX / TAXII</dt><dd>Format et protocole d&#039;échange de la CTI.</dd><dt>Sigma</dt><dd>Format ouvert de règles de détection.</dd><dt>TTP</dt><dd>Tactiques, techniques et procédures d&#039;un adversaire.</dd><dt>Typosquattage</dt><dd>Enregistrement de domaines proches d&#039;une marque pour tromper.</dd></dl>',NULL,NULL,10,1,4),
(134,47,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Caltagirone, Sergio, Pendergast, Andrew et Betz, Christopher, <em>The Diamond Model of Intrusion Analysis</em>, 2013.<small>Modèle d&#039;analyse des intrusions.</small></li><li>Bianco, David J., « The Pyramid of Pain », 2013.<small>Hiérarchie des indicateurs selon le coût pour l&#039;adversaire.</small></li><li>OASIS, <em>STIX Version 2.1</em>, 2021.<small>Standard d&#039;échange de la CTI.</small></li><li>FIRST, <em>Traffic Light Protocol 2.0</em>, 2022.<small>Règles de partage.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(135,48,'Briefing vidéo : la boîte à outils de l''analyste','video','<p>Panorama visuel des familles d''outils et de la règle d''or : mandat, légalité, proportionnalité.</p>',NULL,17,4,1,1),
(136,48,'Panorama des outils OSINT','text','<table><thead><tr><th>Outil</th><th>Fonction</th><th>Usage légitime type</th></tr></thead><tbody>\n<tr><td><strong>Maltego</strong></td><td>Visualisation de liens sous forme de graphe ; « transformations » interrogeant des sources</td><td>Cartographier les relations publiques entre entreprises et domaines dans une enquête de conformité</td></tr>\n<tr><td><strong>SpiderFoot</strong></td><td>Automatisation de la collecte ouverte autour d''un indicateur</td><td>Évaluer l''exposition de sa propre organisation</td></tr>\n<tr><td><strong>theHarvester</strong></td><td>Recensement d''adresses e-mail, sous-domaines et hôtes publics</td><td>Audit de surface d''attaque mandaté</td></tr>\n<tr><td><strong>Recon-ng</strong></td><td>Cadre modulaire de reconnaissance en ligne de commande</td><td>Industrialiser une collecte ouverte documentée</td></tr>\n<tr><td><strong>Shodan</strong></td><td>Moteur recensant les services exposés sur Internet</td><td>Repérer ses propres équipements exposés par erreur ; études statistiques</td></tr>\n<tr><td><strong>Google Earth</strong></td><td>Imagerie et historique géographique</td><td>Géolocalisation, suivi environnemental, préparation logistique</td></tr>\n</tbody></table>\n<h3>Bonnes pratiques communes</h3>\n<ul><li>Respecter les conditions d''utilisation et les licences ;</li><li>Ne fournir aux outils que les clés d''API légitimement obtenues ;</li><li>Limiter la collecte de données personnelles au strict nécessaire ;</li><li>Conserver un journal des requêtes pour la traçabilité.</li></ul>\n<div class="warning">Ces outils ne doivent jamais servir à profiler, suivre ou harceler une personne privée. Un tel usage peut constituer une infraction (atteinte à la vie privée, harcèlement) et viole la charte AFRICA''SPY.</div>',NULL,NULL,30,1,2),
(137,48,'Approfondissement : choisir l''outil selon la question','text','<p>L''outil découle de la question, jamais l''inverse. Une matrice simple aide à choisir.</p>\n<table><thead><tr><th>Question</th><th>Outil adapté</th><th>Alternative manuelle</th></tr></thead><tbody>\n<tr><td>Quelles relations publiques entre ces sociétés ?</td><td>Maltego (graphe)</td><td>Registres de commerce + tableur</td></tr>\n<tr><td>Que voit-on de notre organisation sur Internet ?</td><td>SpiderFoot, theHarvester</td><td>Moteurs de recherche + journaux de certificats</td></tr>\n<tr><td>Nos équipements sont-ils exposés ?</td><td>Shodan (recherche sur nos plages d''adresses)</td><td>Inventaire interne</td></tr>\n<tr><td>Où cette photo publique a-t-elle été prise ?</td><td>Google Earth, imagerie historique</td><td>Cartes topographiques</td></tr>\n</tbody></table>\n<p>L''outil automatise ; il ne remplace ni la vérification, ni le jugement, ni la responsabilité de l''analyste.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Commencer par la question et le mandat.</li><li>Préférer la méthode la plus simple qui suffit.</li><li>Vérifier manuellement les résultats automatisés.</li></ul></div>',NULL,NULL,15,1,3),
(138,49,'Analyse réseau et forensique','text','<h3>Wireshark : analyse de protocoles</h3>\n<p>Wireshark capture et décode le trafic d''un réseau. Usage légitime : diagnostiquer une panne, comprendre un protocole, analyser une capture fournie dans un cadre pédagogique ou d''incident. <strong>Capturer le trafic d''un réseau dont on n''est pas responsable est illégal.</strong></p>\n<h3>Autopsy : investigation de supports</h3>\n<p>Interface graphique d''investigation de disques : chronologie des fichiers, recherche par mots-clés, récupération d''éléments supprimés, extraction de métadonnées. Utilisé par les enquêteurs autorisés et les équipes de réponse à incident, sur des <strong>copies</strong> de supports.</p>\n<h3>Volatility : analyse de la mémoire vive</h3>\n<p>Cadre d''analyse d''images mémoire : processus actifs, connexions, artefacts de logiciels malveillants. Indispensable en réponse à incident, car certaines menaces ne laissent aucune trace sur disque.</p>\n<h3>Principes de l''investigation numérique</h3>\n<ol><li><strong>Mandat</strong> : autorisation écrite ou cadre judiciaire ;</li><li><strong>Préservation</strong> : copie bit à bit, empreinte cryptographique ;</li><li><strong>Traçabilité</strong> : chaîne de possession documentée ;</li><li><strong>Reproductibilité</strong> : un autre expert doit aboutir aux mêmes constats ;</li><li><strong>Neutralité</strong> : rechercher les éléments à charge comme à décharge.</li></ol>',NULL,NULL,30,1,1),
(139,49,'Approfondissement : monter un laboratoire d''entraînement isolé','text','<p>Pour s''exercer légalement à l''analyse réseau et forensique, on construit un <strong>laboratoire isolé</strong>.</p>\n<h3>Architecture minimale</h3>\n<ul><li>Un ordinateur hôte avec un logiciel de virtualisation ;</li><li>Des machines virtuelles connectées à un <strong>réseau interne isolé</strong> (sans accès à Internet ni au réseau de l''organisation) ;</li><li>Des <strong>instantanés</strong> pour revenir à un état propre ;</li><li>Des jeux de données d''entraînement publiés à des fins pédagogiques (captures réseau d''exemple, images disque de démonstration fournies par des projets éducatifs).</li></ul>\n<h3>Règles du laboratoire</h3>\n<ol><li>Aucune donnée réelle de personnes ;</li><li>Aucun échantillon malveillant hors d''un environnement spécifiquement conçu et autorisé ;</li><li>Documentation de chaque exercice.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>L''isolement réseau est la première règle.</li><li>Les instantanés permettent de recommencer sans risque.</li><li>Utiliser des jeux de données pédagogiques publiés.</li></ul></div>',NULL,NULL,20,1,2),
(140,50,'Les équipements de l''analyste de terrain','text','<table><thead><tr><th>Équipement</th><th>Usage légitime</th><th>Limites et règles</th></tr></thead><tbody>\n<tr><td>Jumelles d''observation</td><td>Observation de paysages, de sites publics, d''infrastructures, études environnementales</td><td>Jamais vers des espaces privés ni pour suivre une personne</td></tr>\n<tr><td>Appareil photo professionnel</td><td>Documentation de sites, reportage, constat</td><td>Droit à l''image, interdictions de photographier certains sites sensibles</td></tr>\n<tr><td>GPS de navigation</td><td>Orientation, relevés de terrain, sécurité des missions</td><td>Ne jamais poser de traceur sur un bien d''autrui</td></tr>\n<tr><td>Communications sécurisées</td><td>Liaison des équipes, coordination de crise</td><td>Respect des réglementations radio nationales</td></tr>\n<tr><td>Station d''analyse numérique</td><td>Traitement de données, forensique autorisée</td><td>Isolement, chiffrement, contrôle d''accès</td></tr>\n<tr><td>Protection des documents</td><td>Coffres, broyeurs, sacoches sécurisées</td><td>Adaptés au niveau de classification</td></tr>\n</tbody></table>\n<div class="warning">L''Académie ne fournit aucun plan de fabrication, aucune information sur des dispositifs clandestins (micros, traceurs dissimulés) ni aucune méthode d''interception. Leur usage par des particuliers est illégal dans la plupart des pays.</div>',NULL,NULL,25,1,1),
(141,50,'Approfondissement : entretien et chaîne de responsabilité du matériel','text','<p>Les équipements de terrain sont des actifs sensibles : leur perte peut exposer des données et des personnes.</p>\n<h3>Bonnes pratiques de gestion</h3>\n<ul><li><strong>Inventaire</strong> nominatif (numéro de série, affectataire, date de sortie et de retour) ;</li><li><strong>Chiffrement</strong> des cartes mémoire et appareils qui le permettent ;</li><li><strong>Effacement</strong> des données de mission au retour, après archivage réglementaire ;</li><li><strong>Contrôle</strong> du respect des réglementations locales (photographie de sites, radiocommunications, drones) avant chaque mission.</li></ul>\n<div class="note">Dans de nombreux pays, l''usage de drones et de certains équipements radio est soumis à autorisation préalable. Se renseigner auprès des autorités de l''aviation civile et de régulation des télécommunications.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un matériel perdu est un incident de sécurité.</li><li>Inventaire et chiffrement réduisent le risque.</li><li>La réglementation locale prime.</li></ul></div>',NULL,NULL,15,1,2),
(142,51,'Avant d''utiliser un outil','text','<p>Le professionnel rédige, avant toute investigation, une <strong>note de cadrage</strong> qui répond à six questions :</p>\n<ol><li><strong>Finalité</strong> : quelle question précise ?</li><li><strong>Mandat</strong> : qui autorise, par écrit ?</li><li><strong>Périmètre</strong> : quelles cibles, quelles exclusions ?</li><li><strong>Base légale</strong> : quelles lois s''appliquent (données personnelles, cybercriminalité) ?</li><li><strong>Proportionnalité</strong> : l''outil choisi est-il le moins intrusif possible ?</li><li><strong>Conservation</strong> : combien de temps garde-t-on les données, et comment les détruit-on ?</li></ol>\n<p>Cette discipline protège les personnes concernées, le client et l''analyste lui-même.</p>',NULL,NULL,20,1,1),
(143,51,'Approfondissement : l''éthique face aux outils de surveillance commerciale','text','<p>Des enquêtes publiées par des laboratoires de recherche (par exemple le Citizen Lab de l''Université de Toronto) et par des consortiums de journalistes ont documenté l''usage abusif de logiciels espions commerciaux contre des journalistes, des avocats et des défenseurs des droits humains, y compris en Afrique.</p>\n<h3>Ce que ces affaires enseignent</h3>\n<ul><li>Un outil « réservé aux autorités » peut être détourné en l''absence de contrôle ;</li><li>Les victimes sont souvent celles qui exercent un contre-pouvoir ;</li><li>La responsabilité concerne aussi les vendeurs et les intermédiaires.</li></ul>\n<h3>Position de l''Académie</h3>\n<p>AFRICA''SPY n''enseigne l''usage d''aucun logiciel espion. Ces affaires sont étudiées pour comprendre les risques, renforcer la protection des personnes exposées et nourrir le débat sur le contrôle démocratique.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les abus documentés justifient des garde-fous stricts.</li><li>Protéger les personnes à risque fait partie du métier.</li><li>L''éthique s''applique à toute la chaîne.</li></ul></div>',NULL,NULL,15,1,2),
(144,52,'Simulation guidée : cahier des charges outillage','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Une chambre de commerce fictive crée une cellule de veille de trois personnes chargée de suivre les marchés régionaux, de protéger l''image de ses membres et de vérifier les informations circulant en ligne. Budget limité.</p>\n<h3>Consignes</h3>\n<ol><li>Listez les missions et, pour chacune, l''outil logiciel ou matériel adapté (privilégier libre ou gratuit lorsque c''est suffisant).</li><li>Rédigez pour chaque outil une ligne de cadrage : finalité, données traitées, durée de conservation.</li><li>Définissez la configuration du poste de travail (comptes séparés, chiffrement, sauvegardes).</li><li>Proposez un plan de formation de cinq jours.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Adéquation outils / missions</td><td>6</td></tr><tr><td>Lignes de cadrage</td><td>5</td></tr><tr><td>Sécurité du poste</td><td>4</td></tr><tr><td>Plan de formation</td><td>5</td></tr></tbody></table>',NULL,NULL,50,1,1),
(145,52,'Étude de cas : l''outil gratuit trop bavard','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Un analyste utilise un service en ligne gratuit pour « enrichir » automatiquement une liste de 2 000 adresses e-mail de clients de son entreprise. Il découvre ensuite que les conditions d''utilisation autorisent le service à conserver et réutiliser les données soumises.</p>\n<ol><li>Quelles obligations de protection des données ont été méconnues ?</li><li>Que faut-il vérifier avant d''utiliser un service en ligne (conditions, localisation, conservation) ?</li><li>Quelles actions correctives engager ?</li></ol>',NULL,NULL,20,1,2),
(146,52,'Fiche méthode : évaluer un outil avant adoption','text','<table><thead><tr><th>Critère</th><th>Questions</th></tr></thead><tbody>\n<tr><td>Finalité</td><td>Répond-il à une mission définie ?</td></tr>\n<tr><td>Légalité</td><td>Son usage est-il licite dans les pays concernés ?</td></tr>\n<tr><td>Données</td><td>Quelles données transmet-il, à qui, où sont-elles stockées ?</td></tr>\n<tr><td>Licence</td><td>Usage commercial autorisé ? Coût réel ?</td></tr>\n<tr><td>Fiabilité</td><td>Maintenu ? Documentation ? Communauté ?</td></tr>\n<tr><td>Sécurité</td><td>Mises à jour, authentification, journalisation ?</td></tr>\n</tbody></table>\n<div class="keypoints"><strong>Points clés</strong><ul><li>« Gratuit » peut signifier que vos données sont le prix.</li><li>Lire les conditions d''utilisation avant tout envoi de données.</li></ul></div>',NULL,NULL,10,1,3),
(147,53,'Fiche de synthèse (PDF)','document','<p>Tableau des outils, usages légitimes et modèle de note de cadrage.</p>',NULL,18,10,1,1),
(148,53,'Exercice : rédiger une note de cadrage','exercise','<p><strong>Mandat fictif :</strong> une banque régionale vous charge par écrit d''évaluer l''exposition publique de ses propres services en ligne.</p>\n<ol><li>Rédigez la note de cadrage en six rubriques.</li><li>Sélectionnez trois outils et justifiez chaque choix.</li><li>Listez explicitement ce qui est hors périmètre (employés à titre privé, fournisseurs non mandants...).</li><li>Prévoyez la restitution et la destruction des données.</li></ol>',NULL,NULL,40,1,2),
(149,53,'Étude de cas : la dérive d''un outil','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Un analyste mandaté pour auditer l''exposition d''une entreprise utilise ensuite les mêmes outils pour réunir des informations sur la vie privée d''un dirigeant concurrent, « par curiosité ». L''affaire est révélée.</p>\n<ol><li>Quelles limites du mandat ont été franchies ?</li><li>Quelles infractions sont potentiellement constituées ?</li><li>Quelles conséquences pour l''analyste, son cabinet et le client ?</li><li>Quels contrôles internes auraient prévenu la dérive ?</li></ol>',NULL,NULL,30,1,3),
(150,53,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Analyse mémoire</dt><dd>Examen du contenu de la mémoire vive d&#039;un système.</dd><dt>Capture réseau</dt><dd>Enregistrement du trafic d&#039;un réseau dont on est responsable.</dd><dt>Copie bit à bit</dt><dd>Duplication exacte d&#039;un support, vérifiée par empreinte.</dd><dt>Forensique</dt><dd>Investigation numérique visant à établir des faits.</dd><dt>Graphe de liens</dt><dd>Représentation des relations entre entités.</dd><dt>Laboratoire isolé</dt><dd>Environnement d&#039;entraînement sans connexion aux réseaux réels.</dd><dt>Note de cadrage</dt><dd>Document fixant finalité, mandat, périmètre, base légale, proportionnalité et conservation.</dd><dt>Proportionnalité</dt><dd>Choix du moyen le moins intrusif suffisant.</dd></dl>',NULL,NULL,10,1,4);
INSERT INTO `lessons` (`id`,`chapter_id`,`title`,`type`,`content`,`video_url`,`media_id`,`duration_minutes`,`is_downloadable`,`sort_order`) VALUES
(151,53,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Carrier, Brian, <em>File System Forensic Analysis</em>, Addison-Wesley, 2005.<small>Fondements de l&#039;investigation de supports (auteur de The Sleuth Kit / Autopsy).</small></li><li>Ligh, Michael H., Case, Andrew, Levy, Jamie et Walters, Aaron, <em>The Art of Memory Forensics</em>, Wiley, 2014.<small>Référence de l&#039;analyse mémoire (Volatility).</small></li><li>Documentation officielle de Wireshark (Wireshark User''s Guide, en ligne).<small>Prise en main de l&#039;analyse de protocoles.</small></li><li>Citizen Lab, Université de Toronto : rapports publics sur la surveillance numérique.<small>Études de cas sur les abus de logiciels espions.</small></li><li>Nations unies, Conseil des droits de l''homme, <em>Compilation de bonnes pratiques relatives aux cadres juridiques et institutionnels des services de renseignement</em>, A/HRC/14/46, 2010.<small>Référence internationale sur le contrôle démocratique des services.</small></li><li>Union africaine, <em>Convention sur la cybersécurité et la protection des données à caractère personnel</em> (Convention de Malabo), 2014, en vigueur depuis 2023.<small>Cadre continental de la protection des données.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(152,54,'Briefing vidéo : l''information comme avantage','video','<p>Les trois piliers de l''intelligence économique.</p>',NULL,19,4,1,1),
(153,54,'Les trois piliers','text','<p>L''intelligence économique (IE) est la maîtrise et la protection de l''information stratégique utile aux acteurs économiques. Elle se pratique <strong>exclusivement par des moyens légaux</strong> : c''est ce qui la distingue de l''espionnage industriel.</p>\n<h3>1. La veille</h3><p>Surveiller l''environnement : concurrents, technologies, réglementations, marchés, signaux faibles.</p>\n<h3>2. La protection</h3><p>Sécuriser le patrimoine informationnel : savoir-faire, données, brevets, réputation.</p>\n<h3>3. L''influence</h3><p>Agir légitimement sur son environnement : participation aux normes, plaidoyer transparent, communication, réseaux professionnels.</p>\n<h3>Enjeux africains</h3>\n<ul><li>La ZLECAf ouvre un marché de plus de 1,3 milliard de personnes : connaître les règles d''origine et les acteurs devient crucial ;</li><li>Les ressources minières et agricoles attirent une compétition internationale intense ;</li><li>Le paiement mobile et la fintech africaine sont devenus des secteurs d''innovation mondiale à protéger.</li></ul>',NULL,NULL,25,1,2),
(154,54,'Approfondissement : modèles nationaux d''intelligence économique','text','<p>Plusieurs pays ont structuré une politique publique d''intelligence économique. On cite souvent :</p>\n<ul><li>le <strong>Japon</strong>, avec une coordination historique entre l''État et les grandes entreprises pour la veille technologique ;</li><li>la <strong>France</strong>, dont le rapport Martre (1994) a popularisé le concept et qui dispose d''un service dédié à la sécurité économique ;</li><li>les <strong>États-Unis</strong>, avec un dispositif de contrôle des investissements étrangers dans les secteurs sensibles.</li></ul>\n<h3>Et en Afrique ?</h3>\n<p>Plusieurs pays (notamment le Maroc, le Sénégal ou la Côte d''Ivoire) ont lancé des formations, des cellules ou des réflexions nationales en intelligence économique. Les enjeux prioritaires sont la valorisation des ressources, la protection des entreprises nationales et l''accompagnement à l''export dans la ZLECAf.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>L''IE est aussi une politique publique.</li><li>Chaque modèle reflète une culture économique.</li><li>L''Afrique construit ses propres dispositifs.</li></ul></div>',NULL,NULL,15,1,3),
(155,55,'Monter un dispositif de veille','text','<h3>Les axes de veille</h3>\n<table><thead><tr><th>Type</th><th>Objet</th><th>Sources ouvertes</th></tr></thead><tbody>\n<tr><td>Concurrentielle</td><td>Produits, prix, stratégies</td><td>Rapports annuels, salons, presse économique</td></tr>\n<tr><td>Technologique</td><td>Innovations, brevets</td><td>Bases de brevets, publications scientifiques</td></tr>\n<tr><td>Réglementaire</td><td>Lois, normes, fiscalité</td><td>Journaux officiels, communautés économiques régionales</td></tr>\n<tr><td>Sociétale</td><td>Opinion, attentes</td><td>Réseaux sociaux publics, études</td></tr>\n</tbody></table>\n<h3>Le processus</h3>\n<ol><li>Définir les <strong>facteurs critiques de succès</strong> et les questions clés ;</li><li>Sélectionner et qualifier les sources ;</li><li>Mettre en place des alertes et une revue régulière ;</li><li>Analyser et diffuser un bulletin court ;</li><li>Mesurer l''utilité auprès des destinataires.</li></ol>\n<div class="callout">Les <strong>signaux faibles</strong> (informations fragmentaires annonçant un changement) sont la vraie valeur ajoutée de la veille. Ils ne prennent sens que s''ils sont rapprochés et discutés.</div>',NULL,NULL,25,1,1),
(156,55,'Approfondissement : outils et sources de veille gratuits','text','<p>Une veille efficace peut être construite avec des moyens modestes.</p>\n<table><thead><tr><th>Besoin</th><th>Ressources ouvertes</th></tr></thead><tbody>\n<tr><td>Commerce et prix</td><td>Statistiques douanières nationales, bases de l''OMC et de la CNUCED, Trade Map (ITC)</td></tr>\n<tr><td>Brevets</td><td>Bases de l''OMPI (Patentscope), offices OAPI et ARIPO</td></tr>\n<tr><td>Réglementation</td><td>Journaux officiels, sites de la CEDEAO, de l''UEMOA, de la CEMAC, du secrétariat de la ZLECAf</td></tr>\n<tr><td>Économie</td><td>Rapports de la Banque africaine de développement, du FMI, de la Banque mondiale</td></tr>\n<tr><td>Actualité sectorielle</td><td>Alertes de moteurs de recherche, flux RSS, newsletters professionnelles</td></tr>\n</tbody></table>\n<h3>Organiser le flux</h3>\n<p>Un agrégateur RSS, un tableur de qualification des sources et un rendez-vous hebdomadaire de 30 minutes suffisent pour démarrer.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les sources institutionnelles sont gratuites et fiables.</li><li>La régularité compte plus que la quantité.</li><li>Qualifier chaque source avant de l''ajouter.</li></ul></div>',NULL,NULL,15,1,2),
(157,56,'Protéger la valeur','text','<ul><li><strong>Propriété intellectuelle</strong> : brevets, marques, dessins : en Afrique, via l''OAPI (espace francophone) et l''ARIPO (espace anglophone) en complément des offices nationaux ;</li><li><strong>Secret des affaires</strong> : protection des informations confidentielles par des mesures raisonnables (contrats, accès restreints) ;</li><li><strong>Contrats</strong> : clauses de confidentialité et de non-concurrence dans les partenariats ;</li><li><strong>Réputation</strong> : surveillance des atteintes, plan de réponse aux campagnes de dénigrement.</li></ul>\n<h3>Situations à risque</h3>\n<p>Joint-ventures, transferts de technologie, levées de fonds, délégations étrangères, recrutement de profils issus de la concurrence, stagiaires et visites de site.</p>\n<div class="note">Protéger n''est pas se fermer : il s''agit de partager <em>ce qu''il faut, avec qui il faut, au bon moment</em>.</div>',NULL,NULL,25,1,1),
(158,56,'Approfondissement : protéger ses marques et son image','text','<p>La <strong>réputation</strong> est un actif économique. Elle se protège juridiquement et se surveille.</p>\n<h3>Protection juridique</h3>\n<ul><li>Enregistrer ses marques auprès de l''OAPI (un dépôt couvre les 17 États membres) ou de l''ARIPO et des offices nationaux concernés ;</li><li>Enregistrer les noms de domaine correspondants ;</li><li>Réserver ses noms sur les principaux réseaux sociaux.</li></ul>\n<h3>Gestion des atteintes</h3>\n<ol><li>Détecter (veille d''image) ;</li><li>Qualifier : critique légitime, erreur, ou campagne coordonnée ?</li><li>Répondre de façon proportionnée : correction factuelle, droit de réponse, action juridique en cas de diffamation ou de contrefaçon.</li></ol>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un dépôt OAPI couvre tous les États membres.</li><li>Toute critique n''est pas une attaque.</li><li>La réponse doit être proportionnée et factuelle.</li></ul></div>',NULL,NULL,15,1,2),
(159,57,'La note stratégique','text','<p>La note stratégique éclaire une décision de long terme. Elle tient en deux à quatre pages.</p>\n<ol><li><strong>Question posée</strong> et contexte en trois lignes ;</li><li><strong>Messages clés</strong> (3 à 5 puces) ;</li><li><strong>Analyse</strong> : facteurs, acteurs, tendances ;</li><li><strong>Scénarios</strong> : tendanciel, favorable, défavorable ;</li><li><strong>Options</strong> avec avantages, risques, coûts ;</li><li><strong>Recommandation</strong> argumentée ;</li><li><strong>Indicateurs de suivi</strong>.</li></ol>\n<p>Outils utiles : analyse PESTEL, SWOT, cartographie des parties prenantes, matrice des scénarios.</p>',NULL,NULL,25,1,1),
(160,57,'Approfondissement : la méthode des scénarios','text','<p>La prospective par scénarios, popularisée notamment par les travaux de la Shell dans les années 1970, aide les décideurs à se préparer à plusieurs futurs plutôt qu''à parier sur un seul.</p>\n<h3>Méthode des deux axes</h3>\n<ol><li>Identifier les facteurs qui influencent la question ;</li><li>Retenir les deux incertitudes <strong>les plus importantes et les plus incertaines</strong> ;</li><li>Les croiser pour obtenir quatre scénarios contrastés ;</li><li>Nommer et décrire chaque scénario ; identifier ses indicateurs ;</li><li>Tester les options stratégiques dans chacun.</li></ol>\n<div class="note"><strong>Exemple fictif.</strong> Axes : « intégration régionale rapide / lente » et « prix des matières premières hauts / bas ». Quatre scénarios en découlent, chacun avec ses implications pour une PME exportatrice.</div>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Un scénario n''est pas une prévision.</li><li>Choisir des incertitudes réellement indépendantes.</li><li>Les options robustes fonctionnent dans plusieurs scénarios.</li></ul></div>',NULL,NULL,15,1,2),
(161,58,'Simulation guidée : dossier d''aide à la décision','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>La PME fictive « Soleil Mango » produit des jus de fruits et hésite entre deux marchés d''export : le pays côtier de Kanaga et le pays enclavé de Tarenda. Le conseil d''administration décide dans un mois.</p>\n<h3>Consignes</h3>\n<ol><li>Définissez les facteurs critiques de succès et trois questions de veille.</li><li>Réalisez une analyse PESTEL comparative des deux marchés (données fictives à inventer de façon cohérente et signalées comme telles).</li><li>Identifiez les actifs à protéger (recettes, marque, fichiers clients) et les mesures associées (dépôt de marque régional, accords de confidentialité).</li><li>Construisez quatre scénarios avec deux incertitudes clés.</li><li>Rédigez la note stratégique de deux pages avec recommandation.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Facteurs critiques et questions de veille</td><td>3</td></tr><tr><td>PESTEL comparatif</td><td>5</td></tr><tr><td>Plan de protection</td><td>4</td></tr><tr><td>Scénarios cohérents</td><td>4</td></tr><tr><td>Note stratégique argumentée</td><td>4</td></tr></tbody></table>',NULL,NULL,60,1,1),
(162,58,'Étude de cas : la marque déposée par un autre','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Au moment d''exporter vers un pays voisin, une entreprise découvre qu''un distributeur local a déposé sa marque à son propre nom deux ans plus tôt. Il propose de la « rétrocéder » contre une forte somme.</p>\n<ol><li>Quelle erreur de veille et de protection a été commise ?</li><li>Quelles voies de recours explorer (opposition, action en nullité pour dépôt de mauvaise foi, selon le droit applicable) ?</li><li>Quel dispositif de surveillance des dépôts de marques mettre en place ?</li></ol>',NULL,NULL,25,1,2),
(163,58,'Fiche méthode : tableau de bord de veille','text','<table><thead><tr><th>Axe</th><th>Question clé</th><th>Sources</th><th>Fréquence</th><th>Responsable</th><th>Dernier signal</th></tr></thead><tbody>\n<tr><td>Concurrence</td><td>...</td><td>...</td><td>Hebdo</td><td>...</td><td>...</td></tr>\n<tr><td>Réglementation</td><td>...</td><td>...</td><td>Mensuel</td><td>...</td><td>...</td></tr>\n<tr><td>Marques et brevets</td><td>Nouveaux dépôts proches de nos marques ?</td><td>Bulletins officiels de propriété intellectuelle</td><td>Mensuel</td><td>...</td><td>...</td></tr>\n</tbody></table>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Chaque axe a un responsable.</li><li>Surveiller les dépôts de marques avant d''entrer sur un marché.</li></ul></div>',NULL,NULL,10,1,3),
(164,59,'Fiche de synthèse (PDF)','document','<p>Modèles de bulletin de veille et de note stratégique.</p>',NULL,20,10,1,1),
(165,59,'Exercice : bulletin de veille','exercise','<p>Pour une PME fictive de transformation de cajou souhaitant exporter dans la ZLECAf :</p>\n<ol><li>Définissez trois questions clés de veille.</li><li>Proposez dix sources ouvertes qualifiées.</li><li>Rédigez un bulletin d''une page avec trois informations commentées et un signal faible.</li></ol>',NULL,NULL,45,1,2),
(166,59,'Étude de cas : la négociation de licence','case_study','<p><strong>Scénario pédagogique (fictif).</strong> Une startup de paiement mobile négocie une licence de sa technologie avec un groupe étranger. Lors des réunions, le partenaire demande des détails techniques de plus en plus précis, sans engagement signé.</p>\n<ol><li>Quels risques pour la startup ?</li><li>Quelles protections juridiques mettre en place avant la prochaine réunion ?</li><li>Rédigez les messages clés d''une note stratégique au conseil d''administration.</li></ol>',NULL,NULL,35,1,3),
(167,59,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>Facteur critique de succès</dt><dd>Élément déterminant pour atteindre un objectif.</dd><dt>Intelligence économique</dt><dd>Maîtrise et protection de l&#039;information stratégique par des moyens légaux.</dd><dt>OAPI / ARIPO</dt><dd>Offices régionaux africains de propriété intellectuelle.</dd><dt>PESTEL</dt><dd>Grille d&#039;analyse : politique, économique, social, technologique, environnemental, légal.</dd><dt>Scénario</dt><dd>Description cohérente d&#039;un futur possible, non une prévision.</dd><dt>Secret des affaires</dt><dd>Protection juridique des informations confidentielles à valeur économique.</dd><dt>Signal faible</dt><dd>Information fragmentaire annonçant un changement.</dd><dt>Veille</dt><dd>Surveillance organisée de l&#039;environnement.</dd></dl>',NULL,NULL,10,1,4),
(168,59,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Martre, Henri (dir.), <em>Intelligence économique et stratégie des entreprises</em>, La Documentation française, 1994.<small>Rapport fondateur en langue française.</small></li><li>Porter, Michael E., <em>Competitive Strategy</em>, Free Press, 1980.<small>Analyse concurrentielle et forces du marché.</small></li><li>Godet, Michel, <em>Manuel de prospective stratégique</em>, Dunod (éditions successives).<small>Méthodes de prospective et de scénarios.</small></li><li>Schwartz, Peter, <em>The Art of the Long View</em>, Doubleday, 1991.<small>La méthode des scénarios inspirée de l&#039;expérience Shell.</small></li><li>Secrétariat de la ZLECAf : textes de l''Accord et documentation officielle (en ligne).<small>Règles du marché continental.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5),
(169,60,'Briefing vidéo : un continent pluriel','video','<p>Les grandes clés de lecture géopolitique du continent.</p>',NULL,21,4,1,1),
(170,60,'Grilles de lecture du continent','text','<h3>Les acteurs</h3>\n<ul><li><strong>Union africaine</strong> : Conseil de paix et de sécurité, Agenda 2063 ;</li><li><strong>Communautés économiques régionales</strong> : CEDEAO, CEEAC, SADC, EAC, IGAD, UMA, COMESA... ;</li><li><strong>États</strong> et leurs intérêts propres ;</li><li><strong>Acteurs non étatiques</strong> : entreprises, diasporas, organisations religieuses, groupes armés ;</li><li><strong>Puissances extérieures</strong> et nouveaux partenaires.</li></ul>\n<h3>Les espaces stratégiques</h3>\n<table><thead><tr><th>Espace</th><th>Enjeux</th></tr></thead><tbody>\n<tr><td>Sahel</td><td>Sécurité, gouvernance, climat, migrations</td></tr>\n<tr><td>Golfe de Guinée</td><td>Sûreté maritime, hydrocarbures, ports</td></tr>\n<tr><td>Corne de l''Afrique</td><td>Mer Rouge, routes commerciales, eau du Nil</td></tr>\n<tr><td>Grands Lacs</td><td>Ressources minières, frontières, déplacés</td></tr>\n<tr><td>Afrique australe</td><td>Intégration industrielle, énergie, minerais critiques</td></tr>\n</tbody></table>\n<h3>Les dynamiques transversales</h3>\n<p>Démographie (population très jeune), urbanisation rapide, transition énergétique et minerais critiques, numérisation, effets du changement climatique, recompositions des alliances internationales.</p>\n<div class="callout">Méthode : toujours croiser l''échelle locale, nationale, régionale et internationale. Une crise locale a souvent des racines et des effets à d''autres échelles.</div>',NULL,NULL,30,1,2),
(171,60,'Approfondissement : l''architecture africaine de paix et de sécurité','text','<p>L''<strong>Architecture africaine de paix et de sécurité (APSA)</strong>, mise en place par l''Union africaine à partir du Protocole de 2002 relatif au Conseil de paix et de sécurité, repose sur plusieurs piliers :</p>\n<ul><li>le <strong>Conseil de paix et de sécurité</strong> (CPS), organe décisionnel ;</li><li>le <strong>Groupe des sages</strong>, chargé de la diplomatie préventive ;</li><li>le <strong>Système continental d''alerte rapide</strong> (CEWS) ;</li><li>la <strong>Force africaine en attente</strong> ;</li><li>le <strong>Fonds pour la paix</strong>.</li></ul>\n<p>Les communautés économiques régionales et les mécanismes régionaux sont associés au dispositif selon un principe de <strong>subsidiarité</strong>.</p>\n<h3>Agenda 2063</h3>\n<p>Adopté en 2015, l''Agenda 2063 fixe la vision de long terme de l''Union africaine, dont l''initiative « Faire taire les armes ».</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Le CPS est l''organe décisionnel de l''APSA.</li><li>L''alerte précoce est un pilier institutionnel.</li><li>Le niveau régional joue un rôle central.</li></ul></div>',NULL,NULL,20,1,3),
(172,61,'Grille d''analyse des conflits','text','<p>Un conflit s''analyse selon trois dimensions complémentaires.</p>\n<h3>1. Profil</h3><p>Contexte historique, géographique, politique, économique et social.</p>\n<h3>2. Causes</h3>\n<ul><li><strong>Structurelles</strong> : inégalités, accès à la terre et à l''eau, gouvernance ;</li><li><strong>Accélératrices</strong> : crise économique, élection contestée, choc climatique ;</li><li><strong>Déclencheurs</strong> : incident, assassinat, décision politique.</li></ul>\n<h3>3. Acteurs</h3>\n<p>Pour chaque acteur : intérêts, positions, capacités, alliances, et ceux qui ont intérêt à la paix (les « connecteurs ») autant que ceux qui ont intérêt au conflit.</p>\n<h3>Dynamiques et scénarios</h3>\n<p>On identifie les tendances, les fenêtres d''opportunité pour la paix et les indicateurs d''alerte précoce. Les mécanismes africains d''alerte précoce (comme le système continental de l''UA ou ECOWARN de la CEDEAO) reposent sur ce type d''indicateurs.</p>\n<div class="warning">L''analyse de conflit exige une grande prudence : éviter les lectures ethnicisantes simplistes, donner la parole aux sources locales et respecter la dignité des victimes.</div>',NULL,NULL,30,1,1),
(173,61,'Approfondissement : données ouvertes sur les conflits','text','<p>L''analyse quantitative des conflits s''appuie sur des bases de données publiques et documentées :</p>\n<ul><li><strong>ACLED</strong> (Armed Conflict Location & Event Data) : événements de violence politique et de manifestations, géolocalisés et datés ;</li><li><strong>UCDP</strong> (Uppsala Conflict Data Program) : conflits armés et victimes, avec une longue série historique ;</li><li>Rapports d''organisations humanitaires et de l''ONU (OCHA, HCR) sur les déplacements de populations.</li></ul>\n<h3>Précautions d''usage</h3>\n<ul><li>Lire la méthodologie : définitions, sources, délais de mise à jour ;</li><li>Ne pas confondre augmentation des événements et augmentation de la couverture médiatique ;</li><li>Croiser avec des sources qualitatives locales.</li></ul>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Les bases ouvertes permettent d''objectiver les tendances.</li><li>Chaque base a ses définitions : ne pas mélanger sans précaution.</li><li>Les chiffres doivent être contextualisés.</li></ul></div>',NULL,NULL,15,1,2),
(174,62,'Évaluer le risque pays','text','<p>Le risque pays mesure la probabilité que des événements liés à un pays affectent négativement un projet ou une organisation.</p>\n<table><thead><tr><th>Dimension</th><th>Exemples d''indicateurs</th></tr></thead><tbody>\n<tr><td>Politique</td><td>Stabilité institutionnelle, calendrier électoral, relations régionales</td></tr>\n<tr><td>Sécuritaire</td><td>Incidents, zones à risque, criminalité</td></tr>\n<tr><td>Économique</td><td>Croissance, inflation, dette, change</td></tr>\n<tr><td>Juridique</td><td>Sécurité des contrats, fiscalité, efficacité judiciaire</td></tr>\n<tr><td>Opérationnel</td><td>Infrastructures, logistique, énergie</td></tr>\n<tr><td>Environnemental et social</td><td>Climat, acceptation locale, droits humains</td></tr>\n</tbody></table>\n<h3>Méthode</h3>\n<ol><li>Définir le projet (le risque dépend toujours de l''exposition) ;</li><li>Noter chaque dimension avec des critères explicites ;</li><li>Pondérer selon le projet ;</li><li>Analyser les tendances, pas seulement l''instantané ;</li><li>Proposer des mesures d''atténuation.</li></ol>\n<div class="note">Un score ne remplace pas l''analyse. Les notations globales doivent être lues avec leurs hypothèses ; un même pays peut présenter des risques très différents selon les régions et les secteurs.</div>',NULL,NULL,30,1,1),
(175,62,'Approfondissement : risque pays et développement durable','text','<p>Les investisseurs intègrent de plus en plus les critères <strong>ESG</strong> (environnementaux, sociaux et de gouvernance) dans l''évaluation du risque pays et projet.</p>\n<h3>Référentiels utiles</h3>\n<ul><li>Les <strong>Normes de performance de la SFI</strong> (Société financière internationale, groupe Banque mondiale) sur la durabilité environnementale et sociale ;</li><li>Les <strong>Principes directeurs des Nations unies</strong> relatifs aux entreprises et aux droits de l''homme (2011) ;</li><li>Les engagements de transparence sur les industries extractives (Initiative pour la transparence dans les industries extractives, ITIE), à laquelle adhèrent de nombreux pays africains.</li></ul>\n<h3>Pourquoi c''est un enjeu de risque</h3>\n<p>Un projet mal accepté localement (conflit foncier, atteinte environnementale) s''expose à des blocages, des recours et une perte de réputation : le risque social est un risque opérationnel.</p>\n<div class="keypoints"><strong>Points clés</strong><ul><li>L''acceptation locale conditionne la viabilité d''un projet.</li><li>Des référentiels internationaux existent et sont exigés par les financeurs.</li><li>ESG et risque pays se recoupent largement.</li></ul></div>',NULL,NULL,15,1,2),
(176,63,'Simulation guidée : avis de risque pour un projet solaire','exercise','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Un fonds d''investissement fictif étudie une centrale solaire dans une région frontalière de Tarenda (pays imaginaire). Éléments fictifs : élections dans un an, tensions foncières anciennes, forte demande en électricité, financement d''une banque régionale de développement, présence de communautés pastorales sur une partie du site.</p>\n<h3>Consignes</h3>\n<ol><li>Réalisez le profil de la région et la cartographie des acteurs (y compris les connecteurs).</li><li>Notez les six dimensions du risque pays/projet et pondérez-les.</li><li>Identifiez les exigences ESG applicables (consultation des communautés, accès à l''eau, couloirs de transhumance).</li><li>Construisez trois scénarios à trois ans avec indicateurs.</li><li>Rédigez un avis : investir / investir sous conditions / ne pas investir, avec conditions précises.</li></ol><h3>Barème indicatif (auto-évaluation sur 20)</h3><table><thead><tr><th>Critère</th><th>Points</th></tr></thead><tbody><tr><td>Analyse d''acteurs nuancée</td><td>4</td></tr><tr><td>Notation argumentée</td><td>4</td></tr><tr><td>Exigences ESG identifiées</td><td>4</td></tr><tr><td>Scénarios et indicateurs</td><td>4</td></tr><tr><td>Avis clair et conditionné</td><td>4</td></tr></tbody></table>',NULL,NULL,75,1,1),
(177,63,'Étude de cas : la carte qui fâchait','case_study','<div class="note"><strong>Scénario entièrement fictif.</strong> Pays, organisations, personnes et données sont imaginaires et ne décrivent aucune situation réelle.</div><p>Un rapport de risque diffusé à des investisseurs colorie en rouge une province entière « à éviter », sur la base d''incidents concentrés dans deux districts. Les autorités locales et les entreprises de la province protestent : les investissements s''effondrent, y compris dans les zones calmes.</p>\n<ol><li>Quelles erreurs méthodologiques (échelle, données, vocabulaire) ?</li><li>Comment représenter le risque de façon plus fine et plus juste ?</li><li>Quelle responsabilité l''analyste porte-t-il dans les effets de ses publications ?</li></ol>',NULL,NULL,20,1,2),
(178,63,'Fiche méthode : grille de notation du risque pays','text','<table><thead><tr><th>Dimension</th><th>Note (1 à 5)</th><th>Tendance (hausse, stable, baisse)</th><th>Poids projet</th><th>Justification et sources</th></tr></thead><tbody>\n<tr><td>Politique</td><td></td><td></td><td></td><td></td></tr><tr><td>Sécuritaire</td><td></td><td></td><td></td><td></td></tr>\n<tr><td>Économique</td><td></td><td></td><td></td><td></td></tr><tr><td>Juridique</td><td></td><td></td><td></td><td></td></tr>\n<tr><td>Opérationnelle</td><td></td><td></td><td></td><td></td></tr><tr><td>Environnementale et sociale</td><td></td><td></td><td></td><td></td></tr>\n</tbody></table>\n<div class="keypoints"><strong>Points clés</strong><ul><li>Toujours préciser l''échelle géographique.</li><li>La tendance compte autant que la note.</li><li>Une note sans justification n''a pas de valeur.</li></ul></div>',NULL,NULL,10,1,3),
(179,64,'Fiche de synthèse (PDF)','document','<p>Grille d''analyse de conflit et matrice de risque pays.</p>',NULL,22,10,1,1),
(180,64,'Exercice : matrice de risque pays','exercise','<p><strong>Projet fictif :</strong> implantation d''une unité de transformation agricole dans la « République de Kanaga » (pays imaginaire côtier d''Afrique de l''Ouest, 18 millions d''habitants, élections dans 14 mois, inflation à 9 %, port moderne, tensions foncières dans le nord).</p>\n<ol><li>Notez chacune des six dimensions de 1 à 5 avec justification.</li><li>Pondérez selon le projet.</li><li>Rédigez trois scénarios à deux ans.</li><li>Proposez cinq mesures d''atténuation.</li></ol>',NULL,NULL,50,1,2),
(181,64,'Étude de cas : crise dans la région des « Trois Rivières »','case_study','<p><strong>Scénario pédagogique entièrement fictif.</strong> Dans une région frontalière imaginaire, une sécheresse prolongée aggrave les tensions entre agriculteurs et éleveurs. Un incident sur un point d''eau dégénère. Des rumeurs circulent en ligne.</p>\n<ol><li>Réalisez le profil, l''analyse des causes et la cartographie des acteurs.</li><li>Identifiez trois connecteurs pour la paix.</li><li>Proposez cinq indicateurs d''alerte précoce.</li><li>Quelles précautions de vocabulaire et de sources adopter ?</li></ol>',NULL,NULL,40,1,3),
(182,64,'Glossaire de la formation','text','<p>Les notions essentielles de la formation, à maîtriser pour l''examen final.</p><dl class="glossary"><dt>APSA</dt><dd>Architecture africaine de paix et de sécurité.</dd><dt>Alerte précoce</dt><dd>Identification anticipée des risques de crise.</dd><dt>CPS</dt><dd>Conseil de paix et de sécurité de l&#039;Union africaine.</dd><dt>Connecteur</dt><dd>Acteur ou facteur favorisant la paix.</dd><dt>ESG</dt><dd>Critères environnementaux, sociaux et de gouvernance.</dd><dt>ITIE</dt><dd>Initiative pour la transparence dans les industries extractives.</dd><dt>Risque pays</dt><dd>Probabilité qu&#039;un contexte national affecte un projet.</dd><dt>Subsidiarité</dt><dd>Traitement d&#039;un problème au niveau le plus proche pertinent.</dd></dl>',NULL,NULL,10,1,4),
(183,64,'Pour aller plus loin : bibliographie et ressources','text','<p>Sélection d''ouvrages, de normes et de ressources reconnues pour prolonger la formation. Les ressources en accès libre sont signalées.</p><ul class="biblio"><li>Union africaine, <em>Protocole relatif à la création du Conseil de paix et de sécurité</em>, 2002.<small>Fondement juridique de l&#039;APSA.</small></li><li>Union africaine, <em>Agenda 2063 : l''Afrique que nous voulons</em>, 2015.<small>Vision stratégique continentale.</small></li><li>ACLED et UCDP : bases de données ouvertes sur les conflits (en ligne).<small>Données quantitatives documentées.</small></li><li>Institute for Security Studies (ISS Africa) et International Crisis Group, rapports publics.<small>Analyses régionales de référence.</small></li><li>Nations unies, <em>Principes directeurs relatifs aux entreprises et aux droits de l''homme</em>, 2011.<small>Cadre de responsabilité des entreprises.</small></li></ul><div class="note">Ces références sont indiquées à titre pédagogique ; AFRICA''SPY n''a aucun lien d''affiliation avec leurs auteurs ou éditeurs.</div>',NULL,NULL,10,1,5);
