INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(1,1,1,'Quelle est la caractéristique principale qui distingue le renseignement de la simple information ?','Le renseignement se définit par sa finalité (aider une décision) et par le travail d''évaluation, non par le secret de ses sources.',1),
(2,1,1,'Dans le cycle du renseignement, quelle phase consiste à traduire le besoin du décideur en questions précises ?','L''orientation transforme une préoccupation générale en besoins en renseignement exploitables.',1),
(3,1,1,'Un renseignement exact livré après la décision qu''il devait éclairer :','Le délai fait partie de la qualité : un produit tardif ne remplit plus sa fonction.',1),
(4,1,1,'Quel niveau correspond à « l''évolution des délais de passage aux frontières » ?','C''est un fait observable à collecter pour répondre au besoin.',1),
(5,1,1,'Quel produit signale un changement imminent appelant une décision ?','L''alerte est courte, urgente et orientée décision.',1),
(6,1,2,'Que désignait l''expression « cabinet noir » dans les monarchies européennes ?','Les cabinets noirs interceptaient et déchiffraient la correspondance diplomatique.',1),
(7,1,2,'Quel rôle jouaient les caravanes transsahariennes dans les empires sahéliens ?','Commerce et information circulaient ensemble sur les routes caravanières.',1),
(8,1,2,'Quelle tendance caractérise l''évolution des services depuis les années 1990 ?','Lois, organes de contrôle et coopérations régionales se sont développés.',1),
(9,1,2,'Quel pays africain dispose d''un inspecteur général du renseignement prévu par ses textes ?','L''Afrique du Sud a institué un Inspector-General of Intelligence.',1),
(10,1,2,'Selon les bonnes pratiques internationales, qu''est-ce qui doit rester public ?','Le secret porte sur les opérations, pas sur les règles qui encadrent les services.',1),
(11,1,3,'Que signifie l''acronyme OSINT ?','OSINT : renseignement d''origine sources ouvertes.',1),
(12,1,3,'Deux articles de presse reprenant la même dépêche d''agence constituent :','Il faut remonter à l''origine : une même dépêche reprise reste une seule source.',1),
(13,1,3,'Quelle limite principale présente le GEOINT ?','L''imagerie montre des faits physiques, pas des intentions.',1),
(14,1,3,'Que prescrit le principe de parcimonie dans un plan de collecte ?','On escalade seulement si une lacune importante subsiste.',1),
(15,1,3,'Pourquoi l''imagerie radar est-elle utile pour suivre des inondations ?','Le radar fonctionne de jour comme de nuit et à travers les nuages.',1),
(16,1,4,'Dans la méthode ACH, sur quels indices l''analyste concentre-t-il son attention ?','L''ACH privilégie la réfutation : l''hypothèse retenue est la moins contredite.',1),
(17,1,4,'Supposer qu''un acteur étranger raisonne exactement comme nous relève :','L''effet miroir projette notre propre logique sur autrui.',1),
(18,1,4,'Pourquoi utiliser une échelle de probabilité définie à l''avance ?','Un vocabulaire stable garantit que « probable » signifie la même chose pour tous.',1),
(19,1,4,'Qu''est-ce qu''un indicateur en analyse prospective ?','Il rend le scénario plus ou moins probable sans le prouver.',1),
(20,1,4,'Pourquoi définir aussi des indicateurs du scénario favorable ?','Surveiller tous les scénarios limite les biais.',1),
(21,1,5,'Dans une situation urgente, quel format concilie rigueur et délai ?','Le format en deux temps sert la décision sans sacrifier la rigueur.',1),
(22,1,5,'Le titre d''une note d''analyse doit être :','Le décideur doit comprendre la conclusion dès le titre.',1),
(23,2,7,'Pour une entreprise privée, quelle pratique HUMINT est légitime ?','Seuls les échanges transparents et consentis sont acceptables pour un acteur privé.',1),
(24,2,7,'Quel apport spécifique le HUMINT offre-t-il par rapport aux capteurs techniques ?','Les intentions humaines échappent largement aux capteurs techniques.',1),
(25,2,7,'Le recrutement de sources clandestines relève :','Cette activité est réservée aux autorités habilitées par la loi.',1),
(26,2,7,'Le débriefing de retour de mission doit être :','C''est la base d''une pratique légitime.',1),
(27,2,7,'Que recueille-t-on en priorité lors d''un débriefing ?','On se concentre sur l''observé et le vérifiable.',1),
(28,2,8,'Pourquoi archiver URL, date et capture lors d''une collecte OSINT ?','La traçabilité permet la vérification par un tiers et protège contre la disparition des contenus.',1),
(29,2,8,'Une information publiquement accessible sur une personne :','L''accessibilité ne lève pas les obligations légales de protection des données.',1),
(30,2,8,'Créer un faux profil pour entrer dans un groupe privé est :','L''OSINT éthique se limite aux contenus réellement publics, sans tromperie.',1),
(31,2,8,'À quoi sert une archive web publique en OSINT ?','Elle conserve des copies datées de pages web.',1),
(32,2,8,'Pourquoi chercher qui a publié une information en premier ?','Remonter à l''origine est un réflexe fondamental.',1),
(33,2,9,'Que désigne le COMINT ?','COMINT = Communications Intelligence, sous-ensemble du SIGINT.',1),
(34,2,9,'Dans un État de droit, une mesure d''interception doit notamment être :','Légalité, proportionnalité, autorisation et contrôle sont les piliers du cadre.',1),
(35,2,9,'L''interception de communications par une entreprise privée :','Elle est réservée aux autorités publiques habilitées par la loi.',1),
(36,2,9,'Quel est l''intérêt d''un point d''échange Internet (IXP) national ?','Le trafic local reste local : moins coûteux, plus rapide, plus résilient.',1),
(37,2,9,'L''analyse des dépendances aux câbles sous-marins relève :','Ces enjeux s''étudient avec des informations publiques.',1),
(38,2,10,'Que mesure la résolution spatiale d''une image ?','La résolution spatiale correspond à la taille au sol d''un pixel.',1),
(39,2,10,'Quel critère de photo-interprétation renseigne sur la hauteur d''un objet ?','La longueur de l''ombre permet d''estimer la hauteur, connaissant l''heure et la position du soleil.',1),
(40,2,10,'Pourquoi comparer deux images d''une même zone à des dates différentes ?','L''analyse diachronique révèle les évolutions du terrain.',1),
(41,2,10,'Quelles bandes combine le NDVI ?','NDVI = (PIR - Rouge) / (PIR + Rouge).',1),
(42,2,10,'Un NDVI élevé indique :','Plus la valeur est proche de 1, plus la végétation est vigoureuse.',1),
(43,2,11,'Pour savoir si une activité observée sur imagerie est inhabituelle, on compare de préférence avec :','La comparaison saisonnière évite de confondre routine et anomalie.',1),
(44,2,11,'Pourquoi archiver un contenu avant de l''analyser ?','La preuve doit être conservée.',1),
(45,3,13,'Que signifie le principe du « besoin d''en connaître » ?','La collecte doit être ciblée sur un besoin défini.',1),
(46,3,13,'Dans un cadre privé, le consentement éclairé implique que l''interlocuteur :','Transparence sur l''identité et la finalité : c''est la base de l''éthique.',1),
(47,3,13,'Quelle vigilance s''impose face à un acteur économique local ?','Chaque profil a ses biais : ici, les intérêts commerciaux.',1),
(48,3,13,'Quelle contrepartie est acceptable dans une relation d''information ?','La réciprocité doit être transparente et proportionnée.',1),
(49,3,13,'Que faire lorsque le besoin d''information disparaît ?','La clôture fait partie d''une relation respectueuse.',1),
(50,3,14,'Laquelle de ces pratiques constitue une ligne rouge absolue ?','L''usurpation d''identité ou de qualité est illégale et contraire à l''éthique.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(51,3,14,'Quel texte africain encadre la protection des données personnelles à l''échelle continentale ?','La Convention de l''UA de 2014, dite de Malabo.',1),
(52,3,14,'Selon le test des quatre questions, que faire si une seule réponse est négative ?','Une seule réponse négative suffit à renoncer.',1),
(53,3,14,'Un enregistrement audio d''entretien suppose :','L''enregistrement à l''insu de la personne est contraire à l''éthique et souvent illégal.',1),
(54,3,14,'Face à une personne vulnérable, en cas de doute sur le consentement, il faut :','La protection de la personne prime sur le besoin d''information.',1),
(55,3,15,'Dans la méthode de l''entonnoir, quand pose-t-on les questions fermées ?','On part du général (ouvert) pour aller vers la vérification (fermé).',1),
(56,3,15,'Laquelle de ces questions est suggestive ?','Elle oriente la réponse et contamine l''information.',1),
(57,3,15,'L''observation non intrusive d''un espace public porte sur :','On observe des flux et des usages, jamais des individus.',1),
(58,3,15,'Qui a développé l''entretien cognitif ?','Ronald Fisher et Edward Geiselman, dans les années 1980.',1),
(59,3,15,'Laquelle est une consigne de l''entretien cognitif ?','Raconter à rebours aide à retrouver des détails.',1),
(60,3,16,'Que signifie la cotation « B2 » ?','La lettre cote la source, le chiffre cote l''information.',1),
(61,3,16,'Pourquoi coter séparément la source et l''information ?','Les deux dimensions sont indépendantes.',1),
(62,3,16,'Qu''est-ce qu''un « rapport circulaire » ?','Il donne une fausse impression de confirmation.',1),
(63,3,16,'Qu''est-ce qui distingue la désinformation de la mésinformation ?','La désinformation est intentionnelle.',1),
(64,3,16,'Pourquoi coter séparément les éléments d''un même récit ?','Le mélange vrai/faux est une technique classique.',1),
(65,3,17,'Un interlocuteur propose des données internes de son employeur contre paiement. Que faire ?','L''opération serait illégale et contaminerait l''analyse.',1),
(66,3,17,'Dans un compte rendu d''entretien, les impressions de l''enquêteur doivent être :','La séparation garantit l''honnêteté du document.',1),
(67,4,19,'À quoi sert la pseudonymisation d''une source ?','Le code remplace l''identité ; la correspondance est stockée à part.',1),
(68,4,19,'Pourquoi un rapport sans nom peut-il malgré tout exposer une source ?','Le risque de recoupement impose une relecture attentive.',1),
(69,4,19,'Quelle mesure relève de l''hygiène numérique ?','Le chiffrement protège en cas de perte ou de vol.',1),
(70,4,19,'Quelle instance a adopté la Déclaration de principes sur la liberté d''expression en Afrique ?','La Commission africaine, avec une révision en 2019.',1),
(71,4,19,'Selon ces principes, un journaliste peut être contraint de révéler sa source :','Les exceptions doivent être encadrées et proportionnées.',1),
(72,4,20,'Que montrent les méta-analyses sur la détection du mensonge à partir du comportement ?','Autour de 54 % : guère mieux que le hasard.',1),
(73,4,20,'Existe-t-il un signe non verbal universel du mensonge ?','La recherche n''a identifié aucun indice universel.',1),
(74,4,20,'Quelle approche est jugée plus fiable ?','Le contenu vérifiable et les entretiens non accusatoires donnent de meilleurs résultats.',1),
(75,4,20,'L''effet de halo désigne :','Une impression positive ou négative contamine l''ensemble de l''évaluation.',1),
(76,4,20,'Les personnes se disant expertes en détection du mensonge :','Les études montrent un excès de confiance sans gain de précision.',1),
(77,4,21,'Que signifie BLUF ?','La conclusion est placée en tête du document.',1),
(78,4,21,'Quelle formulation est la plus professionnelle ?','Faits chiffrés + jugement probabiliste + niveau de confiance.',1),
(79,4,21,'Que doit contenir la section « lacunes et indicateurs » ?','Elle prépare le suivi et l''actualisation de l''analyse.',1),
(80,4,21,'Quel support est le plus adapté pour comparer des options ?','Le tableau rend la comparaison immédiate.',1),
(81,4,21,'Que doit permettre un résumé exécutif ?','Le décideur doit pouvoir s''arrêter au résumé.',1),
(82,4,22,'Écarter des candidats parce qu''ils évitent le regard est :','Le contact visuel varie selon les cultures et ne prédit pas l''honnêteté.',1),
(83,4,22,'Comment relire un rapport pour protéger une source ?','Cette relecture révèle les détails identifiants.',1),
(84,5,24,'Pour une organisation privée, le contre-espionnage consiste principalement à :','L''approche est défensive ; les enquêtes relèvent des autorités.',1),
(85,5,24,'Quelle est la cause la plus fréquente des fuites d''informations ?','Conversations, réseaux sociaux, négligences : le facteur humain domine.',1),
(86,5,24,'Un consultant posant des questions insistantes hors de sa mission relève de :','C''est un vecteur humain classique.',1),
(87,5,24,'Qu''est-ce qui caractérise une ingérence économique ?','Le caractère déloyal distingue l''ingérence de la concurrence normale.',1),
(88,5,24,'Quel moment expose particulièrement une entreprise ?','Les échanges d''informations y sont intenses.',1),
(89,5,25,'Quel est le profil de menace interne le plus fréquent ?','L''erreur et la méconnaissance des règles dominent.',1),
(90,5,25,'Le principe du moindre privilège consiste à :','Chacun n''accède qu''à ce dont il a besoin.',1),
(91,5,25,'Quelle mesure réduit durablement le risque interne ?','Le climat organisationnel est un facteur clé.',1),
(92,5,25,'Lequel est un signal pertinent de menace interne ?','Seuls des signaux professionnels et objectifs sont légitimes.',1),
(93,5,25,'Quelle est la première réponse appropriée à un signal ?','La réponse doit rester proportionnée et encadrée.',1),
(94,5,26,'Par quoi commence une démarche de protection de l''information ?','On identifie d''abord ce qui doit être protégé.',1),
(95,5,26,'Pourquoi limiter le nombre de niveaux de classification ?','La simplicité favorise l''adoption.',1),
(96,5,26,'Laquelle est une mesure de protection physique ?','Broyage et politique du bureau propre relèvent de la sécurité physique.',1),
(97,5,26,'Que permet TLP:GREEN ?','GREEN = communauté, pas de publication.',1),
(98,5,26,'Quel marquage a remplacé TLP:WHITE dans la version 2.0 ?','TLP 2.0 (2022) utilise TLP:CLEAR.',1),
(99,5,27,'« Votre compte sera bloqué dans une heure » exploite principalement le levier :','L''urgence empêche la réflexion.',1),
(100,5,27,'Quelle est la meilleure parade face à une demande inhabituelle de virement ?','Le contre-appel par un canal indépendant déjoue la fraude au président.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(101,5,27,'Un salarié qui signale une tentative d''hameçonnage après avoir cliqué doit être :','Blâmer décourage les signalements, pourtant essentiels.',1),
(102,5,27,'Quel indicateur reflète le mieux une bonne culture de sécurité ?','Signaler montre que la menace est reconnue et que le dispositif inspire confiance.',1),
(103,5,27,'Quel format de sensibilisation est le plus efficace ?','La répétition et la proximité favorisent le changement de comportement.',1),
(104,5,28,'Lors d''une visite d''usine, quelle règle est la plus protectrice ?','Le parcours accompagné limite les fuites involontaires.',1),
(105,5,28,'Une formule de produit stockée sans protection sur un poste partagé relève d''une vulnérabilité :','C''est un actif essentiel exposé.',1),
(106,6,30,'Quelle vérification est appropriée lors d''un recrutement ?','Les vérifications doivent rester légales et proportionnées.',1),
(107,6,30,'Que doit inclure la procédure de départ d''un salarié ?','Des comptes actifs après départ sont un risque majeur.',1),
(108,6,30,'Le « duty of care » désigne :','Il impose d''évaluer et de couvrir les risques des missions.',1),
(109,6,30,'Pourquoi utiliser un ordinateur dédié en déplacement ?','Minimiser les données emportées réduit l''impact d''un incident.',1),
(110,6,30,'Que faire des appareils au retour d''une mission sensible ?','Une vérification permet de détecter une éventuelle compromission.',1),
(111,6,31,'Le risque résulte de la combinaison de :','Les trois composantes doivent être évaluées.',1),
(112,6,31,'Les trois critères d''évaluation d''une menace sont :','Intention + capacité + opportunité.',1),
(113,6,31,'Pourquoi actualiser régulièrement une matrice de risques ?','Une analyse figée devient trompeuse.',1),
(114,6,31,'Dans un nœud papillon, où se placent les mesures de prévention ?','Elles empêchent l''événement de survenir.',1),
(115,6,31,'Les sauvegardes testées sont, dans le nœud papillon :','Elles réduisent l''impact après l''événement.',1),
(116,6,32,'Que signifie la « défense en profondeur » ?','Plusieurs couches évitent qu''une seule défaillance soit fatale.',1),
(117,6,32,'Les sauvegardes testées relèvent de quelle fonction ?','Elles permettent le rétablissement après incident.',1),
(118,6,32,'Face à une attaque, une organisation privée doit :','La riposte offensive est illégale ; on signale.',1),
(119,6,32,'Que désigne le RPO ?','Recovery Point Objective.',1),
(120,6,32,'Quelle norme encadre la continuité d''activité ?','ISO 22301 porte sur les systèmes de management de la continuité d''activité.',1),
(121,6,33,'Qu''est-ce qu''un « inject » dans un exercice sur table ?','Les injects font évoluer le scénario.',1),
(122,6,33,'Le scénario d''un exercice doit être :','Le fictif évite toute mise en cause réelle.',1),
(123,6,33,'Qu''est-ce qu''un exercice réussi ?','L''objectif est d''apprendre.',1),
(124,6,33,'Que signifie un RETEX « sans recherche de coupable » ?','Cela favorise des retours honnêtes.',1),
(125,6,33,'Que doit comporter chaque action corrective ?','Sans responsable ni date, l''action reste lettre morte.',1),
(126,6,34,'Que faire d''une clé USB reçue lors d''un séminaire ?','Les supports amovibles inconnus sont un vecteur d''attaque classique.',1),
(127,6,34,'À quoi sert le check-in quotidien en mission ?','Il déclenche la procédure d''urgence si nécessaire.',1),
(128,7,36,'Que signifie l''acronyme APT ?','Désigne des groupes sophistiqués et persistants.',1),
(129,7,36,'Pourquoi étudier la chaîne d''attaque ?','C''est un outil de conception défensive.',1),
(130,7,36,'Quelle étape repose souvent sur les sources ouvertes ?','D''où l''intérêt de réduire son exposition publique.',1),
(131,7,36,'En quelle année la Convention de Malabo est-elle entrée en vigueur ?','Adoptée en 2014, elle est entrée en vigueur en 2023.',1),
(132,7,36,'Quel type de structure coordonne la réponse aux incidents au niveau national ?','Les CERT/CSIRT nationaux coordonnent la réponse aux incidents.',1),
(133,7,37,'Que permet l''opérateur filetype: ?','Ex. filetype:pdf.',1),
(134,7,37,'Qu''appelle-t-on « pivoter » en OSINT ?','Domaine puis certificat puis infrastructure, etc.',1),
(135,7,37,'Quelle règle d''hygiène est essentielle ?','L''enquêteur observe sans interagir.',1),
(136,7,37,'Le Protocole de Berkeley porte sur :','Il fixe des standards de collecte, préservation et vérification.',1),
(137,7,37,'Que doit contenir une entrée de journal d''enquête ?','La traçabilité exige un enregistrement complet.',1),
(138,7,38,'Qu''est-ce que l''empreinte numérique d''une organisation ?','Sites, documents, profils, sous-domaines...',1),
(139,7,38,'Un audit d''exposition sur une organisation tierce nécessite :','Sans autorisation, la démarche est contestable.',1),
(140,7,38,'Pourquoi les offres d''emploi peuvent-elles être sensibles ?','Elles informent un attaquant sur l''environnement technique.',1),
(141,7,38,'À quoi sert le fichier security.txt (RFC 9116) ?','Il facilite la divulgation responsable.',1),
(142,7,38,'Quelle mesure répond à un sous-domaine de test exposé ?','Les environnements de test sont des cibles fréquentes.',1),
(143,7,39,'Que désigne EXIF ?','EXIF stocke les informations de prise de vue.',1),
(144,7,39,'Pourquoi calculer l''empreinte SHA-256 d''un fichier original ?','L''empreinte garantit l''intégrité.',1),
(145,7,39,'Une métadonnée de date isolée constitue :','Elle peut être erronée ou falsifiée.',1),
(146,7,39,'Quelle métadonnée d''une photo est la plus sensible pour la vie privée ?','Elle peut révéler un domicile ou un lieu sensible.',1),
(147,7,39,'Quel outil libre permet d''afficher et supprimer des métadonnées ?','ExifTool gère de nombreux formats.',1),
(148,7,40,'Un rapport d''exposition doit commencer par :','Le cadre et l''essentiel d''abord.',1),
(149,7,40,'Une photo publique d''un bureau peut révéler :','Tableaux, écrans et post-it sont des fuites fréquentes.',1),
(150,8,42,'Les indicateurs de compromission (IoC) relèvent principalement du niveau :','Ils servent directement aux équipes techniques.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(151,8,42,'Quels sont les quatre sommets du modèle en diamant ?','Ils structurent l''analyse d''un événement.',1),
(152,8,42,'Selon la pyramide de la douleur, qu''est-ce qui gêne le plus un attaquant ?','Changer de comportement est coûteux pour l''adversaire.',1),
(153,8,42,'Quel est le rôle de TAXII ?','STIX décrit, TAXII transporte.',1),
(154,8,42,'Qu''est-ce qui rend un indicateur de compromission de qualité ?','Sans contexte, un IoC est difficilement exploitable.',1),
(155,8,43,'Quel registre attribue les adresses IP en Afrique ?','AFRINIC est le registre Internet régional africain.',1),
(156,8,43,'Les journaux de transparence des certificats permettent :','Ils sont publics et utiles pour découvrir des domaines.',1),
(157,8,43,'Plusieurs domaines frauduleux sur une même IP suggèrent :','C''est une hypothèse à confirmer.',1),
(158,8,43,'Qu''est-ce que le typosquattage ?','Il vise à piéger les utilisateurs inattentifs.',1),
(159,8,43,'Quels mécanismes limitent l''usurpation d''adresses e-mail d''un domaine ?','Ils authentifient l''expéditeur.',1),
(160,8,44,'Le chiffrement de bout en bout garantit que :','Le fournisseur n''a pas accès au contenu.',1),
(161,8,44,'Même chiffrées, les communications peuvent révéler :','Les métadonnées restent souvent visibles.',1),
(162,8,44,'Pourquoi vérifier les codes de sécurité d''un contact ?','Cela protège contre l''attaque de l''intercepteur.',1),
(163,8,44,'Quelle méthode MFA résiste le mieux à l''hameçonnage ?','FIDO2 lie l''authentification au site légitime.',1),
(164,8,44,'Quel risque concerne le code par SMS ?','Le SIM swapping permet de recevoir les SMS de la victime.',1),
(165,8,45,'Qu''est-ce qu''un « voyage impossible » ?','Indice fort d''utilisation d''identifiants par un tiers.',1),
(166,8,45,'Une règle de transfert automatique vers l''extérieur créée la nuit est :','C''est un mode opératoire courant d''exfiltration.',1),
(167,8,45,'Avant d''agir sur une alerte, il faut :','Distinguer vrai et faux positif.',1),
(168,8,45,'Quel est l''intérêt du format Sigma ?','Une règle Sigma peut être convertie pour différents SIEM.',1),
(169,8,45,'Que faire avant de déployer une règle de détection ?','Une règle non testée peut noyer les analystes.',1),
(170,8,46,'Pourquoi bloquer automatiquement une liste d''IP sans qualification est-il risqué ?','Les infrastructures partagées génèrent des faux positifs.',1),
(171,8,46,'Un bulletin CTI destiné aux directions générales doit surtout présenter :','Chaque niveau a son lecteur.',1),
(172,9,48,'Quelle est la fonction principale de Maltego ?','Maltego représente des liens entre entités.',1),
(173,9,48,'Un usage légitime de Shodan est :','Il sert notamment à mesurer sa propre exposition.',1),
(174,9,48,'Profiler une personne privée avec ces outils :','C''est une ligne rouge.',1),
(175,9,48,'Quel principe guide le choix d''un outil ?','L''outil découle de la question.',1),
(176,9,48,'Les résultats d''un outil automatisé doivent être :','L''automatisation produit aussi des erreurs.',1),
(177,9,49,'Capturer le trafic d''un réseau dont on n''est pas responsable :','Sans autorisation, c''est une interception illicite.',1),
(178,9,49,'Volatility sert à analyser :','C''est un outil d''analyse mémoire.',1),
(179,9,49,'Sur quoi travaille-t-on lors d''une investigation de support ?','L''original est préservé.',1),
(180,9,49,'Quelle est la première règle d''un laboratoire d''entraînement ?','Sans isolement, un exercice peut déborder sur des systèmes réels.',1),
(181,9,49,'À quoi servent les instantanés (snapshots) ?','Ils permettent de recommencer un exercice dans les mêmes conditions.',1),
(182,9,50,'Un usage légitime des jumelles d''observation est :','Observation de lieux publics uniquement.',1),
(183,9,50,'Poser un traceur GPS sur le véhicule d''autrui est :','C''est une atteinte à la vie privée.',1),
(184,9,50,'Un broyeur de documents relève de :','Il protège contre la récupération de documents jetés.',1),
(185,9,50,'La perte d''un appareil de terrain doit être traitée comme :','Elle peut exposer des données.',1),
(186,9,50,'Avant d''utiliser un drone en mission, il faut :','L''usage des drones est souvent soumis à autorisation.',1),
(187,9,51,'Quel document rédiger avant une investigation outillée ?','Elle formalise finalité, mandat, périmètre et légalité.',1),
(188,9,51,'Le principe de proportionnalité impose de choisir :','L''intrusion doit être minimale.',1),
(189,9,51,'Pourquoi définir une durée de conservation des données ?','Conserver indéfiniment est contraire au droit des données.',1),
(190,9,51,'Qui a documenté publiquement des abus de logiciels espions commerciaux ?','Le Citizen Lab et des consortiums de journalistes notamment.',1),
(191,9,51,'Pourquoi étudier ces affaires dans un cursus éthique ?','L''objectif est défensif et éthique.',1),
(192,9,52,'Avant de soumettre des données à un service en ligne gratuit, il faut :','Les données soumises peuvent être réutilisées par le service.',1),
(193,9,52,'Quel critère d''évaluation d''un outil porte sur la licéité de son usage ?','La légalité de l''usage dépend du droit applicable.',1),
(194,10,54,'Qu''est-ce qui distingue l''intelligence économique de l''espionnage industriel ?','L''IE est légale par définition.',1),
(195,10,54,'Quels sont les trois piliers de l''IE ?','Ce triptyque structure toute démarche.',1),
(196,10,54,'La ZLECAf est :','Elle redéfinit le paysage économique africain.',1),
(197,10,54,'Quel rapport a popularisé le concept d''intelligence économique en France ?','Le rapport Martre a été publié en 1994.',1),
(198,10,54,'Quel enjeu est prioritaire pour l''IE africaine dans la ZLECAf ?','L''IE accompagne la conquête de marchés.',1),
(199,10,55,'La surveillance des journaux officiels relève de la veille :','Lois, décrets et normes.',1),
(200,10,55,'Qu''est-ce qu''un signal faible ?','Il annonce une évolution potentielle.',1);
INSERT INTO `questions` (`id`,`exam_id`,`chapter_id`,`prompt`,`explanation`,`is_active`) VALUES
(201,10,55,'Par quoi commence un dispositif de veille ?','On sait d''abord ce que l''on cherche.',1),
(202,10,55,'Quelle base permet de rechercher des brevets au niveau international ?','L''OMPI propose Patentscope.',1),
(203,10,55,'Que suffit-il pour démarrer une veille ?','La méthode prime sur les moyens.',1),
(204,10,56,'Quel office régional gère la propriété intellectuelle dans l''espace francophone africain ?','L''Organisation africaine de la propriété intellectuelle.',1),
(205,10,56,'Le secret des affaires protège une information si :','La protection doit être organisée.',1),
(206,10,56,'Laquelle est une situation à risque ?','Elle implique un partage important d''informations.',1),
(207,10,56,'Un dépôt de marque auprès de l''OAPI couvre :','L''OAPI fonctionne comme un office unique pour ses membres.',1),
(208,10,56,'Face à une critique en ligne, la première étape est :','Il faut distinguer critique légitime, erreur et campagne.',1),
(209,10,57,'Combien de scénarios une note stratégique présente-t-elle classiquement ?','Trois scénarios contrastés.',1),
(210,10,57,'PESTEL analyse les facteurs :','Un outil d''analyse de l''environnement.',1),
(211,10,57,'Où place-t-on les messages clés ?','Le décideur doit les lire en premier.',1),
(212,10,57,'Dans la méthode des deux axes, combien de scénarios obtient-on ?','Le croisement de deux axes donne quatre quadrants.',1),
(213,10,57,'Qu''est-ce qu''une option stratégique robuste ?','Elle résiste à l''incertitude.',1),
(214,10,58,'Quelle mesure aurait évité le dépôt de la marque par un distributeur ?','La protection doit précéder l''entrée sur un marché.',1),
(215,10,58,'Dans un tableau de bord de veille, chaque axe doit avoir :','C''est ce qui rend la veille opérationnelle.',1),
(216,11,60,'Quel organe de l''UA traite des questions de sécurité ?','Le CPS est l''organe décisionnel en la matière.',1),
(217,11,60,'Quel enjeu caractérise le Golfe de Guinée ?','Piraterie et sécurité portuaire.',1),
(218,11,60,'Pourquoi croiser plusieurs échelles d''analyse ?','Local, national, régional et international interagissent.',1),
(219,11,60,'Quel pilier de l''APSA est chargé de la diplomatie préventive ?','Le Groupe des sages mène la diplomatie préventive.',1),
(220,11,60,'En quelle année l''Agenda 2063 a-t-il été adopté ?','L''Agenda 2063 a été adopté en 2015.',1),
(221,11,61,'Une élection contestée est généralement une cause :','Elle accentue des tensions existantes.',1),
(222,11,61,'Que sont les « connecteurs » dans l''analyse de conflit ?','Ils sont des leviers de résolution.',1),
(223,11,61,'ECOWARN est le système d''alerte précoce de :','Mécanisme de la CEDEAO.',1),
(224,11,61,'Que recense principalement ACLED ?','ACLED est une base d''événements géolocalisés.',1),
(225,11,61,'Une hausse des événements dans une base peut aussi refléter :','La couverture des sources influence les données.',1),
(226,11,62,'Le risque pays dépend :','Un même pays présente des risques différents selon les projets.',1),
(227,11,62,'La sécurité des contrats relève de la dimension :','Elle concerne le cadre légal et judiciaire.',1),
(228,11,62,'Pourquoi analyser les tendances ?','La trajectoire compte autant que la situation présente.',1),
(229,11,62,'Que signifie ESG ?','Trois familles de critères extra-financiers.',1),
(230,11,62,'Pourquoi le risque social est-il un risque opérationnel ?','Conflits et recours peuvent arrêter un projet.',1),
(231,11,63,'Colorier toute une province en rouge à partir d''incidents localisés est une erreur de :','Le risque doit être représenté à la bonne échelle.',1),
(232,11,63,'Dans une grille de risque pays, la tendance indique :','Une même note peut cacher une amélioration ou une dégradation.',1);
